-- First guarded publication of the 40 Perfect Video lessons in modules 10–12.
-- Existing modules, access grants, progress and attempts stay unchanged.
SET lock_timeout = '5s';

CREATE OR REPLACE FUNCTION academy_private.lesson_validation(p_version uuid)
RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
  v public.academy_lesson_versions;
  errors jsonb := '[]'::jsonb;
  warnings jsonb := '[]'::jsonb;
  n integer;
  kinds text[];
BEGIN
  SELECT * INTO v FROM public.academy_lesson_versions WHERE id=p_version;
  IF NOT FOUND THEN RAISE EXCEPTION 'Version not found'; END IF;

  SELECT count(*),coalesce(array_agg(DISTINCT block_type),'{}')
    INTO n,kinds
  FROM public.academy_lesson_blocks WHERE version_id=p_version;

  IF btrim(v.objective)='' THEN errors:=errors||jsonb_build_array('missing_objective'); END IF;
  IF btrim(v.hook)='' THEN errors:=errors||jsonb_build_array('missing_hook'); END IF;
  IF n<5 THEN errors:=errors||jsonb_build_array('too_few_blocks'); END IF;
  IF NOT (kinds && ARRAY[
    'sequence_sort','matching','image_hotspot','decision_tree','scenario',
    'client_simulation','calculator','prompt_builder','practical_response',
    'reflection','checklist','quiz','homework','submission','flip_cards'
  ]) THEN errors:=errors||jsonb_build_array('missing_interaction'); END IF;
  IF NOT ('quiz'=ANY(kinds)) THEN errors:=errors||jsonb_build_array('missing_knowledge_check'); END IF;
  IF NOT (
    kinds && ARRAY['prompt_builder','practical_response','homework','submission']
    OR (
      EXISTS (
        SELECT 1 FROM public.academy_lessons l
        WHERE l.id=v.academy_lesson_id
          AND l.module_id IN (
            's02-m01','s02-m02','s02-m03','s02-m04','s02-m05','s02-m06',
            's02-m07','s02-m08','s02-m09',
            's02-m10','s02-m11','s02-m12'
          )
      )
      AND kinds && ARRAY[
        'sequence_sort','matching','image_hotspot','decision_tree',
        'scenario','client_simulation','calculator'
      ]
    )
  ) THEN errors:=errors||jsonb_build_array('missing_practice'); END IF;
  IF NOT ('summary'=ANY(kinds)) THEN errors:=errors||jsonb_build_array('missing_summary'); END IF;
  IF EXISTS (
    SELECT 1 FROM public.academy_lesson_blocks b
    WHERE b.version_id=p_version AND b.required AND b.points=0
  ) THEN warnings:=warnings||jsonb_build_array('required_block_has_no_xp'); END IF;
  IF EXISTS (
    SELECT 1
    FROM public.academy_lesson_blocks b
    LEFT JOIN academy_private.lesson_block_keys k ON k.block_id=b.id
    WHERE b.version_id=p_version
      AND b.block_type IN (
        'sequence_sort','matching','image_hotspot','decision_tree','scenario',
        'client_simulation','calculator','quiz'
      )
      AND k.block_id IS NULL
  ) THEN errors:=errors||jsonb_build_array('missing_server_evaluation'); END IF;

  RETURN jsonb_build_object(
    'errors',errors,
    'warnings',warnings,
    'block_count',n,
    'interactive',kinds && ARRAY[
      'sequence_sort','matching','image_hotspot','decision_tree','scenario',
      'client_simulation','calculator','prompt_builder','practical_response',
      'reflection','checklist','quiz','homework','submission','flip_cards'
    ],
    'has_quiz','quiz'=ANY(kinds),
    'has_assignment',kinds && ARRAY['practical_response','homework','submission']
  );
END
$function$;


DO $release$
DECLARE
  payload jsonb := $curriculum$[{"module_id":"s02-m10","lesson_id":"pv10-01","title":"Напиши описание, което помага на човека да намери и разбере видеото","subtitle":"Публикуване с проверено обещание и подходящ канал","objective":"Човек, който не е гледал видеото, разбира какво получава; всички имена, глави и връзки са точни.","hook":"Клиентът търси как се сменя филтър, а описанието казва само „ново видео“.","estimated_minutes":38,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Човек, който не е гледал видеото, разбира какво получава; всички имена, глави и връзки са точни."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Клиентът търси как се сменя филтър, а описанието казва само „ново видео“."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Описанието служи на зрителя след обещанието в заглавието. В първите редове кажи какъв проблем решава клипът и за кого е; добави точни термини от самото видео, глави и връзка към следваща стъпка само когато са полезни. Не повтаряй ключова дума като заклинание и не обещавай несъществуващ резултат."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Преди публикуване провери актуалната функция в своя акаунт, език и регион. Платформен инструмент може да липсва или да измерва друга публика. Запиши целта на видеото, собствеността върху материала, източника на факта и точния път от клипа до полезното действие. Ако каналът не дава обещаната функция, използвай наблюдаем резервен метод и назови ограничението. Не превръщай метрика от една услуга в метрика от друга.\n\nЗа тази задача: Изтрий недоказаните термини; сверявай наименованията с кадъра и с продуктовия лист."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Изслушай видеото и запиши въпроса, на който реално отговаря.\n2. Напиши две конкретни начални изречения с резултат и ограничение.\n3. Добави точни части/модели, глави и източници само след проверка в кадъра.\n4. Отвори описанието на телефон и проследи къде води всеки линк.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Сервиз показва смяна на филтър за точно определен модел. Описанието назовава модела, необходимия инструмент и че процедурата е за изключен уред; линкът сочи съвместимата част, а не произволен магазин.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Поставяш популярни думи за несъвместими модели и линкът води към друг продукт."},"after":{"label":"Как го поправяш","text":"Изтрий недоказаните термини; сверявай наименованията с кадъра и с продуктовия лист."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Поставяш популярни думи за несъвместими модели и линкът води към друг продукт.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Изслушай видеото и запиши въпроса, на който реално отговаря. След него: Добави точни части/модели, глави и източници само след проверка в кадъра.\n\nКорекция: Изтрий недоказаните термини; сверявай наименованията с кадъра и с продуктовия лист.\n\nНови данни, които ще приемеш за успешна поправка: Човек, който не е гледал видеото, разбира какво получава; всички имена, глави и връзки са точни. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Направи описание за свой разрешен клип: два въвеждащи реда, три точни термина, един проверен линк и бележка кое твърдение не можеш да докажеш.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Човек, който не е гледал видеото, разбира какво получава; всички имена, глави и връзки са точни.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Сервиз показва смяна на филтър за точно определен модел. Описанието назовава модела, необходимия инструмент и че процедурата е за изключен уред; линкът сочи съвместимата част, а не произволен магазин.\n\nДоставка: Направи описание за свой разрешен клип: два въвеждащи реда, три точни термина, един проверен линк и бележка кое твърдение не можеш да докажеш.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Човек, който не е гледал видеото, разбира какво получава; всички имена, глави и връзки са точни."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Проверен първоизточник","content":{"body":"YouTube Help — Reach, източници на трафик и CTR: https://support.google.com/youtube/answer/9314355\nПровери текущата версия на функцията преди да повториш стъпките."},"points":0,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Кой първи ред помага на търсещия?","options":[{"id":"a","label":"„Най-доброто видео! Гледай до края!“"},{"id":"b","label":"„Смяна на филтър за модел X: инструмент, стъпки и проверка след монтажа.“"},{"id":"c","label":"Повторение на една ключова дума пет пъти."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: „Смяна на филтър за модел X: инструмент, стъпки и проверка след монтажа.“\n\nПървият слаб ход — „Най-доброто видео! Гледай до края!“ — пропуска тази проверка: Човек, който не е гледал видеото, разбира какво получава; всички имена, глави и връзки са точни. Вторият — Повторение на една ключова дума пет пъти. — оставя този риск: Поставяш популярни думи за несъвместими модели и линкът води към друг продукт. В работна ситуация поправката е: Изтрий недоказаните термини; сверявай наименованията с кадъра и с продуктовия лист. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Клипът не показва монтажа за модел Y, но той е по-търсен. Какво пишеш?","options":[{"id":"a","label":"Променяш заглавието, без да гледаш кадъра."},{"id":"b","label":"Оставяш само доказания модел X и уточняваш границата."},{"id":"c","label":"Добавяш Y за трафик."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Оставяш само доказания модел X и уточняваш границата.\n\nПървият слаб ход — Добавяш Y за трафик. — пропуска тази проверка: Човек, който не е гледал видеото, разбира какво получава; всички имена, глави и връзки са точни. Вторият — Променяш заглавието, без да гледаш кадъра. — оставя този риск: Поставяш популярни думи за несъвместими модели и линкът води към друг продукт. В работна ситуация поправката е: Изтрий недоказаните термини; сверявай наименованията с кадъра и с продуктовия лист. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Кое проверяваш след публикуване?","options":[{"id":"a","label":"Дали зрители от релевантни търсения стигат до клипа и остават за отговора."},{"id":"b","label":"Позиция, обещана от генератор на ключови думи."},{"id":"c","label":"Само броя хаштагове."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Дали зрители от релевантни търсения стигат до клипа и остават за отговора.\n\nПървият слаб ход — Само броя хаштагове. — пропуска тази проверка: Човек, който не е гледал видеото, разбира какво получава; всички имена, глави и връзки са точни. Вторият — Позиция, обещана от генератор на ключови думи. — оставя този риск: Поставяш популярни думи за несъвместими модели и линкът води към друг продукт. В работна ситуация поправката е: Изтрий недоказаните термини; сверявай наименованията с кадъра и с продуктовия лист. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Поставяш популярни думи за несъвместими модели и линкът води към друг продукт. Как продължаваш?","options":[{"id":"a","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"b","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"c","label":"Изтрий недоказаните термини; сверявай наименованията с кадъра и с продуктовия лист."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Изтрий недоказаните термини; сверявай наименованията с кадъра и с продуктовия лист.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Човек, който не е гледал видеото, разбира какво получава; всички имена, глави и връзки са точни. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Поставяш популярни думи за несъвместими модели и линкът води към друг продукт. В работна ситуация поправката е: Изтрий недоказаните термини; сверявай наименованията с кадъра и с продуктовия лист. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s2","text":"Напиши две конкретни начални изречения с резултат и ограничение."},{"id":"s3","text":"Добави точни части/модели, глави и източници само след проверка в кадъра."},{"id":"s4","text":"Отвори описанието на телефон и проследи къде води всеки линк."},{"id":"s1","text":"Изслушай видеото и запиши въпроса, на който реално отговаря."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Изслушай видеото и запиши въпроса, на който реално отговаря.\n2. Напиши две конкретни начални изречения с резултат и ограничение.\n3. Добави точни части/модели, глави и източници само след проверка в кадъра.\n4. Отвори описанието на телефон и проследи къде води всеки линк."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Описанието служи на зрителя след обещанието в заглавието. В първите редове кажи какъв проблем решава клипът и за кого е; добави точни термини от самото видео, глави и връзка към следваща стъпка само когато са полезни. Не повтаряй ключова дума като заклинание и не обещавай несъществуващ резултат.","Изтрий недоказаните термини; сверявай наименованията с кадъра и с продуктовия лист.","Човек, който не е гледал видеото, разбира какво получава; всички имена, глави и връзки са точни."],"nextStep":"Направи описание за свой разрешен клип: два въвеждащи реда, три точни термина, един проверен линк и бележка кое твърдение не можеш да докажеш."},"points":1,"required":true}]},{"module_id":"s02-m10","lesson_id":"pv10-02","title":"Направи thumbnail, който е четим и обещава точния клип","subtitle":"Публикуване с проверено обещание и подходящ канал","objective":"Поне двама разпознават темата и обекта; миниатюрата не приписва на видеото непоказан резултат.","hook":"На голям монитор надписът се чете. В списъка на телефона продуктът е точка.","estimated_minutes":38,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Поне двама разпознават темата и обекта; миниатюрата не приписва на видеото непоказан резултат."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"На голям монитор надписът се чете. В списъка на телефона продуктът е точка."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Миниатюрата трябва да различава видеото в малък размер и да е вярна на съдържанието. Избери един обект или действие, контраст и най-много кратък текст, ако без него смисълът се губи. Заглавието и изображението работят заедно: не дублирай изречението и не инсценирай резултат, който видеото не показва."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Преди публикуване провери актуалната функция в своя акаунт, език и регион. Платформен инструмент може да липсва или да измерва друга публика. Запиши целта на видеото, собствеността върху материала, източника на факта и точния път от клипа до полезното действие. Ако каналът не дава обещаната функция, използвай наблюдаем резервен метод и назови ограничението. Не превръщай метрика от една услуга в метрика от друга.\n\nЗа тази задача: Остави един визуален въпрос и едно конкретно доказателство от клипа; провери на телефон."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Опиши с едно изречение какво зрителят ще види в първата минута.\n2. Избери кадър с ясен обект; направи две композиции с различен акцент.\n3. Смали и двете до размер на мобилен списък и ги покажи без обяснение.\n4. Провери лица, марки, разрешения и точния резултат във видеото.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Пекарна сравнява две техники за глазиране. Едната миниатюра показва апетитен, но чужд десерт; другата показва действителния разрез с четима разлика. Избира втората и пренарежда кадъра, вместо да подменя продукта.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Стрелки, три шрифта и драматична снимка скриват истинския продукт."},"after":{"label":"Как го поправяш","text":"Остави един визуален въпрос и едно конкретно доказателство от клипа; провери на телефон."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Стрелки, три шрифта и драматична снимка скриват истинския продукт.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Опиши с едно изречение какво зрителят ще види в първата минута. След него: Смали и двете до размер на мобилен списък и ги покажи без обяснение.\n\nКорекция: Остави един визуален въпрос и едно конкретно доказателство от клипа; провери на телефон.\n\nНови данни, които ще приемеш за успешна поправка: Поне двама разпознават темата и обекта; миниатюрата не приписва на видеото непоказан резултат. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Направи две миниатюри от собствен материал и запиши какво разчитат трима души за две секунди, без да знаят темата.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Поне двама разпознават темата и обекта; миниатюрата не приписва на видеото непоказан резултат.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Пекарна сравнява две техники за глазиране. Едната миниатюра показва апетитен, но чужд десерт; другата показва действителния разрез с четима разлика. Избира втората и пренарежда кадъра, вместо да подменя продукта.\n\nДоставка: Направи две миниатюри от собствен материал и запиши какво разчитат трима души за две секунди, без да знаят темата.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Поне двама разпознават темата и обекта; миниатюрата не приписва на видеото непоказан резултат."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Проверен първоизточник","content":{"body":"YouTube Help — Test & compare thumbnails: https://support.google.com/youtube/answer/13861714\nПровери текущата версия на функцията преди да повториш стъпките."},"points":0,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Кое е добро обещание в миниатюра?","options":[{"id":"a","label":"Кадър от показаното действие, четим в малък размер."},{"id":"b","label":"Чужда снимка с по-добра храна."},{"id":"c","label":"Пет различни фрази на дребен шрифт."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Кадър от показаното действие, четим в малък размер.\n\nПървият слаб ход — Чужда снимка с по-добра храна. — пропуска тази проверка: Поне двама разпознават темата и обекта; миниатюрата не приписва на видеото непоказан резултат. Вторият — Пет различни фрази на дребен шрифт. — оставя този риск: Стрелки, три шрифта и драматична снимка скриват истинския продукт. В работна ситуация поправката е: Остави един визуален въпрос и едно конкретно доказателство от клипа; провери на телефон. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"CTR расте, но хората напускат веднага. Какъв е първият тест?","options":[{"id":"a","label":"Добавяш още шокиращ текст."},{"id":"b","label":"Сравняваш обещанието на заглавието и миниатюрата с началните кадри."},{"id":"c","label":"Заключаваш, че видеото е отлично само по CTR."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Сравняваш обещанието на заглавието и миниатюрата с началните кадри.\n\nПървият слаб ход — Добавяш още шокиращ текст. — пропуска тази проверка: Поне двама разпознават темата и обекта; миниатюрата не приписва на видеото непоказан резултат. Вторият — Заключаваш, че видеото е отлично само по CTR. — оставя този риск: Стрелки, три шрифта и драматична снимка скриват истинския продукт. В работна ситуация поправката е: Остави един визуален въпрос и едно конкретно доказателство от клипа; провери на телефон. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Как сравняваш версиите?","options":[{"id":"a","label":"Публикуваш два различни клипа и приемаш, че аудиториите са еднакви."},{"id":"b","label":"При наличен вграден тест гледаш резултат и гледане, не само кликове; иначе отчитай източниците на трафик."},{"id":"c","label":"Обявяваш победител след три показвания."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: При наличен вграден тест гледаш резултат и гледане, не само кликове; иначе отчитай източниците на трафик.\n\nПървият слаб ход — Обявяваш победител след три показвания. — пропуска тази проверка: Поне двама разпознават темата и обекта; миниатюрата не приписва на видеото непоказан резултат. Вторият — Публикуваш два различни клипа и приемаш, че аудиториите са еднакви. — оставя този риск: Стрелки, три шрифта и драматична снимка скриват истинския продукт. В работна ситуация поправката е: Остави един визуален въпрос и едно конкретно доказателство от клипа; провери на телефон. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Стрелки, три шрифта и драматична снимка скриват истинския продукт. Как продължаваш?","options":[{"id":"a","label":"Остави един визуален въпрос и едно конкретно доказателство от клипа; провери на телефон."},{"id":"b","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"c","label":"Продължаваш без проверка и наричаш тази версия окончателна."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Остави един визуален въпрос и едно конкретно доказателство от клипа; провери на телефон.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Поне двама разпознават темата и обекта; миниатюрата не приписва на видеото непоказан резултат. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Стрелки, три шрифта и драматична снимка скриват истинския продукт. В работна ситуация поправката е: Остави един визуален въпрос и едно конкретно доказателство от клипа; провери на телефон. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s2","text":"Избери кадър с ясен обект; направи две композиции с различен акцент."},{"id":"s1","text":"Опиши с едно изречение какво зрителят ще види в първата минута."},{"id":"s4","text":"Провери лица, марки, разрешения и точния резултат във видеото."},{"id":"s3","text":"Смали и двете до размер на мобилен списък и ги покажи без обяснение."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Опиши с едно изречение какво зрителят ще види в първата минута.\n2. Избери кадър с ясен обект; направи две композиции с различен акцент.\n3. Смали и двете до размер на мобилен списък и ги покажи без обяснение.\n4. Провери лица, марки, разрешения и точния резултат във видеото."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Миниатюрата трябва да различава видеото в малък размер и да е вярна на съдържанието. Избери един обект или действие, контраст и най-много кратък текст, ако без него смисълът се губи. Заглавието и изображението работят заедно: не дублирай изречението и не инсценирай резултат, който видеото не показва.","Остави един визуален въпрос и едно конкретно доказателство от клипа; провери на телефон.","Поне двама разпознават темата и обекта; миниатюрата не приписва на видеото непоказан резултат."],"nextStep":"Направи две миниатюри от собствен материал и запиши какво разчитат трима души за две секунди, без да знаят темата."},"points":1,"required":true}]},{"module_id":"s02-m10","lesson_id":"pv10-03","title":"Избери час за публикуване по данни, не по суеверие","subtitle":"Публикуване с проверено обещание и подходящ канал","objective":"Решението за следващ час стъпва на записана хипотеза и съпоставими данни, без обещание за гарантиран пик.","hook":"Някой обещава „магическия час“ за публикуване, без да е виждал твоята аудитория.","estimated_minutes":36,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Решението за следващ час стъпва на записана хипотеза и съпоставими данни, без обещание за гарантиран пик."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Някой обещава „магическия час“ за публикуване, без да е виждал твоята аудитория."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Часът е оперативно решение, не гаранция за разпространение. Използвай собствените данни за активност, география и навици; съобрази кога можеш да отговаряш и дали съдържанието е навременно. При малка аудитория наблюденията са шумни: сравнявай подобни видеа през достатъчно време и не сменяй едновременно тема, формат и час."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Преди публикуване провери актуалната функция в своя акаунт, език и регион. Платформен инструмент може да липсва или да измерва друга публика. Запиши целта на видеото, собствеността върху материала, източника на факта и точния път от клипа до полезното действие. Ако каналът не дава обещаната функция, използвай наблюдаем резервен метод и назови ограничението. Не превръщай метрика от една услуга в метрика от друга.\n\nЗа тази задача: Остави разумен прозорец за данни и отдели влиянието на темата от часа."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Запиши часовата зона и кога конкретните зрители вероятно имат нужда от темата.\n2. Избери две устойчиви публикационни прозорчета от собствените данни.\n3. Пусни сходни по тип клипове с предварително записан график.\n4. След достатъчно наблюдения сравни източници, гледане и реални действия, не само първите минути.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Малка фирма обслужва хора след работно време. Екипът може да отговаря вечер, но не в полунощ. Тества два вечерни прозореца за поредица от сходни демонстрации и запазва бележки за различни теми.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Обявяваш провал петнадесет минути след поста и го изтриваш."},"after":{"label":"Как го поправяш","text":"Остави разумен прозорец за данни и отдели влиянието на темата от часа."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Обявяваш провал петнадесет минути след поста и го изтриваш.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Запиши часовата зона и кога конкретните зрители вероятно имат нужда от темата. След него: Пусни сходни по тип клипове с предварително записан график.\n\nКорекция: Остави разумен прозорец за данни и отдели влиянието на темата от часа.\n\nНови данни, които ще приемеш за успешна поправка: Решението за следващ час стъпва на записана хипотеза и съпоставими данни, без обещание за гарантиран пик. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Създай календар за четири сравними видеа с хипотеза, часова зона, наличен човек за отговори и дата за преглед.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Решението за следващ час стъпва на записана хипотеза и съпоставими данни, без обещание за гарантиран пик.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Малка фирма обслужва хора след работно време. Екипът може да отговаря вечер, но не в полунощ. Тества два вечерни прозореца за поредица от сходни демонстрации и запазва бележки за различни теми.\n\nДоставка: Създай календар за четири сравними видеа с хипотеза, часова зона, наличен човек за отговори и дата за преглед.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Решението за следващ час стъпва на записана хипотеза и съпоставими данни, без обещание за гарантиран пик."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Проверен първоизточник","content":{"body":"YouTube Help — YouTube Analytics: https://support.google.com/youtube/answer/9002587\nПровери текущата версия на функцията преди да повториш стъпките."},"points":0,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Коя хипотеза може да се провери?","options":[{"id":"a","label":"„Часът няма значение, защото клипът е добър.“"},{"id":"b","label":"„Вторник винаги е най-добър за всички.“"},{"id":"c","label":"„Нашите зрители виждат инструкциите след работа; сравняваме два вечерни прозореца.“"}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: „Нашите зрители виждат инструкциите след работа; сравняваме два вечерни прозореца.“\n\nПървият слаб ход — „Вторник винаги е най-добър за всички.“ — пропуска тази проверка: Решението за следващ час стъпва на записана хипотеза и съпоставими данни, без обещание за гарантиран пик. Вторият — „Часът няма значение, защото клипът е добър.“ — оставя този риск: Обявяваш провал петнадесет минути след поста и го изтриваш. В работна ситуация поправката е: Остави разумен прозорец за данни и отдели влиянието на темата от часа. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Един клип се представя зле. Какво правиш?","options":[{"id":"a","label":"Проверяваш тема, източник и период, преди да обвиняваш часа."},{"id":"b","label":"Сменяш всички бъдещи часове заради един пост."},{"id":"c","label":"Добавяш платени гледания, за да докажеш прозореца."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Проверяваш тема, източник и период, преди да обвиняваш часа.\n\nПървият слаб ход — Сменяш всички бъдещи часове заради един пост. — пропуска тази проверка: Решението за следващ час стъпва на записана хипотеза и съпоставими данни, без обещание за гарантиран пик. Вторият — Добавяш платени гледания, за да докажеш прозореца. — оставя този риск: Обявяваш провал петнадесет минути след поста и го изтриваш. В работна ситуация поправката е: Остави разумен прозорец за данни и отдели влиянието на темата от часа. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Коя метрика говори за полезност след публикуване?","options":[{"id":"a","label":"Само минутните показвания."},{"id":"b","label":"Гледане и действия от подходящата аудитория по сравними видеа."},{"id":"c","label":"Броят постове, които качваш на ден."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Гледане и действия от подходящата аудитория по сравними видеа.\n\nПървият слаб ход — Само минутните показвания. — пропуска тази проверка: Решението за следващ час стъпва на записана хипотеза и съпоставими данни, без обещание за гарантиран пик. Вторият — Броят постове, които качваш на ден. — оставя този риск: Обявяваш провал петнадесет минути след поста и го изтриваш. В работна ситуация поправката е: Остави разумен прозорец за данни и отдели влиянието на темата от часа. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Обявяваш провал петнадесет минути след поста и го изтриваш. Как продължаваш?","options":[{"id":"a","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"b","label":"Остави разумен прозорец за данни и отдели влиянието на темата от часа."},{"id":"c","label":"Продължаваш без проверка и наричаш тази версия окончателна."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Остави разумен прозорец за данни и отдели влиянието на темата от часа.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Решението за следващ час стъпва на записана хипотеза и съпоставими данни, без обещание за гарантиран пик. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Обявяваш провал петнадесет минути след поста и го изтриваш. В работна ситуация поправката е: Остави разумен прозорец за данни и отдели влиянието на темата от часа. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s4","text":"След достатъчно наблюдения сравни източници, гледане и реални действия, не само първите минути."},{"id":"s1","text":"Запиши часовата зона и кога конкретните зрители вероятно имат нужда от темата."},{"id":"s2","text":"Избери две устойчиви публикационни прозорчета от собствените данни."},{"id":"s3","text":"Пусни сходни по тип клипове с предварително записан график."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Запиши часовата зона и кога конкретните зрители вероятно имат нужда от темата.\n2. Избери две устойчиви публикационни прозорчета от собствените данни.\n3. Пусни сходни по тип клипове с предварително записан график.\n4. След достатъчно наблюдения сравни източници, гледане и реални действия, не само първите минути."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Часът е оперативно решение, не гаранция за разпространение. Използвай собствените данни за активност, география и навици; съобрази кога можеш да отговаряш и дали съдържанието е навременно. При малка аудитория наблюденията са шумни: сравнявай подобни видеа през достатъчно време и не сменяй едновременно тема, формат и час.","Остави разумен прозорец за данни и отдели влиянието на темата от часа.","Решението за следващ час стъпва на записана хипотеза и съпоставими данни, без обещание за гарантиран пик."],"nextStep":"Създай календар за четири сравними видеа с хипотеза, часова зона, наличен човек за отговори и дата за преглед."},"points":1,"required":true}]},{"module_id":"s02-m10","lesson_id":"pv10-04","title":"Подреди плейлист като следваща стъпка, не като склад","subtitle":"Публикуване с проверено обещание и подходящ канал","objective":"Редът може да бъде обяснен с нуждите на един зрител; всеки следващ клип добавя умение, а не повтаря темата.","hook":"След полезен урок зрителят попада в плейлист с несвързани стари реклами.","estimated_minutes":36,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Редът може да бъде обяснен с нуждите на един зрител; всеки следващ клип добавя умение, а не повтаря темата."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"След полезен урок зрителят попада в плейлист с несвързани стари реклами."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Плейлистът е маршрут към следващ въпрос. Подреди вход, междинна задача и напреднала работа, така че човекът да знае какво ще може след всяко видео. Общата тема не е достатъчна; провери прехода между две съседни видеа, наличните права и дали остарялата инструкция още е вярна."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Преди публикуване провери актуалната функция в своя акаунт, език и регион. Платформен инструмент може да липсва или да измерва друга публика. Запиши целта на видеото, собствеността върху материала, източника на факта и точния път от клипа до полезното действие. Ако каналът не дава обещаната функция, използвай наблюдаем резервен метод и назови ограничението. Не превръщай метрика от една услуга в метрика от друга.\n\nЗа тази задача: Извади видеата, които прекъсват задачата; сложи ги в отделен справочник."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Избери една ситуация на зрителя, например първо видео за малък бизнес.\n2. Нареди три до пет клипа по зависимост на задачите, не по дата.\n3. Пиши кратко описание на маршрута и обнови следващите връзки.\n4. Изгледай края на всеки клип и началото на следващия като нов зрител.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Школа по видео поставя първо избор на задача, после звук, после експортиране; клип за скъп обектив се премества извън маршрута за начинаещи.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Категория „Всички наши клипове“ смесва нива и не казва какво следва."},"after":{"label":"Как го поправяш","text":"Извади видеата, които прекъсват задачата; сложи ги в отделен справочник."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Категория „Всички наши клипове“ смесва нива и не казва какво следва.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Избери една ситуация на зрителя, например първо видео за малък бизнес. След него: Пиши кратко описание на маршрута и обнови следващите връзки.\n\nКорекция: Извади видеата, които прекъсват задачата; сложи ги в отделен справочник.\n\nНови данни, които ще приемеш за успешна поправка: Редът може да бъде обяснен с нуждите на един зрител; всеки следващ клип добавя умение, а не повтаря темата. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Направи плейлист от четири съществуващи или планирани видеа и напиши какъв въпрос води зрителя от всяко към следващото.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Редът може да бъде обяснен с нуждите на един зрител; всеки следващ клип добавя умение, а не повтаря темата.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Школа по видео поставя първо избор на задача, после звук, после експортиране; клип за скъп обектив се премества извън маршрута за начинаещи.\n\nДоставка: Направи плейлист от четири съществуващи или планирани видеа и напиши какъв въпрос води зрителя от всяко към следващото.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Редът може да бъде обяснен с нуждите на един зрител; всеки следващ клип добавя умение, а не повтаря темата."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Проверен първоизточник","content":{"body":"YouTube Help — YouTube Analytics: https://support.google.com/youtube/answer/9002587\nПровери текущата версия на функцията преди да повториш стъпките."},"points":0,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Какъв ред е смислен?","options":[{"id":"a","label":"По дата, независимо от темата."},{"id":"b","label":"По брой гледания, независимо от нивото."},{"id":"c","label":"Въпрос → основно действие → проверка → следваща задача."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Въпрос → основно действие → проверка → следваща задача.\n\nПървият слаб ход — По дата, независимо от темата. — пропуска тази проверка: Редът може да бъде обяснен с нуждите на един зрител; всеки следващ клип добавя умение, а не повтаря темата. Вторият — По брой гледания, независимо от нивото. — оставя този риск: Категория „Всички наши клипове“ смесва нива и не казва какво следва. В работна ситуация поправката е: Извади видеата, които прекъсват задачата; сложи ги в отделен справочник. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Вторият клип изисква термин, който се обяснява чак в четвъртия. Какво правиш?","options":[{"id":"a","label":"Изтриваш термина от описанието, но не от видеото."},{"id":"b","label":"Оставяш зрителя да търси сам."},{"id":"c","label":"Променяш реда или добавяш ясна връзка към предварителното обяснение."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Променяш реда или добавяш ясна връзка към предварителното обяснение.\n\nПървият слаб ход — Оставяш зрителя да търси сам. — пропуска тази проверка: Редът може да бъде обяснен с нуждите на един зрител; всеки следващ клип добавя умение, а не повтаря темата. Вторият — Изтриваш термина от описанието, но не от видеото. — оставя този риск: Категория „Всички наши клипове“ смесва нива и не казва какво следва. В работна ситуация поправката е: Извади видеата, които прекъсват задачата; сложи ги в отделен справочник. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Как разбираш дали маршрутът работи?","options":[{"id":"a","label":"Проверяваш дали зрители преминават към следващото видео и дали задачата остава ясна."},{"id":"b","label":"Само общия брой клипове."},{"id":"c","label":"Само дължината на описанието."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Проверяваш дали зрители преминават към следващото видео и дали задачата остава ясна.\n\nПървият слаб ход — Само общия брой клипове. — пропуска тази проверка: Редът може да бъде обяснен с нуждите на един зрител; всеки следващ клип добавя умение, а не повтаря темата. Вторият — Само дължината на описанието. — оставя този риск: Категория „Всички наши клипове“ смесва нива и не казва какво следва. В работна ситуация поправката е: Извади видеата, които прекъсват задачата; сложи ги в отделен справочник. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Категория „Всички наши клипове“ смесва нива и не казва какво следва. Как продължаваш?","options":[{"id":"a","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"b","label":"Извади видеата, които прекъсват задачата; сложи ги в отделен справочник."},{"id":"c","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Извади видеата, които прекъсват задачата; сложи ги в отделен справочник.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Редът може да бъде обяснен с нуждите на един зрител; всеки следващ клип добавя умение, а не повтаря темата. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Категория „Всички наши клипове“ смесва нива и не казва какво следва. В работна ситуация поправката е: Извади видеата, които прекъсват задачата; сложи ги в отделен справочник. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s4","text":"Изгледай края на всеки клип и началото на следващия като нов зрител."},{"id":"s3","text":"Пиши кратко описание на маршрута и обнови следващите връзки."},{"id":"s2","text":"Нареди три до пет клипа по зависимост на задачите, не по дата."},{"id":"s1","text":"Избери една ситуация на зрителя, например първо видео за малък бизнес."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Избери една ситуация на зрителя, например първо видео за малък бизнес.\n2. Нареди три до пет клипа по зависимост на задачите, не по дата.\n3. Пиши кратко описание на маршрута и обнови следващите връзки.\n4. Изгледай края на всеки клип и началото на следващия като нов зрител."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Плейлистът е маршрут към следващ въпрос. Подреди вход, междинна задача и напреднала работа, така че човекът да знае какво ще може след всяко видео. Общата тема не е достатъчна; провери прехода между две съседни видеа, наличните права и дали остарялата инструкция още е вярна.","Извади видеата, които прекъсват задачата; сложи ги в отделен справочник.","Редът може да бъде обяснен с нуждите на един зрител; всеки следващ клип добавя умение, а не повтаря темата."],"nextStep":"Направи плейлист от четири съществуващи или планирани видеа и напиши какъв въпрос води зрителя от всяко към следващото."},"points":1,"required":true}]},{"module_id":"s02-m10","lesson_id":"pv10-05","title":"Проведи честен тест на заглавие и миниатюра","subtitle":"Публикуване с проверено обещание и подходящ канал","objective":"Можеш да кажеш какво е проверено и какво остава неизвестно; победителят не е избран само по първите кликове.","hook":"Сменил си заглавие, миниатюра и първите кадри наведнъж. После не знаеш кое помогна.","estimated_minutes":38,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Можеш да кажеш какво е проверено и какво остава неизвестно; победителят не е избран само по първите кликове."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Сменил си заглавие, миниатюра и първите кадри наведнъж. После не знаеш кое помогна."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Тестът започва с въпрос, а не с обявяване на победител. При вграден експеримент спазвай наличните опции и гледай метриката, която платформата сравнява. При последователна смяна аудиторията и източникът на показванията също се сменят; запиши ограниченията. Целта е съответствие между обещание и гледане, не само любопитен клик."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Преди публикуване провери актуалната функция в своя акаунт, език и регион. Платформен инструмент може да липсва или да измерва друга публика. Запиши целта на видеото, собствеността върху материала, източника на факта и точния път от клипа до полезното действие. Ако каналът не дава обещаната функция, използвай наблюдаем резервен метод и назови ограничението. Не превръщай метрика от една услуга в метрика от друга.\n\nЗа тази задача: Отложи извода при малка извадка и отдели промените в аудиторията от промените в опаковката."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Формулирай една разлика: например показан продукт срещу лице.\n2. Подготви две честни версии на същото обещание и архивирай изходните файлове.\n3. Провери дали каналът има вграден Test & compare и запиши правилата му.\n4. Отчети гледане, източници и достатъчен период; вземи следващото решение с бележка за несигурността.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Канал за ремонт сравнява две реални снимки на същата смяна на част. В единия вариант се вижда инструментът, в другия крайният резултат. Екипът записва и дали търсене или начална страница е донесла показванията.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Три клика в първия час се превръщат в „доказан победител“."},"after":{"label":"Как го поправяш","text":"Отложи извода при малка извадка и отдели промените в аудиторията от промените в опаковката."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Три клика в първия час се превръщат в „доказан победител“.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Формулирай една разлика: например показан продукт срещу лице. След него: Провери дали каналът има вграден Test & compare и запиши правилата му.\n\nКорекция: Отложи извода при малка извадка и отдели промените в аудиторията от промените в опаковката.\n\nНови данни, които ще приемеш за успешна поправка: Можеш да кажеш какво е проверено и какво остава неизвестно; победителят не е избран само по първите кликове. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Напиши едностранен протокол: хипотеза, две версии, какво остава еднакво, период, наблюдавана метрика и правило за спиране.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Можеш да кажеш какво е проверено и какво остава неизвестно; победителят не е избран само по първите кликове.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Канал за ремонт сравнява две реални снимки на същата смяна на част. В единия вариант се вижда инструментът, в другия крайният резултат. Екипът записва и дали търсене или начална страница е донесла показванията.\n\nДоставка: Напиши едностранен протокол: хипотеза, две версии, какво остава еднакво, период, наблюдавана метрика и правило за спиране.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Можеш да кажеш какво е проверено и какво остава неизвестно; победителят не е избран само по първите кликове."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Проверен първоизточник","content":{"body":"YouTube Help — Test & compare thumbnails: https://support.google.com/youtube/answer/13861714\nПровери текущата версия на функцията преди да повториш стъпките."},"points":0,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Кое е честно сравнение?","options":[{"id":"a","label":"Един клип с две верни опаковки и предварително избрана метрика."},{"id":"b","label":"Смяна на всичко без запис на версия."},{"id":"c","label":"Два клипа с различна тема и публика."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Един клип с две верни опаковки и предварително избрана метрика.\n\nПървият слаб ход — Два клипа с различна тема и публика. — пропуска тази проверка: Можеш да кажеш какво е проверено и какво остава неизвестно; победителят не е избран само по първите кликове. Вторият — Смяна на всичко без запис на версия. — оставя този риск: Три клика в първия час се превръщат в „доказан победител“. В работна ситуация поправката е: Отложи извода при малка извадка и отдели промените в аудиторията от промените в опаковката. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"CTR е по-висок, но гледането след клика е по-слабо. Какво проверяваш?","options":[{"id":"a","label":"Обявяваш победител само по CTR."},{"id":"b","label":"Премахваш първите 30 секунди без преглед."},{"id":"c","label":"Дали опаковката е обещала повече от видеото и как платформата отчита теста."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Дали опаковката е обещала повече от видеото и как платформата отчита теста.\n\nПървият слаб ход — Обявяваш победител само по CTR. — пропуска тази проверка: Можеш да кажеш какво е проверено и какво остава неизвестно; победителят не е избран само по първите кликове. Вторият — Премахваш първите 30 секунди без преглед. — оставя този риск: Три клика в първия час се превръщат в „доказан победител“. В работна ситуация поправката е: Отложи извода при малка извадка и отдели промените в аудиторията от промените в опаковката. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Кога резултатът е неубедителен?","options":[{"id":"a","label":"Когато не харесваш числото."},{"id":"b","label":"Когато вариантите изглеждат различно."},{"id":"c","label":"При малко данни, смяна на източник на трафик или нееднаква аудитория."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: При малко данни, смяна на източник на трафик или нееднаква аудитория.\n\nПървият слаб ход — Когато вариантите изглеждат различно. — пропуска тази проверка: Можеш да кажеш какво е проверено и какво остава неизвестно; победителят не е избран само по първите кликове. Вторият — Когато не харесваш числото. — оставя този риск: Три клика в първия час се превръщат в „доказан победител“. В работна ситуация поправката е: Отложи извода при малка извадка и отдели промените в аудиторията от промените в опаковката. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Три клика в първия час се превръщат в „доказан победител“. Как продължаваш?","options":[{"id":"a","label":"Отложи извода при малка извадка и отдели промените в аудиторията от промените в опаковката."},{"id":"b","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"c","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Отложи извода при малка извадка и отдели промените в аудиторията от промените в опаковката.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Можеш да кажеш какво е проверено и какво остава неизвестно; победителят не е избран само по първите кликове. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Три клика в първия час се превръщат в „доказан победител“. В работна ситуация поправката е: Отложи извода при малка извадка и отдели промените в аудиторията от промените в опаковката. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s2","text":"Подготви две честни версии на същото обещание и архивирай изходните файлове."},{"id":"s3","text":"Провери дали каналът има вграден Test & compare и запиши правилата му."},{"id":"s4","text":"Отчети гледане, източници и достатъчен период; вземи следващото решение с бележка за несигурността."},{"id":"s1","text":"Формулирай една разлика: например показан продукт срещу лице."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Формулирай една разлика: например показан продукт срещу лице.\n2. Подготви две честни версии на същото обещание и архивирай изходните файлове.\n3. Провери дали каналът има вграден Test & compare и запиши правилата му.\n4. Отчети гледане, източници и достатъчен период; вземи следващото решение с бележка за несигурността."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Тестът започва с въпрос, а не с обявяване на победител. При вграден експеримент спазвай наличните опции и гледай метриката, която платформата сравнява. При последователна смяна аудиторията и източникът на показванията също се сменят; запиши ограниченията. Целта е съответствие между обещание и гледане, не само любопитен клик.","Отложи извода при малка извадка и отдели промените в аудиторията от промените в опаковката.","Можеш да кажеш какво е проверено и какво остава неизвестно; победителят не е избран само по първите кликове."],"nextStep":"Напиши едностранен протокол: хипотеза, две версии, какво остава еднакво, период, наблюдавана метрика и правило за спиране."},"points":1,"required":true}]},{"module_id":"s02-m10","lesson_id":"pv10-06","title":"Закрепи коментар, който помага на разговора","subtitle":"Публикуване с проверено обещание и подходящ канал","objective":"Коментарът добавя проверима информация или задава смислен въпрос; няма обещание или линк без основание.","hook":"Под видео за цени коментарът „Пишете ни“ оставя най-важния въпрос без отговор.","estimated_minutes":34,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Коментарът добавя проверима информация или задава смислен въпрос; няма обещание или линк без основание."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Под видео за цени коментарът „Пишете ни“ оставя най-важния въпрос без отговор."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Закрепеният коментар може да допълни инструкция, да уточни промяна или да покани към конкретен разговор. Той не е място за прикриване на грешка във видеото. Отговори на често срещаното объркване, отбележи дата при промяна и следи въпросите. Линк или покана се поставя само ако води към следваща полезна стъпка."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Преди публикуване провери актуалната функция в своя акаунт, език и регион. Платформен инструмент може да липсва или да измерва друга публика. Запиши целта на видеото, собствеността върху материала, източника на факта и точния път от клипа до полезното действие. Ако каналът не дава обещаната функция, използвай наблюдаем резервен метод и назови ограничението. Не превръщай метрика от една услуга в метрика от друга.\n\nЗа тази задача: Свери фактите с отговорния човек и актуализирай видеото или описанието, ако старото твърдение остава видимо."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Прегледай първите реални въпроси и избери един повтарящ се проблем.\n2. Напиши кратък отговор с уточнение и проверим източник.\n3. Добави конкретен въпрос, който позволява отговор с опит, не с емоджи.\n4. Следи коментарите и поправи същинското видео или описанието при системно объркване.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Производител показва опаковка 100 г. След въпрос за алергени закрепва насочване към точния етикет и канал за продуктова информация; не обещава, че всички варианти имат еднакъв състав.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Закрепяш спорна информация без дата и отговаряш с рекламен шаблон на всеки човек."},"after":{"label":"Как го поправяш","text":"Свери фактите с отговорния човек и актуализирай видеото или описанието, ако старото твърдение остава видимо."}},"points":2,"required":true},{"position":7,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Напиши два варианта за закрепен коментар към свой клип: един за уточнение и един за конкретен въпрос. Избери кой решава истински проблем.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Коментарът добавя проверима информация или задава смислен въпрос; няма обещание или линк без основание.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":9,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Кога е полезно да закрепиш коментар?","options":[{"id":"a","label":"Когато прикриваш грешка, без да я поправиш."},{"id":"b","label":"Когато изяснява повтарящ се въпрос или актуализация с източник."},{"id":"c","label":"Когато искаш само „пишете +“."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Когато изяснява повтарящ се въпрос или актуализация с източник.\n\nПървият слаб ход — Когато искаш само „пишете +“. — пропуска тази проверка: Коментарът добавя проверима информация или задава смислен въпрос; няма обещание или линк без основание. Вторият — Когато прикриваш грешка, без да я поправиш. — оставя този риск: Закрепяш спорна информация без дата и отговаряш с рекламен шаблон на всеки човек. В работна ситуация поправката е: Свери фактите с отговорния човек и актуализирай видеото или описанието, ако старото твърдение остава видимо. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Инструкцията в клипа вече е неточна. Как действаш?","options":[{"id":"a","label":"Маркираш промяната и коригираш основния материал, когато е възможно."},{"id":"b","label":"Изтриваш всички въпроси."},{"id":"c","label":"Разчиташ никой да не забележи."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Маркираш промяната и коригираш основния материал, когато е възможно.\n\nПървият слаб ход — Разчиташ никой да не забележи. — пропуска тази проверка: Коментарът добавя проверима информация или задава смислен въпрос; няма обещание или линк без основание. Вторият — Изтриваш всички въпроси. — оставя този риск: Закрепяш спорна информация без дата и отговаряш с рекламен шаблон на всеки човек. В работна ситуация поправката е: Свери фактите с отговорния човек и актуализирай видеото или описанието, ако старото твърдение остава видимо. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Какво наблюдаваш?","options":[{"id":"a","label":"Само броя емоджита."},{"id":"b","label":"Колко пъти си написал един и същ линк."},{"id":"c","label":"Дали конкретните въпроси получават отговор и объркването намалява."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Дали конкретните въпроси получават отговор и объркването намалява.\n\nПървият слаб ход — Само броя емоджита. — пропуска тази проверка: Коментарът добавя проверима информация или задава смислен въпрос; няма обещание или линк без основание. Вторият — Колко пъти си написал един и същ линк. — оставя този риск: Закрепяш спорна информация без дата и отговаряш с рекламен шаблон на всеки човек. В работна ситуация поправката е: Свери фактите с отговорния човек и актуализирай видеото или описанието, ако старото твърдение остава видимо. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Закрепяш спорна информация без дата и отговаряш с рекламен шаблон на всеки човек. Как продължаваш?","options":[{"id":"a","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"b","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"c","label":"Свери фактите с отговорния човек и актуализирай видеото или описанието, ако старото твърдение остава видимо."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Свери фактите с отговорния човек и актуализирай видеото или описанието, ако старото твърдение остава видимо.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Коментарът добавя проверима информация или задава смислен въпрос; няма обещание или линк без основание. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Закрепяш спорна информация без дата и отговаряш с рекламен шаблон на всеки човек. В работна ситуация поправката е: Свери фактите с отговорния човек и актуализирай видеото или описанието, ако старото твърдение остава видимо. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s2","text":"Напиши кратък отговор с уточнение и проверим източник."},{"id":"s1","text":"Прегледай първите реални въпроси и избери един повтарящ се проблем."},{"id":"s4","text":"Следи коментарите и поправи същинското видео или описанието при системно объркване."},{"id":"s3","text":"Добави конкретен въпрос, който позволява отговор с опит, не с емоджи."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Прегледай първите реални въпроси и избери един повтарящ се проблем.\n2. Напиши кратък отговор с уточнение и проверим източник.\n3. Добави конкретен въпрос, който позволява отговор с опит, не с емоджи.\n4. Следи коментарите и поправи същинското видео или описанието при системно объркване."},"scoring":{"mode":"exact_order"}},{"position":14,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Закрепеният коментар може да допълни инструкция, да уточни промяна или да покани към конкретен разговор. Той не е място за прикриване на грешка във видеото. Отговори на често срещаното объркване, отбележи дата при промяна и следи въпросите. Линк или покана се поставя само ако води към следваща полезна стъпка.","Свери фактите с отговорния човек и актуализирай видеото или описанието, ако старото твърдение остава видимо.","Коментарът добавя проверима информация или задава смислен въпрос; няма обещание или линк без основание."],"nextStep":"Напиши два варианта за закрепен коментар към свой клип: един за уточнение и един за конкретен въпрос. Избери кой решава истински проблем."},"points":1,"required":true}]},{"module_id":"s02-m10","lesson_id":"pv10-07","title":"Провери търсене в TikTok, преди да избереш тема","subtitle":"Публикуване с проверено обещание и подходящ канал","objective":"Видеото отговаря на реално формулиран въпрос; източникът на темата и границите на отговора са записани.","hook":"Търсиш тема в TikTok и приемаш всеки популярен термин за поръчка от твоята аудитория.","estimated_minutes":38,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Видеото отговаря на реално формулиран въпрос; източникът на темата и границите на отговора са записани."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Търсиш тема в TikTok и приемаш всеки популярен термин за поръчка от твоята аудитория."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Creator Search Insights показва сигнали за търсене, а не гаранция за успех. Разгледай темата, намерението зад въпроса, съществуващите отговори и дали имаш собствен опит или достъп до доказателство. Наличността на функцията може да зависи от акаунт и регион; обикновено търсене и клиентски въпроси остават валиден резервен източник."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Преди публикуване провери актуалната функция в своя акаунт, език и регион. Платформен инструмент може да липсва или да измерва друга публика. Запиши целта на видеото, собствеността върху материала, източника на факта и точния път от клипа до полезното действие. Ако каналът не дава обещаната функция, използвай наблюдаем резервен метод и назови ограничението. Не превръщай метрика от една услуга в метрика от друга.\n\nЗа тази задача: Съгласувай точния въпрос с първите кадри; ако нямаш компетентност, избери друг въпрос."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Извади три въпроса, които хората формулират с конкретни думи.\n2. За всеки провери видимите резултати и какво остава неясно.\n3. Избери само въпрос, на който можеш да отговориш с собствен пример.\n4. Планирай отварящ кадър, демонстрация и проверима следваща стъпка.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Сервиз за велосипеди вижда търсене за скърцане при спиране. Вместо общ „трик“ показва две различни причини и кога човек трябва да спре да кара и да потърси специалист.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Избираш търсена тема, но снимаш отговор за различен проблем."},"after":{"label":"Как го поправяш","text":"Съгласувай точния въпрос с първите кадри; ако нямаш компетентност, избери друг въпрос."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Избираш търсена тема, но снимаш отговор за различен проблем.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Извади три въпроса, които хората формулират с конкретни думи. След него: Избери само въпрос, на който можеш да отговориш с собствен пример.\n\nКорекция: Съгласувай точния въпрос с първите кадри; ако нямаш компетентност, избери друг въпрос.\n\nНови данни, които ще приемеш за успешна поправка: Видеото отговаря на реално формулиран въпрос; източникът на темата и границите на отговора са записани. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Събери три сигнала за тема с дата и източник; напиши за един 20-секундна демонстрация и какво няма да твърдиш.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Видеото отговаря на реално формулиран въпрос; източникът на темата и границите на отговора са записани.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Сервиз за велосипеди вижда търсене за скърцане при спиране. Вместо общ „трик“ показва две различни причини и кога човек трябва да спре да кара и да потърси специалист.\n\nДоставка: Събери три сигнала за тема с дата и източник; напиши за един 20-секундна демонстрация и какво няма да твърдиш.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Видеото отговаря на реално формулиран въпрос; източникът на темата и границите на отговора са записани."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Проверен първоизточник","content":{"body":"TikTok Help — Creator Search Insights: https://support.tiktok.com/en/using-tiktok/growing-your-audience/creator-search-insights\nПровери текущата версия на функцията преди да повториш стъпките."},"points":0,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Как тълкуваш Search Insights?","options":[{"id":"a","label":"Като гаранция за вирусност."},{"id":"b","label":"Като сигнал за въпроси, който проверяваш срещу съществуващите отговори и опита си."},{"id":"c","label":"Като доказателство, че имаш право да снимаш чуждо видео."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Като сигнал за въпроси, който проверяваш срещу съществуващите отговори и опита си.\n\nПървият слаб ход — Като гаранция за вирусност. — пропуска тази проверка: Видеото отговаря на реално формулиран въпрос; източникът на темата и границите на отговора са записани. Вторият — Като доказателство, че имаш право да снимаш чуждо видео. — оставя този риск: Избираш търсена тема, но снимаш отговор за различен проблем. В работна ситуация поправката е: Съгласувай точния въпрос с първите кадри; ако нямаш компетентност, избери друг въпрос. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Инструментът не е достъпен в твоя акаунт. Какво правиш?","options":[{"id":"a","label":"Спираш всяка тема за месеца."},{"id":"b","label":"Ползваш реални търсения, клиентски въпроси и отбелязваш източника."},{"id":"c","label":"Измисляш данни от функцията."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Ползваш реални търсения, клиентски въпроси и отбелязваш източника.\n\nПървият слаб ход — Измисляш данни от функцията. — пропуска тази проверка: Видеото отговаря на реално формулиран въпрос; източникът на темата и границите на отговора са записани. Вторият — Спираш всяка тема за месеца. — оставя този риск: Избираш търсена тема, но снимаш отговор за различен проблем. В работна ситуация поправката е: Съгласувай точния въпрос с първите кадри; ако нямаш компетентност, избери друг въпрос. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Кой сигнал проверяваш след публикация?","options":[{"id":"a","label":"Дали клипът привлича хора с посочения въпрос и те стигат до отговора."},{"id":"b","label":"Само броя хаштагове."},{"id":"c","label":"Само популярността на думата."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Дали клипът привлича хора с посочения въпрос и те стигат до отговора.\n\nПървият слаб ход — Само популярността на думата. — пропуска тази проверка: Видеото отговаря на реално формулиран въпрос; източникът на темата и границите на отговора са записани. Вторият — Само броя хаштагове. — оставя този риск: Избираш търсена тема, но снимаш отговор за различен проблем. В работна ситуация поправката е: Съгласувай точния въпрос с първите кадри; ако нямаш компетентност, избери друг въпрос. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Избираш търсена тема, но снимаш отговор за различен проблем. Как продължаваш?","options":[{"id":"a","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"b","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"c","label":"Съгласувай точния въпрос с първите кадри; ако нямаш компетентност, избери друг въпрос."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Съгласувай точния въпрос с първите кадри; ако нямаш компетентност, избери друг въпрос.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Видеото отговаря на реално формулиран въпрос; източникът на темата и границите на отговора са записани. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Избираш търсена тема, но снимаш отговор за различен проблем. В работна ситуация поправката е: Съгласувай точния въпрос с първите кадри; ако нямаш компетентност, избери друг въпрос. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s4","text":"Планирай отварящ кадър, демонстрация и проверима следваща стъпка."},{"id":"s1","text":"Извади три въпроса, които хората формулират с конкретни думи."},{"id":"s2","text":"За всеки провери видимите резултати и какво остава неясно."},{"id":"s3","text":"Избери само въпрос, на който можеш да отговориш с собствен пример."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Извади три въпроса, които хората формулират с конкретни думи.\n2. За всеки провери видимите резултати и какво остава неясно.\n3. Избери само въпрос, на който можеш да отговориш с собствен пример.\n4. Планирай отварящ кадър, демонстрация и проверима следваща стъпка."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Creator Search Insights показва сигнали за търсене, а не гаранция за успех. Разгледай темата, намерението зад въпроса, съществуващите отговори и дали имаш собствен опит или достъп до доказателство. Наличността на функцията може да зависи от акаунт и регион; обикновено търсене и клиентски въпроси остават валиден резервен източник.","Съгласувай точния въпрос с първите кадри; ако нямаш компетентност, избери друг въпрос.","Видеото отговаря на реално формулиран въпрос; източникът на темата и границите на отговора са записани."],"nextStep":"Събери три сигнала за тема с дата и източник; напиши за един 20-секундна демонстрация и какво няма да твърдиш."},"points":1,"required":true}]},{"module_id":"s02-m10","lesson_id":"pv10-08","title":"Разграничи личните Reels препоръки от данните за аудиторията","subtitle":"Публикуване с проверено обещание и подходящ канал","objective":"Нито един извод за аудиторията не се основава само на това какво вижда един човек в своя Reels feed.","hook":"Променяш своя Instagram Your Algorithm и твърдиш, че си променил аудиторията на клиента.","estimated_minutes":34,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Нито един извод за аудиторията не се основава само на това какво вижда един човек в своя Reels feed."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Променяш своя Instagram Your Algorithm и твърдиш, че си променил аудиторията на клиента."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Контролите на личните препоръки променят какво виждаш ти; това не е табло за това какво е видяла публиката. За аудиторията използвай наличните Insights на собствения професионален акаунт, въпроси от хора и резултатите от конкретни публикации. Функцията Your Algorithm може да е ограничена по език и регион. Никога не представяй своя feed като извадка от всички зрители."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Преди публикуване провери актуалната функция в своя акаунт, език и регион. Платформен инструмент може да липсва или да измерва друга публика. Запиши целта на видеото, собствеността върху материала, източника на факта и точния път от клипа до полезното действие. Ако каналът не дава обещаната функция, използвай наблюдаем резервен метод и назови ограничението. Не превръщай метрика от една услуга в метрика от друга.\n\nЗа тази задача: Премести извода към измерима публикация и ясно запиши кой акаунт, период и метрика гледаш."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Отдели в бележките „моят feed“ от „данни за нашата публикация“.\n2. Провери дали имаш достъп до Insights и кои периоди/метрики са налични.\n3. Сравни две собствени публикации по формат, тема и цел, без да смесваш reach с полезност.\n4. Назови едно решение, за което данните стигат, и едно, за което не стигат.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Агенция показва на клиент как личният feed на служител се напълнил с автомобили. Вместо „Instagram обича автомобили“, проверява собствения профил, коментарите и поведението под две конкретни видеа.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Извеждаш стратегия за всички от личните си препоръки."},"after":{"label":"Как го поправяш","text":"Премести извода към измерима публикация и ясно запиши кой акаунт, период и метрика гледаш."}},"points":2,"required":true},{"position":7,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Направи едностранично сравнение: личен feed, данни от собствен пост и три реални въпроса; отбележи кое може да се използва за решение.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Нито един извод за аудиторията не се основава само на това какво вижда един човек в своя Reels feed.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":9,"block_key":"reference","block_type":"rich_text","title":"Проверен първоизточник","content":{"body":"Meta — Your Algorithm е контрол на личните препоръки: https://about.fb.com/news/2026/05/new-supervision-tools-parents-insights-teens-algorithm/\nПровери текущата версия на функцията преди да повториш стъпките."},"points":0,"required":false},{"position":10,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Какво показва Your Algorithm?","options":[{"id":"a","label":"Предпочитания за личните препоръки, където функцията е налична."},{"id":"b","label":"Точни интереси на всички последователи."},{"id":"c","label":"Гарантиран начин за повече reach."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Предпочитания за личните препоръки, където функцията е налична.\n\nПървият слаб ход — Точни интереси на всички последователи. — пропуска тази проверка: Нито един извод за аудиторията не се основава само на това какво вижда един човек в своя Reels feed. Вторият — Гарантиран начин за повече reach. — оставя този риск: Извеждаш стратегия за всички от личните си препоръки. В работна ситуация поправката е: Премести извода към измерима публикация и ясно запиши кой акаунт, период и метрика гледаш. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Клиент иска доказателство, че нова тема работи. Какво показваш?","options":[{"id":"a","label":"Скрийншот от твоя feed."},{"id":"b","label":"Резултата от конкретни собствени публикации и ограниченията на данните."},{"id":"c","label":"Общо твърдение за алгоритъма без данни."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Резултата от конкретни собствени публикации и ограниченията на данните.\n\nПървият слаб ход — Скрийншот от твоя feed. — пропуска тази проверка: Нито един извод за аудиторията не се основава само на това какво вижда един човек в своя Reels feed. Вторият — Общо твърдение за алгоритъма без данни. — оставя този риск: Извеждаш стратегия за всички от личните си препоръки. В работна ситуация поправката е: Премести извода към измерима публикация и ясно запиши кой акаунт, период и метрика гледаш. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Какво записваш към анализ?","options":[{"id":"a","label":"Само прогнозирани гледания."},{"id":"b","label":"Акаунт, период, публикация, дефиниция на метриката и ограничение."},{"id":"c","label":"Само любимите си видеа."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Акаунт, период, публикация, дефиниция на метриката и ограничение.\n\nПървият слаб ход — Само любимите си видеа. — пропуска тази проверка: Нито един извод за аудиторията не се основава само на това какво вижда един човек в своя Reels feed. Вторият — Само прогнозирани гледания. — оставя този риск: Извеждаш стратегия за всички от личните си препоръки. В работна ситуация поправката е: Премести извода към измерима публикация и ясно запиши кой акаунт, период и метрика гледаш. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Извеждаш стратегия за всички от личните си препоръки. Как продължаваш?","options":[{"id":"a","label":"Премести извода към измерима публикация и ясно запиши кой акаунт, период и метрика гледаш."},{"id":"b","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"c","label":"Продължаваш без проверка и наричаш тази версия окончателна."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Премести извода към измерима публикация и ясно запиши кой акаунт, период и метрика гледаш.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Нито един извод за аудиторията не се основава само на това какво вижда един човек в своя Reels feed. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Извеждаш стратегия за всички от личните си препоръки. В работна ситуация поправката е: Премести извода към измерима публикация и ясно запиши кой акаунт, период и метрика гледаш. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s4","text":"Назови едно решение, за което данните стигат, и едно, за което не стигат."},{"id":"s3","text":"Сравни две собствени публикации по формат, тема и цел, без да смесваш reach с полезност."},{"id":"s2","text":"Провери дали имаш достъп до Insights и кои периоди/метрики са налични."},{"id":"s1","text":"Отдели в бележките „моят feed“ от „данни за нашата публикация“."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Отдели в бележките „моят feed“ от „данни за нашата публикация“.\n2. Провери дали имаш достъп до Insights и кои периоди/метрики са налични.\n3. Сравни две собствени публикации по формат, тема и цел, без да смесваш reach с полезност.\n4. Назови едно решение, за което данните стигат, и едно, за което не стигат."},"scoring":{"mode":"exact_order"}},{"position":15,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Контролите на личните препоръки променят какво виждаш ти; това не е табло за това какво е видяла публиката. За аудиторията използвай наличните Insights на собствения професионален акаунт, въпроси от хора и резултатите от конкретни публикации. Функцията Your Algorithm може да е ограничена по език и регион. Никога не представяй своя feed като извадка от всички зрители.","Премести извода към измерима публикация и ясно запиши кой акаунт, период и метрика гледаш.","Нито един извод за аудиторията не се основава само на това какво вижда един човек в своя Reels feed."],"nextStep":"Направи едностранично сравнение: личен feed, данни от собствен пост и три реални въпроса; отбележи кое може да се използва за решение."},"points":1,"required":true}]},{"module_id":"s02-m10","lesson_id":"pv10-09","title":"Използвай AI за вариант, но провери факт, образ и права","subtitle":"Публикуване с проверено обещание и подходящ канал","objective":"Крайната версия не добавя несъществуваща характеристика; за всеки актив има произход и отговорник за проверката.","hook":"AI прави по-впечатляващ кадър с детайл, който продуктът всъщност няма.","estimated_minutes":38,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Крайната версия не добавя несъществуваща характеристика; за всеки актив има произход и отговорник за проверката."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"AI прави по-впечатляващ кадър с детайл, който продуктът всъщност няма."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Използвай генериране за вариант на структура, субтитър или композиционна идея, но запази списък с факти, разрешени активи и граници. Свери всяко число, демонстрация, лице и глас с първоизточник и разрешение. Отдели чернова от реален продукт. Проверявай изискванията за обозначаване на съответната платформа преди публикуване, особено при реалистична синтетична сцена."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Преди публикуване провери актуалната функция в своя акаунт, език и регион. Платформен инструмент може да липсва или да измерва друга публика. Запиши целта на видеото, собствеността върху материала, източника на факта и точния път от клипа до полезното действие. Ако каналът не дава обещаната функция, използвай наблюдаем резервен метод и назови ограничението. Не превръщай метрика от една услуга в метрика от друга.\n\nЗа тази задача: Отхвърли недоказаните елементи и запази проверен кадър и разрешенията в досието."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Подготви brief с проверени факти и забранени твърдения.\n2. Поискай два варианта и запази входа и версиите.\n3. Сравни всеки кадър и ред с действителния продукт, права и материали.\n4. Провери обозначенията и направи финален човешки преглед на експорта.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Халва се продава в опаковка 100 г. Генераторът рисува 200 г и несъществуваща съставка. Екипът използва само идеята за фон, връща реалната продуктова снимка и сверява текста с етикета.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Публикуваш визуално убедителна измислица, защото генераторът „познава продукта“."},"after":{"label":"Как го поправяш","text":"Отхвърли недоказаните елементи и запази проверен кадър и разрешенията в досието."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Публикуваш визуално убедителна измислица, защото генераторът „познава продукта“.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Подготви brief с проверени факти и забранени твърдения. След него: Сравни всеки кадър и ред с действителния продукт, права и материали.\n\nКорекция: Отхвърли недоказаните елементи и запази проверен кадър и разрешенията в досието.\n\nНови данни, които ще приемеш за успешна поправка: Крайната версия не добавя несъществуваща характеристика; за всеки актив има произход и отговорник за проверката. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Направи две версии на 15-секунден откъс с разрешен материал; маркирай всеки AI елемент, факт, право и човешка поправка.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Крайната версия не добавя несъществуваща характеристика; за всеки актив има произход и отговорник за проверката.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Халва се продава в опаковка 100 г. Генераторът рисува 200 г и несъществуваща съставка. Екипът използва само идеята за фон, връща реалната продуктова снимка и сверява текста с етикета.\n\nДоставка: Направи две версии на 15-секунден откъс с разрешен материал; маркирай всеки AI елемент, факт, право и човешка поправка.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Крайната версия не добавя несъществуваща характеристика; за всеки актив има произход и отговорник за проверката."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Проверен първоизточник","content":{"body":"YouTube Help — обозначаване на значително променено или синтетично съдържание: https://support.google.com/youtube/answer/14328491\nПровери текущата версия на функцията преди да повториш стъпките."},"points":0,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Коя употреба е безопасна за продукта?","options":[{"id":"a","label":"Лице на реален човек без разрешение."},{"id":"b","label":"Генериран нов етикет с измислени съставки."},{"id":"c","label":"Вариант на композиция, проверен спрямо реалния продукт и права."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Вариант на композиция, проверен спрямо реалния продукт и права.\n\nПървият слаб ход — Генериран нов етикет с измислени съставки. — пропуска тази проверка: Крайната версия не добавя несъществуваща характеристика; за всеки актив има произход и отговорник за проверката. Вторият — Лице на реален човек без разрешение. — оставя този риск: Публикуваш визуално убедителна измислица, защото генераторът „познава продукта“. В работна ситуация поправката е: Отхвърли недоказаните елементи и запази проверен кадър и разрешенията в досието. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Генераторът добавя неподтвърден резултат. Какво правиш?","options":[{"id":"a","label":"Премахваш твърдението и проверяваш оригиналния източник."},{"id":"b","label":"Оставяш го, ако звучи убедително."},{"id":"c","label":"Преместваш го в субтитрите."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Премахваш твърдението и проверяваш оригиналния източник.\n\nПървият слаб ход — Оставяш го, ако звучи убедително. — пропуска тази проверка: Крайната версия не добавя несъществуваща характеристика; за всеки актив има произход и отговорник за проверката. Вторият — Преместваш го в субтитрите. — оставя този риск: Публикуваш визуално убедителна измислица, защото генераторът „познава продукта“. В работна ситуация поправката е: Отхвърли недоказаните елементи и запази проверен кадър и разрешенията в досието. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Какво остава в досието?","options":[{"id":"a","label":"Само крайният mp4."},{"id":"b","label":"Входни активи, разрешения, версии, проверени факти и изисквани обозначения."},{"id":"c","label":"Само prompt-ът без изходните права."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Входни активи, разрешения, версии, проверени факти и изисквани обозначения.\n\nПървият слаб ход — Само крайният mp4. — пропуска тази проверка: Крайната версия не добавя несъществуваща характеристика; за всеки актив има произход и отговорник за проверката. Вторият — Само prompt-ът без изходните права. — оставя този риск: Публикуваш визуално убедителна измислица, защото генераторът „познава продукта“. В работна ситуация поправката е: Отхвърли недоказаните елементи и запази проверен кадър и разрешенията в досието. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Публикуваш визуално убедителна измислица, защото генераторът „познава продукта“. Как продължаваш?","options":[{"id":"a","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"b","label":"Отхвърли недоказаните елементи и запази проверен кадър и разрешенията в досието."},{"id":"c","label":"Продължаваш без проверка и наричаш тази версия окончателна."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Отхвърли недоказаните елементи и запази проверен кадър и разрешенията в досието.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Крайната версия не добавя несъществуваща характеристика; за всеки актив има произход и отговорник за проверката. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Публикуваш визуално убедителна измислица, защото генераторът „познава продукта“. В работна ситуация поправката е: Отхвърли недоказаните елементи и запази проверен кадър и разрешенията в досието. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s2","text":"Поискай два варианта и запази входа и версиите."},{"id":"s3","text":"Сравни всеки кадър и ред с действителния продукт, права и материали."},{"id":"s4","text":"Провери обозначенията и направи финален човешки преглед на експорта."},{"id":"s1","text":"Подготви brief с проверени факти и забранени твърдения."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Подготви brief с проверени факти и забранени твърдения.\n2. Поискай два варианта и запази входа и версиите.\n3. Сравни всеки кадър и ред с действителния продукт, права и материали.\n4. Провери обозначенията и направи финален човешки преглед на експорта."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Използвай генериране за вариант на структура, субтитър или композиционна идея, но запази списък с факти, разрешени активи и граници. Свери всяко число, демонстрация, лице и глас с първоизточник и разрешение. Отдели чернова от реален продукт. Проверявай изискванията за обозначаване на съответната платформа преди публикуване, особено при реалистична синтетична сцена.","Отхвърли недоказаните елементи и запази проверен кадър и разрешенията в досието.","Крайната версия не добавя несъществуваща характеристика; за всеки актив има произход и отговорник за проверката."],"nextStep":"Направи две версии на 15-секунден откъс с разрешен материал; маркирай всеки AI елемент, факт, право и човешка поправка."},"points":1,"required":true}]},{"module_id":"s02-m10","lesson_id":"pv10-10","title":"Измери социален профил в Search Console, ако имаш достъп","subtitle":"Публикуване с проверено обещание и подходящ канал","objective":"Собствеността е проверена или ограничението е записано; отчетът ясно казва, че мери Google Search.","hook":"Агенция обещава Search Console за профил, до който никой не може да докаже право на достъп.","estimated_minutes":36,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Собствеността е проверена или ограничението е записано; отчетът ясно казва, че мери Google Search."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Агенция обещава Search Console за профил, до който никой не може да докаже право на достъп."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Platform property в Search Console отчита присъствие на поддържан профил в Google Search; не дава достъп до вътрешната аналитика на платформата. Нужна е поддържана връзка и проверка на собственост според текущите инструкции. Ако клиентът не може да потвърди собственост, ползвай предоставени отчети или публично наблюдение и запиши ограничението, вместо да заобикаляш удостоверяването."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Преди публикуване провери актуалната функция в своя акаунт, език и регион. Платформен инструмент може да липсва или да измерва друга публика. Запиши целта на видеото, собствеността върху материала, източника на факта и точния път от клипа до полезното действие. Ако каналът не дава обещаната функция, използвай наблюдаем резервен метод и назови ограничението. Не превръщай метрика от една услуга в метрика от друга.\n\nЗа тази задача: Раздели източник, дефиниция и период; не твърди данни, които инструментът не измерва."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Определи кой държи профила и какво право има да дава достъп.\n2. Провери текущите видове property и стъпките за конкретната платформа.\n3. Документирай проверката на собственост и периода, за който има данни.\n4. Избери една заявка или страница, сравни показвания и кликове в Google Search и докладвай границите.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Малък бранд има Instagram профил, но маркетологът няма администраторски достъп. Той не регистрира чужд профил като свой; моли титуляра да даде позволен достъп и дотогава отделя Google резултатите от Instagram Insights.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Обединяваш Google Search показвания с гледания в социалната платформа в едно число."},"after":{"label":"Как го поправяш","text":"Раздели източник, дефиниция и период; не твърди данни, които инструментът не измерва."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Обединяваш Google Search показвания с гледания в социалната платформа в едно число.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Определи кой държи профила и какво право има да дава достъп. След него: Документирай проверката на собственост и периода, за който има данни.\n\nКорекция: Раздели източник, дефиниция и период; не твърди данни, които инструментът не измерва.\n\nНови данни, които ще приемеш за успешна поправка: Собствеността е проверена или ограничението е записано; отчетът ясно казва, че мери Google Search. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Направи карта на достъпа за собствен или разрешен профил: собственик, метод на проверка, един отчет и едно ограничение.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Собствеността е проверена или ограничението е записано; отчетът ясно казва, че мери Google Search.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Малък бранд има Instagram профил, но маркетологът няма администраторски достъп. Той не регистрира чужд профил като свой; моли титуляра да даде позволен достъп и дотогава отделя Google резултатите от Instagram Insights.\n\nДоставка: Направи карта на достъпа за собствен или разрешен профил: собственик, метод на проверка, един отчет и едно ограничение.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Собствеността е проверена или ограничението е записано; отчетът ясно казва, че мери Google Search."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Проверен първоизточник","content":{"body":"Google Search Console Help — добавяне на сайт или platform property: https://support.google.com/webmasters/answer/34592\nПровери текущата версия на функцията преди да повториш стъпките."},"points":0,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Какво измерва тази property?","options":[{"id":"a","label":"Всички гледания в Instagram."},{"id":"b","label":"Скрити данни на конкурентен профил."},{"id":"c","label":"Видимостта на поддържан профил в Google Search при проверен достъп."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Видимостта на поддържан профил в Google Search при проверен достъп.\n\nПървият слаб ход — Всички гледания в Instagram. — пропуска тази проверка: Собствеността е проверена или ограничението е записано; отчетът ясно казва, че мери Google Search. Вторият — Скрити данни на конкурентен профил. — оставя този риск: Обединяваш Google Search показвания с гледания в социалната платформа в едно число. В работна ситуация поправката е: Раздели източник, дефиниция и период; не твърди данни, които инструментът не измерва. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Клиентът не може да даде достъп днес. Какво правиш?","options":[{"id":"a","label":"Измисляш отчет за Google."},{"id":"b","label":"Заобикаляш проверката с чужд акаунт."},{"id":"c","label":"Записваш ограничението и използваш само данни, за които имаш право."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Записваш ограничението и използваш само данни, за които имаш право.\n\nПървият слаб ход — Заобикаляш проверката с чужд акаунт. — пропуска тази проверка: Собствеността е проверена или ограничението е записано; отчетът ясно казва, че мери Google Search. Вторият — Измисляш отчет за Google. — оставя този риск: Обединяваш Google Search показвания с гледания в социалната платформа в едно число. В работна ситуация поправката е: Раздели източник, дефиниция и период; не твърди данни, които инструментът не измерва. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Коя бележка задължително стои под графиката?","options":[{"id":"a","label":"Източник, дефиниция, property и период на данните."},{"id":"b","label":"„Алгоритъмът ни харесва“."},{"id":"c","label":"Неназован общ брой гледания."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Източник, дефиниция, property и период на данните.\n\nПървият слаб ход — „Алгоритъмът ни харесва“. — пропуска тази проверка: Собствеността е проверена или ограничението е записано; отчетът ясно казва, че мери Google Search. Вторият — Неназован общ брой гледания. — оставя този риск: Обединяваш Google Search показвания с гледания в социалната платформа в едно число. В работна ситуация поправката е: Раздели източник, дефиниция и период; не твърди данни, които инструментът не измерва. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Обединяваш Google Search показвания с гледания в социалната платформа в едно число. Как продължаваш?","options":[{"id":"a","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"b","label":"Раздели източник, дефиниция и период; не твърди данни, които инструментът не измерва."},{"id":"c","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Раздели източник, дефиниция и период; не твърди данни, които инструментът не измерва.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Собствеността е проверена или ограничението е записано; отчетът ясно казва, че мери Google Search. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Обединяваш Google Search показвания с гледания в социалната платформа в едно число. В работна ситуация поправката е: Раздели източник, дефиниция и период; не твърди данни, които инструментът не измерва. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s2","text":"Провери текущите видове property и стъпките за конкретната платформа."},{"id":"s1","text":"Определи кой държи профила и какво право има да дава достъп."},{"id":"s4","text":"Избери една заявка или страница, сравни показвания и кликове в Google Search и докладвай границите."},{"id":"s3","text":"Документирай проверката на собственост и периода, за който има данни."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Определи кой държи профила и какво право има да дава достъп.\n2. Провери текущите видове property и стъпките за конкретната платформа.\n3. Документирай проверката на собственост и периода, за който има данни.\n4. Избери една заявка или страница, сравни показвания и кликове в Google Search и докладвай границите."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Platform property в Search Console отчита присъствие на поддържан профил в Google Search; не дава достъп до вътрешната аналитика на платформата. Нужна е поддържана връзка и проверка на собственост според текущите инструкции. Ако клиентът не може да потвърди собственост, ползвай предоставени отчети или публично наблюдение и запиши ограничението, вместо да заобикаляш удостоверяването.","Раздели източник, дефиниция и период; не твърди данни, които инструментът не измерва.","Собствеността е проверена или ограничението е записано; отчетът ясно казва, че мери Google Search."],"nextStep":"Направи карта на достъпа за собствен или разрешен профил: собственик, метод на проверка, един отчет и едно ограничение."},"points":1,"required":true}]},{"module_id":"s02-m10","lesson_id":"pv10-11","title":"Направи версия за Facebook Reels и група без да спамиш","subtitle":"Публикуване с проверено обещание и подходящ канал","objective":"Груповият пост има причина да е точно там, авторът е прозрачен и правилата са спазени.","hook":"Клипът за местен магазин се качва в пет групи с еднакъв рекламен текст и получава оплаквания.","estimated_minutes":36,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Груповият пост има причина да е точно там, авторът е прозрачен и правилата са спазени."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Клипът за местен магазин се качва в пет групи с еднакъв рекламен текст и получава оплаквания."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Facebook Reel и публикация в група са два различни контекста. Reel може да покаже действие бързо; в групата правилата и разговорът са водещи. Провери дали групата допуска този тип публикация, представи кой си и добави стойност, която е смислена и без линк. Не пренасяй едни и същи обещания и формат механично."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Преди публикуване провери актуалната функция в своя акаунт, език и регион. Платформен инструмент може да липсва или да измерва друга публика. Запиши целта на видеото, собствеността върху материала, източника на факта и точния път от клипа до полезното действие. Ако каналът не дава обещаната функция, използвай наблюдаем резервен метод и назови ограничението. Не превръщай метрика от една услуга в метрика от друга.\n\nЗа тази задача: Спрете разпространението, проверете правилата и отговорете по същество на хората."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Извади полезния момент от видеото, който работи без звук и в малък екран.\n2. Прочети правилата на конкретната група преди публикация.\n3. Напиши групов текст като отговор на реален местен въпрос, с ясен автор.\n4. Следи качеството на въпросите и премахни неподходящ пост, ако е нарушил правилата.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Пекарна показва кратък процес на месене в Reel. В кварталната група споделя кога излиза топъл хляб след въпрос от член, с разрешение на администратор и без масово копиране на оферта.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Групата получава спам, а екипът нарича негативните реакции „ангажираност“."},"after":{"label":"Как го поправяш","text":"Спрете разпространението, проверете правилата и отговорете по същество на хората."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Групата получава спам, а екипът нарича негативните реакции „ангажираност“.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Извади полезния момент от видеото, който работи без звук и в малък екран. След него: Напиши групов текст като отговор на реален местен въпрос, с ясен автор.\n\nКорекция: Спрете разпространението, проверете правилата и отговорете по същество на хората.\n\nНови данни, които ще приемеш за успешна поправка: Груповият пост има причина да е точно там, авторът е прозрачен и правилата са спазени. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Подготви Reel монтаж и отделен текст за една конкретна група; запиши правилото, което позволява или забранява публикуване.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Груповият пост има причина да е точно там, авторът е прозрачен и правилата са спазени.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Пекарна показва кратък процес на месене в Reel. В кварталната група споделя кога излиза топъл хляб след въпрос от член, с разрешение на администратор и без масово копиране на оферта.\n\nДоставка: Подготви Reel монтаж и отделен текст за една конкретна група; запиши правилото, което позволява или забранява публикуване.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Груповият пост има причина да е точно там, авторът е прозрачен и правилата са спазени."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Кога споделяш в група?","options":[{"id":"a","label":"Когато правилата позволяват и публикацията отговаря на конкретен въпрос."},{"id":"b","label":"Когато можеш да скриеш, че си рекламодател."},{"id":"c","label":"Когато групата е голяма, независимо от правила."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Когато правилата позволяват и публикацията отговаря на конкретен въпрос.\n\nПървият слаб ход — Когато групата е голяма, независимо от правила. — пропуска тази проверка: Груповият пост има причина да е точно там, авторът е прозрачен и правилата са спазени. Вторият — Когато можеш да скриеш, че си рекламодател. — оставя този риск: Групата получава спам, а екипът нарича негативните реакции „ангажираност“. В работна ситуация поправката е: Спрете разпространението, проверете правилата и отговорете по същество на хората. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Администраторът отхвърля поста. Как действаш?","options":[{"id":"a","label":"Качваш през лични профили многократно."},{"id":"b","label":"Добавяш линк в коментар, за да заобиколиш правилото."},{"id":"c","label":"Уважаваш решението и търсиш позволен канал или подходяща полезна тема."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Уважаваш решението и търсиш позволен канал или подходяща полезна тема.\n\nПървият слаб ход — Качваш през лични профили многократно. — пропуска тази проверка: Груповият пост има причина да е точно там, авторът е прозрачен и правилата са спазени. Вторият — Добавяш линк в коментар, за да заобиколиш правилото. — оставя този риск: Групата получава спам, а екипът нарича негативните реакции „ангажираност“. В работна ситуация поправката е: Спрете разпространението, проверете правилата и отговорете по същество на хората. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Какво значи качествен резултат?","options":[{"id":"a","label":"Брой отрицателни реакции без контекст."},{"id":"b","label":"Брой групи, в които си копирал текста."},{"id":"c","label":"Конкретни въпроси и полезно действие, без нарушаване на правилата."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Конкретни въпроси и полезно действие, без нарушаване на правилата.\n\nПървият слаб ход — Брой групи, в които си копирал текста. — пропуска тази проверка: Груповият пост има причина да е точно там, авторът е прозрачен и правилата са спазени. Вторият — Брой отрицателни реакции без контекст. — оставя този риск: Групата получава спам, а екипът нарича негативните реакции „ангажираност“. В работна ситуация поправката е: Спрете разпространението, проверете правилата и отговорете по същество на хората. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Групата получава спам, а екипът нарича негативните реакции „ангажираност“. Как продължаваш?","options":[{"id":"a","label":"Спрете разпространението, проверете правилата и отговорете по същество на хората."},{"id":"b","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"c","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Спрете разпространението, проверете правилата и отговорете по същество на хората.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Груповият пост има причина да е точно там, авторът е прозрачен и правилата са спазени. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Групата получава спам, а екипът нарича негативните реакции „ангажираност“. В работна ситуация поправката е: Спрете разпространението, проверете правилата и отговорете по същество на хората. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s4","text":"Следи качеството на въпросите и премахни неподходящ пост, ако е нарушил правилата."},{"id":"s1","text":"Извади полезния момент от видеото, който работи без звук и в малък екран."},{"id":"s2","text":"Прочети правилата на конкретната група преди публикация."},{"id":"s3","text":"Напиши групов текст като отговор на реален местен въпрос, с ясен автор."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Извади полезния момент от видеото, който работи без звук и в малък екран.\n2. Прочети правилата на конкретната група преди публикация.\n3. Напиши групов текст като отговор на реален местен въпрос, с ясен автор.\n4. Следи качеството на въпросите и премахни неподходящ пост, ако е нарушил правилата."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Facebook Reel и публикация в група са два различни контекста. Reel може да покаже действие бързо; в групата правилата и разговорът са водещи. Провери дали групата допуска този тип публикация, представи кой си и добави стойност, която е смислена и без линк. Не пренасяй едни и същи обещания и формат механично.","Спрете разпространението, проверете правилата и отговорете по същество на хората.","Груповият пост има причина да е точно там, авторът е прозрачен и правилата са спазени."],"nextStep":"Подготви Reel монтаж и отделен текст за една конкретна група; запиши правилото, което позволява или забранява публикуване."},"points":1,"required":true}]},{"module_id":"s02-m10","lesson_id":"pv10-12","title":"Направи B2B версия с доказателство, не само с обещание","subtitle":"Публикуване с проверено обещание и подходящ канал","objective":"Зрителят разбира какво решение може да вземе; всяко число и чуждо име имат източник или са премахнати.","hook":"Видео за B2B клиент обещава „10× резултат“, но не показва нито процес, нито основание.","estimated_minutes":38,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Зрителят разбира какво решение може да вземе; всяко число и чуждо име имат източник или са премахнати."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Видео за B2B клиент обещава „10× резултат“, но не показва нито процес, нито основание."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"В професионална среда покажи ситуация, решение, ограничение и доказателство. Ако нямаш измерен резултат, покажи метод и критерий за проверка. Съгласувай клиентските данни и разрешението за казуса. В първите секунди трябва да е ясно на кого е полезно видеото; визуалният стил служи на доказателството, не замества го."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Преди публикуване провери актуалната функция в своя акаунт, език и регион. Платформен инструмент може да липсва или да измерва друга публика. Запиши целта на видеото, собствеността върху материала, източника на факта и точния път от клипа до полезното действие. Ако каналът не дава обещаната функция, използвай наблюдаем резервен метод и назови ограничението. Не превръщай метрика от една услуга в метрика от друга.\n\nЗа тази задача: Махни непотвърденото число; поискай разрешение или направи анонимен процесен пример."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Опиши ролята на зрителя и едно решение, което той взема.\n2. Избери разрешен кадър от процес, а не само общ красив фон.\n3. Формулирай теза с граница и покажи документ, демонстрация или наблюдение.\n4. Провери контекста на LinkedIn и една метрика след публикация.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Малка логистична фирма показва как маркира пратки, за да намали объркване. Вместо измислен процент, показва процеса, отговорника и как ще измери неправилните доставки през следващия месец.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Измисляш процент и използваш лого на клиент без съгласие."},"after":{"label":"Как го поправяш","text":"Махни непотвърденото число; поискай разрешение или направи анонимен процесен пример."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Измисляш процент и използваш лого на клиент без съгласие.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Опиши ролята на зрителя и едно решение, което той взема. След него: Формулирай теза с граница и покажи документ, демонстрация или наблюдение.\n\nКорекция: Махни непотвърденото число; поискай разрешение или направи анонимен процесен пример.\n\nНови данни, които ще приемеш за успешна поправка: Зрителят разбира какво решение може да вземе; всяко число и чуждо име имат източник или са премахнати. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Пренапиши свой клип за B2B зрител: посочи решение, една видима стъпка, източник на твърдението и покана за конкретен разговор.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Зрителят разбира какво решение може да вземе; всяко число и чуждо име имат източник или са премахнати.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Малка логистична фирма показва как маркира пратки, за да намали объркване. Вместо измислен процент, показва процеса, отговорника и как ще измери неправилните доставки през следващия месец.\n\nДоставка: Пренапиши свой клип за B2B зрител: посочи решение, една видима стъпка, източник на твърдението и покана за конкретен разговор.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Зрителят разбира какво решение може да вземе; всяко число и чуждо име имат източник или са премахнати."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Проверен първоизточник","content":{"body":"LinkedIn Help — статистика за видео: https://www.linkedin.com/help/linkedin/answer/a590236\nПровери текущата версия на функцията преди да повториш стъпките."},"points":0,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Кое е доказателство без измислен KPI?","options":[{"id":"a","label":"Непотвърден отзив от клиент."},{"id":"b","label":"Разрешена демонстрация с проверим метод и ясно ограничение."},{"id":"c","label":"Случаен stock кадър с обещание 10×."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Разрешена демонстрация с проверим метод и ясно ограничение.\n\nПървият слаб ход — Случаен stock кадър с обещание 10×. — пропуска тази проверка: Зрителят разбира какво решение може да вземе; всяко число и чуждо име имат източник или са премахнати. Вторият — Непотвърден отзив от клиент. — оставя този риск: Измисляш процент и използваш лого на клиент без съгласие. В работна ситуация поправката е: Махни непотвърденото число; поискай разрешение или направи анонимен процесен пример. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Клиентът не позволява да покажеш данните. Какво правиш?","options":[{"id":"a","label":"Ползваш анонимизиран процес след съгласуване или друг собствен пример."},{"id":"b","label":"Измисляш приблизителен резултат."},{"id":"c","label":"Замъгляваш логото, но оставяш лични данни."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Ползваш анонимизиран процес след съгласуване или друг собствен пример.\n\nПървият слаб ход — Замъгляваш логото, но оставяш лични данни. — пропуска тази проверка: Зрителят разбира какво решение може да вземе; всяко число и чуждо име имат източник или са премахнати. Вторият — Измисляш приблизителен резултат. — оставя този риск: Измисляш процент и използваш лого на клиент без съгласие. В работна ситуация поправката е: Махни непотвърденото число; поискай разрешение или направи анонимен процесен пример. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Какво съпоставяш след поста?","options":[{"id":"a","label":"Само общите импресии."},{"id":"b","label":"Само лайковете от екипа."},{"id":"c","label":"Подходящи гледания, време на гледане и професионални запитвания според целта."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Подходящи гледания, време на гледане и професионални запитвания според целта.\n\nПървият слаб ход — Само общите импресии. — пропуска тази проверка: Зрителят разбира какво решение може да вземе; всяко число и чуждо име имат източник или са премахнати. Вторият — Само лайковете от екипа. — оставя този риск: Измисляш процент и използваш лого на клиент без съгласие. В работна ситуация поправката е: Махни непотвърденото число; поискай разрешение или направи анонимен процесен пример. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Измисляш процент и използваш лого на клиент без съгласие. Как продължаваш?","options":[{"id":"a","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"b","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"c","label":"Махни непотвърденото число; поискай разрешение или направи анонимен процесен пример."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Махни непотвърденото число; поискай разрешение или направи анонимен процесен пример.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Зрителят разбира какво решение може да вземе; всяко число и чуждо име имат източник или са премахнати. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Измисляш процент и използваш лого на клиент без съгласие. В работна ситуация поправката е: Махни непотвърденото число; поискай разрешение или направи анонимен процесен пример. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s4","text":"Провери контекста на LinkedIn и една метрика след публикация."},{"id":"s3","text":"Формулирай теза с граница и покажи документ, демонстрация или наблюдение."},{"id":"s2","text":"Избери разрешен кадър от процес, а не само общ красив фон."},{"id":"s1","text":"Опиши ролята на зрителя и едно решение, което той взема."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Опиши ролята на зрителя и едно решение, което той взема.\n2. Избери разрешен кадър от процес, а не само общ красив фон.\n3. Формулирай теза с граница и покажи документ, демонстрация или наблюдение.\n4. Провери контекста на LinkedIn и една метрика след публикация."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["В професионална среда покажи ситуация, решение, ограничение и доказателство. Ако нямаш измерен резултат, покажи метод и критерий за проверка. Съгласувай клиентските данни и разрешението за казуса. В първите секунди трябва да е ясно на кого е полезно видеото; визуалният стил служи на доказателството, не замества го.","Махни непотвърденото число; поискай разрешение или направи анонимен процесен пример.","Зрителят разбира какво решение може да вземе; всяко число и чуждо име имат източник или са премахнати."],"nextStep":"Пренапиши свой клип за B2B зрител: посочи решение, една видима стъпка, източник на твърдението и покана за конкретен разговор."},"points":1,"required":true}]},{"module_id":"s02-m10","lesson_id":"pv10-13","title":"Използвай Pinterest видео за идея, която хората ще запазят","subtitle":"Публикуване с проверено обещание и подходящ канал","objective":"Кадърът дава повторно използваема идея и връзката, ако съществува, води към обещаното.","hook":"В Pinterest качваш случайна вертикална реклама без идея, която човек би поискал да запази.","estimated_minutes":36,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Кадърът дава повторно използваема идея и връзката, ако съществува, води към обещаното."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"В Pinterest качваш случайна вертикална реклама без идея, която човек би поискал да запази."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Потребителят често търси идея за бъдещо действие. Направи видео с ясно начало, разбираем резултат и кадър/надпис, който носи стойност и при повторно отваряне. Свържи го с коректна дестинация, ако има такава. Различавай запазвания, клик върху Pin и изходящ клик; те не означават едно и също."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Преди публикуване провери актуалната функция в своя акаунт, език и регион. Платформен инструмент може да липсва или да измерва друга публика. Запиши целта на видеото, собствеността върху материала, източника на факта и точния път от клипа до полезното действие. Ако каналът не дава обещаната функция, използвай наблюдаем резервен метод и назови ограничението. Не превръщай метрика от една услуга в метрика от друга.\n\nЗа тази задача: Добави действителната стъпка или назови видеото като вдъхновение, не като урок."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Избери въпрос, който остава полезен и след седмица.\n2. Покажи материали, стъпки и финален резултат в четим вертикален монтаж.\n3. Напиши точно заглавие и провери работеща дестинация, ако има линк.\n4. След публикация сравни запазвания и изходящи действия според целта.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Ателие показва три начина да подреди малка маса. Всеки вариант е заснет отблизо и накрая има схема за размерите; линкът води към показаните продукти, не към обща начална страница.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Етикетът обещава инструкция, а видеото е само финална снимка и несвързан линк."},"after":{"label":"Как го поправяш","text":"Добави действителната стъпка или назови видеото като вдъхновение, не като урок."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Етикетът обещава инструкция, а видеото е само финална снимка и несвързан линк.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Избери въпрос, който остава полезен и след седмица. След него: Напиши точно заглавие и провери работеща дестинация, ако има линк.\n\nКорекция: Добави действителната стъпка или назови видеото като вдъхновение, не като урок.\n\nНови данни, които ще приемеш за успешна поправка: Кадърът дава повторно използваема идея и връзката, ако съществува, води към обещаното. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Направи 20-секундна версия на свой процес за запазване; провери след седмица две различни действия и запиши кое търсиш.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Кадърът дава повторно използваема идея и връзката, ако съществува, води към обещаното.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Ателие показва три начина да подреди малка маса. Всеки вариант е заснет отблизо и накрая има схема за размерите; линкът води към показаните продукти, не към обща начална страница.\n\nДоставка: Направи 20-секундна версия на свой процес за запазване; провери след седмица две различни действия и запиши кое търсиш.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Кадърът дава повторно използваема идея и връзката, ако съществува, води към обещаното."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Проверен първоизточник","content":{"body":"Pinterest Business Help — статистика за Pin: https://help.pinterest.com/en/business/article/pin-stats\nПровери текущата версия на функцията преди да повториш стъпките."},"points":0,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Коя идея има причина за запазване?","options":[{"id":"a","label":"Мигащ бранд знак без задача."},{"id":"b","label":"Кратък процес с материали и резултат, към който зрителят може да се върне."},{"id":"c","label":"Невярна рецепта с красива снимка."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Кратък процес с материали и резултат, към който зрителят може да се върне.\n\nПървият слаб ход — Мигащ бранд знак без задача. — пропуска тази проверка: Кадърът дава повторно използваема идея и връзката, ако съществува, води към обещаното. Вторият — Невярна рецепта с красива снимка. — оставя този риск: Етикетът обещава инструкция, а видеото е само финална снимка и несвързан линк. В работна ситуация поправката е: Добави действителната стъпка или назови видеото като вдъхновение, не като урок. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Pin-ът има запазвания, но няма посещения към сайта. Как тълкуваш?","options":[{"id":"a","label":"Изключваш всички видеа веднага."},{"id":"b","label":"Разделяш целта за запазване от целта за изходящ клик и проверяваш дестинацията."},{"id":"c","label":"Обявяваш директни продажби."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Разделяш целта за запазване от целта за изходящ клик и проверяваш дестинацията.\n\nПървият слаб ход — Обявяваш директни продажби. — пропуска тази проверка: Кадърът дава повторно използваема идея и връзката, ако съществува, води към обещаното. Вторият — Изключваш всички видеа веднага. — оставя този риск: Етикетът обещава инструкция, а видеото е само финална снимка и несвързан линк. В работна ситуация поправката е: Добави действителната стъпка или назови видеото като вдъхновение, не като урок. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Кой отчет е подходящ за посещения към сайт?","options":[{"id":"a","label":"Изходящи кликове към проверения линк."},{"id":"b","label":"Само брой запазвания."},{"id":"c","label":"Само импресии."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Изходящи кликове към проверения линк.\n\nПървият слаб ход — Само импресии. — пропуска тази проверка: Кадърът дава повторно използваема идея и връзката, ако съществува, води към обещаното. Вторият — Само брой запазвания. — оставя този риск: Етикетът обещава инструкция, а видеото е само финална снимка и несвързан линк. В работна ситуация поправката е: Добави действителната стъпка или назови видеото като вдъхновение, не като урок. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Етикетът обещава инструкция, а видеото е само финална снимка и несвързан линк. Как продължаваш?","options":[{"id":"a","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"b","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"c","label":"Добави действителната стъпка или назови видеото като вдъхновение, не като урок."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Добави действителната стъпка или назови видеото като вдъхновение, не като урок.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Кадърът дава повторно използваема идея и връзката, ако съществува, води към обещаното. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Етикетът обещава инструкция, а видеото е само финална снимка и несвързан линк. В работна ситуация поправката е: Добави действителната стъпка или назови видеото като вдъхновение, не като урок. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s2","text":"Покажи материали, стъпки и финален резултат в четим вертикален монтаж."},{"id":"s3","text":"Напиши точно заглавие и провери работеща дестинация, ако има линк."},{"id":"s4","text":"След публикация сравни запазвания и изходящи действия според целта."},{"id":"s1","text":"Избери въпрос, който остава полезен и след седмица."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Избери въпрос, който остава полезен и след седмица.\n2. Покажи материали, стъпки и финален резултат в четим вертикален монтаж.\n3. Напиши точно заглавие и провери работеща дестинация, ако има линк.\n4. След публикация сравни запазвания и изходящи действия според целта."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Потребителят често търси идея за бъдещо действие. Направи видео с ясно начало, разбираем резултат и кадър/надпис, който носи стойност и при повторно отваряне. Свържи го с коректна дестинация, ако има такава. Различавай запазвания, клик върху Pin и изходящ клик; те не означават едно и също.","Добави действителната стъпка или назови видеото като вдъхновение, не като урок.","Кадърът дава повторно използваема идея и връзката, ако съществува, води към обещаното."],"nextStep":"Направи 20-секундна версия на свой процес за запазване; провери след седмица две различни действия и запиши кое търсиш."},"points":1,"required":true}]},{"module_id":"s02-m10","lesson_id":"pv10-14","title":"Адаптирай TikTok и YouTube Shorts по намерение","subtitle":"Публикуване с проверено обещание и подходящ канал","objective":"Фактът и правата остават едни и същи; всяка версия се разбира самостоятелно на своя екран.","hook":"Едно видео е качено без промяна в TikTok и Shorts, въпреки че първият кадър зависи от чужд интерфейс.","estimated_minutes":38,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Фактът и правата остават едни и същи; всяка версия се разбира самостоятелно на своя екран."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Едно видео е качено без промяна в TikTok и Shorts, въпреки че първият кадър зависи от чужд интерфейс."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Двете кратки формати имат различна среда на гледане, но няма универсална формула за всички зрители. Запази основния факт и монтажен master без воден знак. Преработи началото, надписите, контекстните препратки и поканата според реалното намерение и наличните функции. Не пренасяй твърдение, което в новата версия остава без обяснение."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Преди публикуване провери актуалната функция в своя акаунт, език и регион. Платформен инструмент може да липсва или да измерва друга публика. Запиши целта на видеото, собствеността върху материала, източника на факта и точния път от клипа до полезното действие. Ако каналът не дава обещаната функция, използвай наблюдаем резервен метод и назови ограничението. Не превръщай метрика от една услуга в метрика от друга.\n\nЗа тази задача: Върни се към master-а и изнеси отделни версии с проверка на текст и звук."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Запиши един въпрос на зрителя и какъв отговор дава master-ът.\n2. Извади чисти кадри, звук и субтитри в отделни слоеве.\n3. Сглоби два opening-а и провери четимост, безопасни зони и източници.\n4. Публикувай с различни описания и сравни действия в собствените отчети.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Клип показва ремонт на цип. В TikTok започва с дефекта и бърза проба, а в Shorts с обещание за конкретния модел и следваща подробна инструкция. И двете версии показват същия действителен ремонт.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Сваляш качен клип с воден знак и го публикуваш с несъответстващ надпис."},"after":{"label":"Как го поправяш","text":"Върни се към master-а и изнеси отделни версии с проверка на текст и звук."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Сваляш качен клип с воден знак и го публикуваш с несъответстващ надпис.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Запиши един въпрос на зрителя и какъв отговор дава master-ът. След него: Сглоби два opening-а и провери четимост, безопасни зони и източници.\n\nКорекция: Върни се към master-а и изнеси отделни версии с проверка на текст и звук.\n\nНови данни, които ще приемеш за успешна поправка: Фактът и правата остават едни и същи; всяка версия се разбира самостоятелно на своя екран. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Експортирай два монтажа от един разрешен master и приложи карта какво е различно в първите пет секунди и в поканата.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Фактът и правата остават едни и същи; всяка версия се разбира самостоятелно на своя екран.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Клип показва ремонт на цип. В TikTok започва с дефекта и бърза проба, а в Shorts с обещание за конкретния модел и следваща подробна инструкция. И двете версии показват същия действителен ремонт.\n\nДоставка: Експортирай два монтажа от един разрешен master и приложи карта какво е различно в първите пет секунди и в поканата.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Фактът и правата остават едни и същи; всяка версия се разбира самостоятелно на своя екран."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Коя част е обща?","options":[{"id":"a","label":"Провереният факт и изходният разрешен материал."},{"id":"b","label":"Водният знак от първото качване."},{"id":"c","label":"Един и същ недоказан тренд."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Провереният факт и изходният разрешен материал.\n\nПървият слаб ход — Водният знак от първото качване. — пропуска тази проверка: Фактът и правата остават едни и същи; всяка версия се разбира самостоятелно на своя екран. Вторият — Един и същ недоказан тренд. — оставя този риск: Сваляш качен клип с воден знак и го публикуваш с несъответстващ надпис. В работна ситуация поправката е: Върни се към master-а и изнеси отделни версии с проверка на текст и звук. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Началото на Shorts споменава „виж линка тук“, но няма работеща дестинация. Какво правиш?","options":[{"id":"a","label":"Оставяш я заради темпото."},{"id":"b","label":"Сменяш поканата с налична следваща стъпка и проверяваш линка."},{"id":"c","label":"Добавяш случаен URL."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Сменяш поканата с налична следваща стъпка и проверяваш линка.\n\nПървият слаб ход — Оставяш я заради темпото. — пропуска тази проверка: Фактът и правата остават едни и същи; всяка версия се разбира самостоятелно на своя екран. Вторият — Добавяш случаен URL. — оставя този риск: Сваляш качен клип с воден знак и го публикуваш с несъответстващ надпис. В работна ситуация поправката е: Върни се към master-а и изнеси отделни версии с проверка на текст и звук. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Как сравняваш двете версии?","options":[{"id":"a","label":"Само по броя последователи на профила."},{"id":"b","label":"По предварителна цел и дефинирани метрики в отделните платформи."},{"id":"c","label":"Като приравняваш всички видове view."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: По предварителна цел и дефинирани метрики в отделните платформи.\n\nПървият слаб ход — Като приравняваш всички видове view. — пропуска тази проверка: Фактът и правата остават едни и същи; всяка версия се разбира самостоятелно на своя екран. Вторият — Само по броя последователи на профила. — оставя този риск: Сваляш качен клип с воден знак и го публикуваш с несъответстващ надпис. В работна ситуация поправката е: Върни се към master-а и изнеси отделни версии с проверка на текст и звук. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Сваляш качен клип с воден знак и го публикуваш с несъответстващ надпис. Как продължаваш?","options":[{"id":"a","label":"Върни се към master-а и изнеси отделни версии с проверка на текст и звук."},{"id":"b","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"c","label":"Продължаваш без проверка и наричаш тази версия окончателна."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Върни се към master-а и изнеси отделни версии с проверка на текст и звук.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Фактът и правата остават едни и същи; всяка версия се разбира самостоятелно на своя екран. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Сваляш качен клип с воден знак и го публикуваш с несъответстващ надпис. В работна ситуация поправката е: Върни се към master-а и изнеси отделни версии с проверка на текст и звук. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s2","text":"Извади чисти кадри, звук и субтитри в отделни слоеве."},{"id":"s1","text":"Запиши един въпрос на зрителя и какъв отговор дава master-ът."},{"id":"s4","text":"Публикувай с различни описания и сравни действия в собствените отчети."},{"id":"s3","text":"Сглоби два opening-а и провери четимост, безопасни зони и източници."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Запиши един въпрос на зрителя и какъв отговор дава master-ът.\n2. Извади чисти кадри, звук и субтитри в отделни слоеве.\n3. Сглоби два opening-а и провери четимост, безопасни зони и източници.\n4. Публикувай с различни описания и сравни действия в собствените отчети."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Двете кратки формати имат различна среда на гледане, но няма универсална формула за всички зрители. Запази основния факт и монтажен master без воден знак. Преработи началото, надписите, контекстните препратки и поканата според реалното намерение и наличните функции. Не пренасяй твърдение, което в новата версия остава без обяснение.","Върни се към master-а и изнеси отделни версии с проверка на текст и звук.","Фактът и правата остават едни и същи; всяка версия се разбира самостоятелно на своя екран."],"nextStep":"Експортирай два монтажа от един разрешен master и приложи карта какво е различно в първите пет секунди и в поканата."},"points":1,"required":true}]},{"module_id":"s02-m10","lesson_id":"pv10-15","title":"Предай едно видео в четири платформени версии","subtitle":"Публикуване с проверено обещание и подходящ канал","objective":"Получателят може да публикува точно определен файл без да пита автора; всеки файл е изгледан целият.","hook":"Клиентът иска четири версии, но получава четири еднакви файла с различни имена.","estimated_minutes":36,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Получателят може да публикува точно определен файл без да пита автора; всеки файл е изгледан целият."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Клиентът иска четири версии, но получава четири еднакви файла с различни имена."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Пакетът за предаване започва от една проверена история и четири конкретни ситуации на гледане. Използвай версии, не копия: кадриране, начало, субтитри, описание, дестинация и права за всяка платформа. Води manifest, за да знае следващият човек кой файл, защо и къде да качи. Не обещавай един и същ резултат от несъпоставими метрики."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Преди публикуване провери актуалната функция в своя акаунт, език и регион. Платформен инструмент може да липсва или да измерва друга публика. Запиши целта на видеото, собствеността върху материала, източника на факта и точния път от клипа до полезното действие. Ако каналът не дава обещаната функция, използвай наблюдаем резервен метод и назови ограничението. Не превръщай метрика от една услуга в метрика от друга.\n\nЗа тази задача: Изолирай лицензите и проверявай всяко крайно видео, а не само общия проект."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Определи четири канала само ако има причина за всеки.\n2. Избери master и запази източник, права, текст и графики отделно.\n3. Експортирай версии с ясно име, съотношение, първи кадър и проверени субтитри.\n4. Дай manifest с описания, линкове, статус, одобрител и метрика за преглед.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Местна работилница има основен 45-секунден процес. Изпраща кратък Reel, въпрос за TikTok, кратък Shorts и B2B версия с процес и измерване; таблицата сочи кой файл има разрешена музика и кой е без музика.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Един файл се преименува четири пъти и грешната музика отива в канал без лиценз."},"after":{"label":"Как го поправяш","text":"Изолирай лицензите и проверявай всяко крайно видео, а не само общия проект."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Един файл се преименува четири пъти и грешната музика отива в канал без лиценз.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Определи четири канала само ако има причина за всеки. След него: Експортирай версии с ясно име, съотношение, първи кадър и проверени субтитри.\n\nКорекция: Изолирай лицензите и проверявай всяко крайно видео, а не само общия проект.\n\nНови данни, които ще приемеш за успешна поправка: Получателят може да публикува точно определен файл без да пита автора; всеки файл е изгледан целият. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Предай четири реални версии или обясни защо някой канал отпада; включи имена, цели, права, превю и човек за одобрение.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Получателят може да публикува точно определен файл без да пита автора; всеки файл е изгледан целият.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Местна работилница има основен 45-секунден процес. Изпраща кратък Reel, въпрос за TikTok, кратък Shorts и B2B версия с процес и измерване; таблицата сочи кой файл има разрешена музика и кой е без музика.\n\nДоставка: Предай четири реални версии или обясни защо някой канал отпада; включи имена, цели, права, превю и човек за одобрение.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Получателят може да публикува точно определен файл без да пита автора; всеки файл е изгледан целият."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Какво прави пакета използваем?","options":[{"id":"a","label":"Само снимка от монтажния timeline."},{"id":"b","label":"Четири файла final.mp4 в различни папки."},{"id":"c","label":"Различни проверени версии и manifest с цел, права и статус."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Различни проверени версии и manifest с цел, права и статус.\n\nПървият слаб ход — Четири файла final.mp4 в различни папки. — пропуска тази проверка: Получателят може да публикува точно определен файл без да пита автора; всеки файл е изгледан целият. Вторият — Само снимка от монтажния timeline. — оставя този риск: Един файл се преименува четири пъти и грешната музика отива в канал без лиценз. В работна ситуация поправката е: Изолирай лицензите и проверявай всяко крайно видео, а не само общия проект. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Лицензът на музиката е за един канал. Какво правиш?","options":[{"id":"a","label":"Правиш чиста версия за останалите и документираш ограничението."},{"id":"b","label":"Качваш я навсякъде, защото е тиха."},{"id":"c","label":"Не споменаваш правото в manifest-а."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Правиш чиста версия за останалите и документираш ограничението.\n\nПървият слаб ход — Качваш я навсякъде, защото е тиха. — пропуска тази проверка: Получателят може да публикува точно определен файл без да пита автора; всеки файл е изгледан целият. Вторият — Не споменаваш правото в manifest-а. — оставя този риск: Един файл се преименува четири пъти и грешната музика отива в канал без лиценз. В работна ситуация поправката е: Изолирай лицензите и проверявай всяко крайно видео, а не само общия проект. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Какво е последната проверка?","options":[{"id":"a","label":"Само зеления индикатор на export."},{"id":"b","label":"Отваряне на всеки export и сравнение с реда му в manifest-а."},{"id":"c","label":"Само имената на файловете."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Отваряне на всеки export и сравнение с реда му в manifest-а.\n\nПървият слаб ход — Само зеления индикатор на export. — пропуска тази проверка: Получателят може да публикува точно определен файл без да пита автора; всеки файл е изгледан целият. Вторият — Само имената на файловете. — оставя този риск: Един файл се преименува четири пъти и грешната музика отива в канал без лиценз. В работна ситуация поправката е: Изолирай лицензите и проверявай всяко крайно видео, а не само общия проект. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Един файл се преименува четири пъти и грешната музика отива в канал без лиценз. Как продължаваш?","options":[{"id":"a","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"b","label":"Изолирай лицензите и проверявай всяко крайно видео, а не само общия проект."},{"id":"c","label":"Продължаваш без проверка и наричаш тази версия окончателна."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Изолирай лицензите и проверявай всяко крайно видео, а не само общия проект.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Получателят може да публикува точно определен файл без да пита автора; всеки файл е изгледан целият. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Един файл се преименува четири пъти и грешната музика отива в канал без лиценз. В работна ситуация поправката е: Изолирай лицензите и проверявай всяко крайно видео, а не само общия проект. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s4","text":"Дай manifest с описания, линкове, статус, одобрител и метрика за преглед."},{"id":"s1","text":"Определи четири канала само ако има причина за всеки."},{"id":"s2","text":"Избери master и запази източник, права, текст и графики отделно."},{"id":"s3","text":"Експортирай версии с ясно име, съотношение, първи кадър и проверени субтитри."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Определи четири канала само ако има причина за всеки.\n2. Избери master и запази източник, права, текст и графики отделно.\n3. Експортирай версии с ясно име, съотношение, първи кадър и проверени субтитри.\n4. Дай manifest с описания, линкове, статус, одобрител и метрика за преглед."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Пакетът за предаване започва от една проверена история и четири конкретни ситуации на гледане. Използвай версии, не копия: кадриране, начало, субтитри, описание, дестинация и права за всяка платформа. Води manifest, за да знае следващият човек кой файл, защо и къде да качи. Не обещавай един и същ резултат от несъпоставими метрики.","Изолирай лицензите и проверявай всяко крайно видео, а не само общия проект.","Получателят може да публикува точно определен файл без да пита автора; всеки файл е изгледан целият."],"nextStep":"Предай четири реални версии или обясни защо някой канал отпада; включи имена, цели, права, превю и човек за одобрение."},"points":1,"required":true}]},{"module_id":"s02-m10","lesson_id":"pv10-16","title":"Избери платформата преди снимките","subtitle":"Публикуване с проверено обещание и подходящ канал","objective":"Ключовото действие се вижда и в двата формата; има проверен пробен export преди край на снимачния ден.","hook":"Снимките са приключили, а вертикалният crop отрязва ръцете, които показват ключовата стъпка.","estimated_minutes":38,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Ключовото действие се вижда и в двата формата; има проверен пробен export преди край на снимачния ден."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Снимките са приключили, а вертикалният crop отрязва ръцете, които показват ключовата стъпка."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Платформеното решение преди снимки определя композиция, звукова среда, място за надпис, продължителност и права. Избери основен формат и вторични версии; набележи кои действия изискват отделен кадър. Не се опитвай да решиш в монтаж информация, която никога не е записана."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Преди публикуване провери актуалната функция в своя акаунт, език и регион. Платформен инструмент може да липсва или да измерва друга публика. Запиши целта на видеото, собствеността върху материала, източника на факта и точния път от клипа до полезното действие. Ако каналът не дава обещаната функция, използвай наблюдаем резервен метод и назови ограничението. Не превръщай метрика от една услуга в метрика от друга.\n\nЗа тази задача: Добави отделен план на действието по време на снимки или намали обещанието на версията."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Определи къде човек ще види клипа и какво ще направи след него.\n2. Нарисувай safe zones и заснеми пробен кадър за основния и вторичния формат.\n3. Запиши действията с handles и отделен близък план за критичната стъпка.\n4. Преди да разпуснеш екипа, провери изрязване, звук и четимост на телефон.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Керамист снима демонстрация за вертикален Reel и хоризонтален подробен клип. За близката работа с ръце отделя втори кадър; не оставя надпис върху инструмента.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Снимаш само един тесен кадър, после обещаваш широк урок с невидими действия."},"after":{"label":"Как го поправяш","text":"Добави отделен план на действието по време на снимки или намали обещанието на версията."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Снимаш само един тесен кадър, после обещаваш широк урок с невидими действия.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Определи къде човек ще види клипа и какво ще направи след него. След него: Запиши действията с handles и отделен близък план за критичната стъпка.\n\nКорекция: Добави отделен план на действието по време на снимки или намали обещанието на версията.\n\nНови данни, които ще приемеш за успешна поправка: Ключовото действие се вижда и в двата формата; има проверен пробен export преди край на снимачния ден. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Създай shot list за две дестинации, пробвай един реален кадър и запиши кое трябва да се снима повторно.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Ключовото действие се вижда и в двата формата; има проверен пробен export преди край на снимачния ден.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Керамист снима демонстрация за вертикален Reel и хоризонтален подробен клип. За близката работа с ръце отделя втори кадър; не оставя надпис върху инструмента.\n\nДоставка: Създай shot list за две дестинации, пробвай един реален кадър и запиши кое трябва да се снима повторно.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Ключовото действие се вижда и в двата формата; има проверен пробен export преди край на снимачния ден."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Кое решаваш преди снимки?","options":[{"id":"a","label":"Само модела на камерата."},{"id":"b","label":"Само времето за upload."},{"id":"c","label":"Основния екран, действието и кадрите, които вторият формат ще изисква."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Основния екран, действието и кадрите, които вторият формат ще изисква.\n\nПървият слаб ход — Само модела на камерата. — пропуска тази проверка: Ключовото действие се вижда и в двата формата; има проверен пробен export преди край на снимачния ден. Вторият — Само времето за upload. — оставя този риск: Снимаш само един тесен кадър, после обещаваш широк урок с невидими действия. В работна ситуация поправката е: Добави отделен план на действието по време на снимки или намали обещанието на версията. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Вертикалният crop скрива инструмента. Какъв е ходът на терен?","options":[{"id":"a","label":"Оставяш кадъра без ключовата стъпка."},{"id":"b","label":"Обещаваш, че AI ще възстанови инструмента."},{"id":"c","label":"Снимаш отделен близък план или променяш композицията с проба."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Снимаш отделен близък план или променяш композицията с проба.\n\nПървият слаб ход — Обещаваш, че AI ще възстанови инструмента. — пропуска тази проверка: Ключовото действие се вижда и в двата формата; има проверен пробен export преди край на снимачния ден. Вторият — Оставяш кадъра без ключовата стъпка. — оставя този риск: Снимаш само един тесен кадър, после обещаваш широк урок с невидими действия. В работна ситуация поправката е: Добави отделен план на действието по време на снимки или намали обещанието на версията. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Какво доказва готовност?","options":[{"id":"a","label":"Пробен export на целеви екран със звук, текст и видимо действие."},{"id":"b","label":"Красив кадър на monitor-а."},{"id":"c","label":"Твърдение, че crop винаги работи."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Пробен export на целеви екран със звук, текст и видимо действие.\n\nПървият слаб ход — Красив кадър на monitor-а. — пропуска тази проверка: Ключовото действие се вижда и в двата формата; има проверен пробен export преди край на снимачния ден. Вторият — Твърдение, че crop винаги работи. — оставя този риск: Снимаш само един тесен кадър, после обещаваш широк урок с невидими действия. В работна ситуация поправката е: Добави отделен план на действието по време на снимки или намали обещанието на версията. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Снимаш само един тесен кадър, после обещаваш широк урок с невидими действия. Как продължаваш?","options":[{"id":"a","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"b","label":"Добави отделен план на действието по време на снимки или намали обещанието на версията."},{"id":"c","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Добави отделен план на действието по време на снимки или намали обещанието на версията.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Ключовото действие се вижда и в двата формата; има проверен пробен export преди край на снимачния ден. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Снимаш само един тесен кадър, после обещаваш широк урок с невидими действия. В работна ситуация поправката е: Добави отделен план на действието по време на снимки или намали обещанието на версията. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s4","text":"Преди да разпуснеш екипа, провери изрязване, звук и четимост на телефон."},{"id":"s3","text":"Запиши действията с handles и отделен близък план за критичната стъпка."},{"id":"s2","text":"Нарисувай safe zones и заснеми пробен кадър за основния и вторичния формат."},{"id":"s1","text":"Определи къде човек ще види клипа и какво ще направи след него."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Определи къде човек ще види клипа и какво ще направи след него.\n2. Нарисувай safe zones и заснеми пробен кадър за основния и вторичния формат.\n3. Запиши действията с handles и отделен близък план за критичната стъпка.\n4. Преди да разпуснеш екипа, провери изрязване, звук и четимост на телефон."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Платформеното решение преди снимки определя композиция, звукова среда, място за надпис, продължителност и права. Избери основен формат и вторични версии; набележи кои действия изискват отделен кадър. Не се опитвай да решиш в монтаж информация, която никога не е записана.","Добави отделен план на действието по време на снимки или намали обещанието на версията.","Ключовото действие се вижда и в двата формата; има проверен пробен export преди край на снимачния ден."],"nextStep":"Създай shot list за две дестинации, пробвай един реален кадър и запиши кое трябва да се снима повторно."},"points":1,"required":true}]},{"module_id":"s02-m11","lesson_id":"pv11-01","title":"Планирай видео като част от серия, не като самотна публикация","subtitle":"Дълъг формат, измерване и решения от реални данни","objective":"Всеки епизод решава едно цяло подзадача; зрителят не трябва да гледа реклама, за да разбере безопасното действие.","hook":"Публикуваш силно първо видео, но нямаш отговор на въпроса, който зрителят задава след него.","estimated_minutes":36,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Всеки епизод решава едно цяло подзадача; зрителят не трябва да гледа реклама, за да разбере безопасното действие."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Публикуваш силно първо видео, но нямаш отговор на въпроса, който зрителят задава след него."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Серията се планира около развитие на една задача, не около изкуствено разделяне на един отговор. Всеки епизод трябва да е полезен самостоятелно и да остави логична следваща работа. Запиши какво зрителят вече знае, какво ще направи и какво доказателство ще му трябва. Не задържай ключовия отговор за следващ клип."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Пази screenshot или export на отчета с дата, видео и избран период. Една крива показва поведение, не причина. Изгледай публикувания файл на точния timecode, сравни зрителското намерение с обещанието и запиши друго възможно обяснение. Малката извадка и промяната на източниците могат да обърнат извода. Предлагай тест за следващото видео и определи кой ще го изпълни и кога ще се върне към данните.\n\nЗа тази задача: Върни необходимата информация във всеки самостоятелен епизод; свържи само следващата задача."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Избери една реална задача и три последователни решения.\n2. За всеки епизод напиши въпрос, действие и изходен артефакт.\n3. Провери дали нов човек разбира епизод 2 с кратък контекст.\n4. Подготви честен преход към следващата задача, без да криеш отговора.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Майстор показва диагностика на теч, отделно безопасен демонтаж и после проверка след сглобяване. Първият клип завършва с правило кога не се пипа системата, а не с „част 2 за тайната“.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Разрязваш една инструкция на три и държиш критичното предупреждение за финала."},"after":{"label":"Как го поправяш","text":"Върни необходимата информация във всеки самостоятелен епизод; свържи само следващата задача."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Разрязваш една инструкция на три и държиш критичното предупреждение за финала.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Избери една реална задача и три последователни решения. След него: Провери дали нов човек разбира епизод 2 с кратък контекст.\n\nКорекция: Върни необходимата информация във всеки самостоятелен епизод; свържи само следващата задача.\n\nНови данни, които ще приемеш за успешна поправка: Всеки епизод решава едно цяло подзадача; зрителят не трябва да гледа реклама, за да разбере безопасното действие. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Напиши карта на серия от три видеа: входно знание, конкретна проверка, видим резултат и естествена връзка.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Всеки епизод решава едно цяло подзадача; зрителят не трябва да гледа реклама, за да разбере безопасното действие.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Майстор показва диагностика на теч, отделно безопасен демонтаж и после проверка след сглобяване. Първият клип завършва с правило кога не се пипа системата, а не с „част 2 за тайната“.\n\nДоставка: Напиши карта на серия от три видеа: входно знание, конкретна проверка, видим резултат и естествена връзка.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Всеки епизод решава едно цяло подзадача; зрителят не трябва да гледа реклама, за да разбере безопасното действие."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Проверен първоизточник","content":{"body":"YouTube Help — YouTube Analytics: https://support.google.com/youtube/answer/9002587\nПровери текущата версия на функцията преди да повториш стъпките."},"points":0,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Кога има смисъл от серия?","options":[{"id":"a","label":"Когато всяко видео решава своя задача и подготвя следваща."},{"id":"b","label":"Когато всички видеа имат еднакво заглавие."},{"id":"c","label":"Когато нарежеш един отговор на три за гледания."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Когато всяко видео решава своя задача и подготвя следваща.\n\nПървият слаб ход — Когато нарежеш един отговор на три за гледания. — пропуска тази проверка: Всеки епизод решава едно цяло подзадача; зрителят не трябва да гледа реклама, за да разбере безопасното действие. Вторият — Когато всички видеа имат еднакво заглавие. — оставя този риск: Разрязваш една инструкция на три и държиш критичното предупреждение за финала. В работна ситуация поправката е: Върни необходимата информация във всеки самостоятелен епизод; свържи само следващата задача. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Епизод 2 разчита на термин от епизод 1. Какво правиш?","options":[{"id":"a","label":"Не казваш нищо и се надяваш на плейлиста."},{"id":"b","label":"Скриваш термина в субтитрите."},{"id":"c","label":"Даваш кратък контекст и линк към пълното обяснение."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Даваш кратък контекст и линк към пълното обяснение.\n\nПървият слаб ход — Не казваш нищо и се надяваш на плейлиста. — пропуска тази проверка: Всеки епизод решава едно цяло подзадача; зрителят не трябва да гледа реклама, за да разбере безопасното действие. Вторият — Скриваш термина в субтитрите. — оставя този риск: Разрязваш една инструкция на три и държиш критичното предупреждение за финала. В работна ситуация поправката е: Върни необходимата информация във всеки самостоятелен епизод; свържи само следващата задача. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Как проверяваш маршрута?","options":[{"id":"a","label":"Само общата дължина на серията."},{"id":"b","label":"Само броя епизоди."},{"id":"c","label":"Следиш дали зрители преминават към следващата уместна задача и къде отпадат."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Следиш дали зрители преминават към следващата уместна задача и къде отпадат.\n\nПървият слаб ход — Само броя епизоди. — пропуска тази проверка: Всеки епизод решава едно цяло подзадача; зрителят не трябва да гледа реклама, за да разбере безопасното действие. Вторият — Само общата дължина на серията. — оставя този риск: Разрязваш една инструкция на три и държиш критичното предупреждение за финала. В работна ситуация поправката е: Върни необходимата информация във всеки самостоятелен епизод; свържи само следващата задача. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Разрязваш една инструкция на три и държиш критичното предупреждение за финала. Как продължаваш?","options":[{"id":"a","label":"Върни необходимата информация във всеки самостоятелен епизод; свържи само следващата задача."},{"id":"b","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"c","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Върни необходимата информация във всеки самостоятелен епизод; свържи само следващата задача.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Всеки епизод решава едно цяло подзадача; зрителят не трябва да гледа реклама, за да разбере безопасното действие. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Разрязваш една инструкция на три и държиш критичното предупреждение за финала. В работна ситуация поправката е: Върни необходимата информация във всеки самостоятелен епизод; свържи само следващата задача. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s2","text":"За всеки епизод напиши въпрос, действие и изходен артефакт."},{"id":"s3","text":"Провери дали нов човек разбира епизод 2 с кратък контекст."},{"id":"s4","text":"Подготви честен преход към следващата задача, без да криеш отговора."},{"id":"s1","text":"Избери една реална задача и три последователни решения."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Избери една реална задача и три последователни решения.\n2. За всеки епизод напиши въпрос, действие и изходен артефакт.\n3. Провери дали нов човек разбира епизод 2 с кратък контекст.\n4. Подготви честен преход към следващата задача, без да криеш отговора."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Серията се планира около развитие на една задача, не около изкуствено разделяне на един отговор. Всеки епизод трябва да е полезен самостоятелно и да остави логична следваща работа. Запиши какво зрителят вече знае, какво ще направи и какво доказателство ще му трябва. Не задържай ключовия отговор за следващ клип.","Върни необходимата информация във всеки самостоятелен епизод; свържи само следващата задача.","Всеки епизод решава едно цяло подзадача; зрителят не трябва да гледа реклама, за да разбере безопасното действие."],"nextStep":"Напиши карта на серия от три видеа: входно знание, конкретна проверка, видим резултат и естествена връзка."},"points":1,"required":true}]},{"module_id":"s02-m11","lesson_id":"pv11-02","title":"Направи плейлист, който води към правилното следващо видео","subtitle":"Дълъг формат, измерване и решения от реални данни","objective":"Зрителят знае какво ще може след маршрута и не попада на липсваща предпоставка.","hook":"Плейлистът започва с най-новия клип, който изисква инструмент от третото видео.","estimated_minutes":36,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Зрителят знае какво ще може след маршрута и не попада на липсваща предпоставка."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Плейлистът започва с най-новия клип, който изисква инструмент от третото видео."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Редът трябва да намалява пречките пред зрителя. Постави необходимите умения преди задачите, които зависят от тях; не е задължително хронологията на снимките да е редът на учене. Заглавието на плейлиста казва конкретния резултат. Проверявай счупени, остарели и изтрити видеа; маршрутът е жив продукт."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Пази screenshot или export на отчета с дата, видео и избран период. Една крива показва поведение, не причина. Изгледай публикувания файл на точния timecode, сравни зрителското намерение с обещанието и запиши друго възможно обяснение. Малката извадка и промяната на източниците могат да обърнат извода. Предлагай тест за следващото видео и определи кой ще го изпълни и кога ще се върне към данните.\n\nЗа тази задача: Върни входния урок отпред и тествай дали нов зрител може да изпълни първата задача."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Запиши една входна ситуация и какво трябва да знае човекът.\n2. Подреди клиповете според зависимостите и прегледай преходите.\n3. Напиши кратко описание с крайния резултат и ограниченията.\n4. Изгледай маршрута от акаунт без авторски контекст и поправи задънените улици.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Фотографска серия започва с контрол на звук, следва интервю на терен, после монтаж на репликите. Общ „making of“ клип се оставя извън маршрута, защото не дава нужно умение.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Подменяш първия урок с най-гледания, въпреки че той е напреднал."},"after":{"label":"Как го поправяш","text":"Върни входния урок отпред и тествай дали нов зрител може да изпълни първата задача."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Подменяш първия урок с най-гледания, въпреки че той е напреднал.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Запиши една входна ситуация и какво трябва да знае човекът. След него: Напиши кратко описание с крайния резултат и ограниченията.\n\nКорекция: Върни входния урок отпред и тествай дали нов зрител може да изпълни първата задача.\n\nНови данни, които ще приемеш за успешна поправка: Зрителят знае какво ще може след маршрута и не попада на липсваща предпоставка. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Пренареди пет видеа или сценария в плейлист; към всяка връзка напиши отговор на „защо това следва сега?“.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Зрителят знае какво ще може след маршрута и не попада на липсваща предпоставка.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Фотографска серия започва с контрол на звук, следва интервю на терен, после монтаж на репликите. Общ „making of“ клип се оставя извън маршрута, защото не дава нужно умение.\n\nДоставка: Пренареди пет видеа или сценария в плейлист; към всяка връзка напиши отговор на „защо това следва сега?“.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Зрителят знае какво ще може след маршрута и не попада на липсваща предпоставка."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Проверен първоизточник","content":{"body":"YouTube Help — YouTube Analytics: https://support.google.com/youtube/answer/9002587\nПровери текущата версия на функцията преди да повториш стъпките."},"points":0,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Кой ред е най-полезен?","options":[{"id":"a","label":"По дължина на файла."},{"id":"b","label":"По нужните умения за следващата задача."},{"id":"c","label":"По дата на заснемане."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: По нужните умения за следващата задача.\n\nПървият слаб ход — По дата на заснемане. — пропуска тази проверка: Зрителят знае какво ще може след маршрута и не попада на липсваща предпоставка. Вторият — По дължина на файла. — оставя този риск: Подменяш първия урок с най-гледания, въпреки че той е напреднал. В работна ситуация поправката е: Върни входния урок отпред и тествай дали нов зрител може да изпълни първата задача. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Един клип е изтрит. Какво правиш?","options":[{"id":"a","label":"Обновяваш прехода и описанието, после проверяваш останалия маршрут."},{"id":"b","label":"Слагаш несвързана реклама на негово място."},{"id":"c","label":"Оставяш празната стъпка."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Обновяваш прехода и описанието, после проверяваш останалия маршрут.\n\nПървият слаб ход — Оставяш празната стъпка. — пропуска тази проверка: Зрителят знае какво ще може след маршрута и не попада на липсваща предпоставка. Вторият — Слагаш несвързана реклама на негово място. — оставя този риск: Подменяш първия урок с най-гледания, въпреки че той е напреднал. В работна ситуация поправката е: Върни входния урок отпред и тествай дали нов зрител може да изпълни първата задача. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Какъв сигнал следиш?","options":[{"id":"a","label":"Само общите абонати."},{"id":"b","label":"Само броя клипове."},{"id":"c","label":"Дали подходящи зрители стигат до следващата стъпка и я разбират."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Дали подходящи зрители стигат до следващата стъпка и я разбират.\n\nПървият слаб ход — Само общите абонати. — пропуска тази проверка: Зрителят знае какво ще може след маршрута и не попада на липсваща предпоставка. Вторият — Само броя клипове. — оставя този риск: Подменяш първия урок с най-гледания, въпреки че той е напреднал. В работна ситуация поправката е: Върни входния урок отпред и тествай дали нов зрител може да изпълни първата задача. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Подменяш първия урок с най-гледания, въпреки че той е напреднал. Как продължаваш?","options":[{"id":"a","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"b","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"c","label":"Върни входния урок отпред и тествай дали нов зрител може да изпълни първата задача."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Върни входния урок отпред и тествай дали нов зрител може да изпълни първата задача.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Зрителят знае какво ще може след маршрута и не попада на липсваща предпоставка. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Подменяш първия урок с най-гледания, въпреки че той е напреднал. В работна ситуация поправката е: Върни входния урок отпред и тествай дали нов зрител може да изпълни първата задача. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s2","text":"Подреди клиповете според зависимостите и прегледай преходите."},{"id":"s1","text":"Запиши една входна ситуация и какво трябва да знае човекът."},{"id":"s4","text":"Изгледай маршрута от акаунт без авторски контекст и поправи задънените улици."},{"id":"s3","text":"Напиши кратко описание с крайния резултат и ограниченията."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Запиши една входна ситуация и какво трябва да знае човекът.\n2. Подреди клиповете според зависимостите и прегледай преходите.\n3. Напиши кратко описание с крайния резултат и ограниченията.\n4. Изгледай маршрута от акаунт без авторски контекст и поправи задънените улици."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Редът трябва да намалява пречките пред зрителя. Постави необходимите умения преди задачите, които зависят от тях; не е задължително хронологията на снимките да е редът на учене. Заглавието на плейлиста казва конкретния резултат. Проверявай счупени, остарели и изтрити видеа; маршрутът е жив продукт.","Върни входния урок отпред и тествай дали нов зрител може да изпълни първата задача.","Зрителят знае какво ще може след маршрута и не попада на липсваща предпоставка."],"nextStep":"Пренареди пет видеа или сценария в плейлист; към всяка връзка напиши отговор на „защо това следва сега?“."},"points":1,"required":true}]},{"module_id":"s02-m11","lesson_id":"pv11-03","title":"Избери устойчива тема и планирай кога да я обновиш","subtitle":"Дълъг формат, измерване и решения от реални данни","objective":"Урокът посочва версията и има ясен план за актуализация; критичните стъпки не зависят от стара снимка.","hook":"Тема „вечна“ обещава същия интерфейс, въпреки че екраните са сменени.","estimated_minutes":36,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Урокът посочва версията и има ясен план за актуализация; критичните стъпки не зависят от стара снимка."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Тема „вечна“ обещава същия интерфейс, въпреки че екраните са сменени."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Устойчивата тема е дълготраен въпрос, не непроменлива инструкция. Отдели стабилния принцип от променливите менюта, цени, правила и технически версии. Запиши дата на проверка и собственик на актуализацията. Избери тема, за която можеш да поддържаш точен отговор и да покажеш реален пример."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Пази screenshot или export на отчета с дата, видео и избран период. Една крива показва поведение, не причина. Изгледай публикувания файл на точния timecode, сравни зрителското намерение с обещанието и запиши друго възможно обяснение. Малката извадка и промяната на източниците могат да обърнат извода. Предлагай тест за следващото видео и определи кой ще го изпълни и кога ще се върне към данните.\n\nЗа тази задача: Провери актуалния източник и обнови или свали подвеждащата част."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Събери три повтарящи се въпроса от хора, не от генератор на заглавия.\n2. Отдели принцип, който остава, от интерфейс и условия, които се сменят.\n3. Снимай пример, като назовеш версия и граници.\n4. Задай календар и критерий за преглед след промени.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Видео „как да провериш звук преди снимка“ остава полезно с нов телефон; кадрите на конкретно меню се заснемат наново при голяма промяна и описанието получава дата.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Оставяш стара инструкция за плащане или поверителност като „evergreen“."},"after":{"label":"Как го поправяш","text":"Провери актуалния източник и обнови или свали подвеждащата част."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Оставяш стара инструкция за плащане или поверителност като „evergreen“.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Събери три повтарящи се въпроса от хора, не от генератор на заглавия. След него: Снимай пример, като назовеш версия и граници.\n\nКорекция: Провери актуалния източник и обнови или свали подвеждащата част.\n\nНови данни, които ще приемеш за успешна поправка: Урокът посочва версията и има ясен план за актуализация; критичните стъпки не зависят от стара снимка. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Планирай устойчив урок: стабилен принцип, конкретна демонстрация, три променливи детайла и събитие, което задейства преглед.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Урокът посочва версията и има ясен план за актуализация; критичните стъпки не зависят от стара снимка.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Видео „как да провериш звук преди снимка“ остава полезно с нов телефон; кадрите на конкретно меню се заснемат наново при голяма промяна и описанието получава дата.\n\nДоставка: Планирай устойчив урок: стабилен принцип, конкретна демонстрация, три променливи детайла и събитие, което задейства преглед.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Урокът посочва версията и има ясен план за актуализация; критичните стъпки не зависят от стара снимка."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Кое е устойчива тема?","options":[{"id":"a","label":"Всеки тренд от тази седмица."},{"id":"b","label":"Повтарящ се проблем с отделени принцип и променлив интерфейс."},{"id":"c","label":"Инструкция без дата за бързо сменящо се меню."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Повтарящ се проблем с отделени принцип и променлив интерфейс.\n\nПървият слаб ход — Всеки тренд от тази седмица. — пропуска тази проверка: Урокът посочва версията и има ясен план за актуализация; критичните стъпки не зависят от стара снимка. Вторият — Инструкция без дата за бързо сменящо се меню. — оставя този риск: Оставяш стара инструкция за плащане или поверителност като „evergreen“. В работна ситуация поправката е: Провери актуалния източник и обнови или свали подвеждащата част. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Платформата сменя стъпките. Какво правиш?","options":[{"id":"a","label":"Сменяш само миниатюрата."},{"id":"b","label":"Проверяваш и обновяваш видеото/описанието или ясно обозначаваш остарялото."},{"id":"c","label":"Оставяш го, защото има гледания."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Проверяваш и обновяваш видеото/описанието или ясно обозначаваш остарялото.\n\nПървият слаб ход — Оставяш го, защото има гледания. — пропуска тази проверка: Урокът посочва версията и има ясен план за актуализация; критичните стъпки не зависят от стара снимка. Вторият — Сменяш само миниатюрата. — оставя този риск: Оставяш стара инструкция за плащане или поверителност като „evergreen“. В работна ситуация поправката е: Провери актуалния източник и обнови или свали подвеждащата част. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Кой праг за преглед записваш?","options":[{"id":"a","label":"Промяна в процес, версия или официална инструкция, която засяга действието."},{"id":"b","label":"Случаен ден без собственик."},{"id":"c","label":"Само спад на лайковете."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Промяна в процес, версия или официална инструкция, която засяга действието.\n\nПървият слаб ход — Само спад на лайковете. — пропуска тази проверка: Урокът посочва версията и има ясен план за актуализация; критичните стъпки не зависят от стара снимка. Вторият — Случаен ден без собственик. — оставя този риск: Оставяш стара инструкция за плащане или поверителност като „evergreen“. В работна ситуация поправката е: Провери актуалния източник и обнови или свали подвеждащата част. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Оставяш стара инструкция за плащане или поверителност като „evergreen“. Как продължаваш?","options":[{"id":"a","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"b","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"c","label":"Провери актуалния източник и обнови или свали подвеждащата част."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Провери актуалния източник и обнови или свали подвеждащата част.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Урокът посочва версията и има ясен план за актуализация; критичните стъпки не зависят от стара снимка. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Оставяш стара инструкция за плащане или поверителност като „evergreen“. В работна ситуация поправката е: Провери актуалния източник и обнови или свали подвеждащата част. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s4","text":"Задай календар и критерий за преглед след промени."},{"id":"s1","text":"Събери три повтарящи се въпроса от хора, не от генератор на заглавия."},{"id":"s2","text":"Отдели принцип, който остава, от интерфейс и условия, които се сменят."},{"id":"s3","text":"Снимай пример, като назовеш версия и граници."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Събери три повтарящи се въпроса от хора, не от генератор на заглавия.\n2. Отдели принцип, който остава, от интерфейс и условия, които се сменят.\n3. Снимай пример, като назовеш версия и граници.\n4. Задай календар и критерий за преглед след промени."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Устойчивата тема е дълготраен въпрос, не непроменлива инструкция. Отдели стабилния принцип от променливите менюта, цени, правила и технически версии. Запиши дата на проверка и собственик на актуализацията. Избери тема, за която можеш да поддържаш точен отговор и да покажеш реален пример.","Провери актуалния източник и обнови или свали подвеждащата част.","Урокът посочва версията и има ясен план за актуализация; критичните стъпки не зависят от стара снимка."],"nextStep":"Планирай устойчив урок: стабилен принцип, конкретна демонстрация, три променливи детайла и събитие, което задейства преглед."},"points":1,"required":true}]},{"module_id":"s02-m11","lesson_id":"pv11-04","title":"Разбери откъде идват зрителите, преди да смениш видеото","subtitle":"Дълъг формат, измерване и решения от реални данни","objective":"Решението е свързано с действителен източник и не твърди причинност само от един графичен пик.","hook":"Видеото получава повече гледания, но каналът е решил, че те идват от търсене, без да отвори Reach.","estimated_minutes":36,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Решението е свързано с действителен източник и не твърди причинност само от един графичен пик."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Видеото получава повече гледания, но каналът е решил, че те идват от търсене, без да отвори Reach."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Източникът показва къде е намерен клипът, а не непременно защо зрителят го е харесал. В YouTube различавай Search, Browse, Suggested, външни източници и другите налични категории. Гледай период, абсолютни числа, част от общото и поведение след клика. Не преименувай Home, Browse и Suggested като едно и също."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Пази screenshot или export на отчета с дата, видео и избран период. Една крива показва поведение, не причина. Изгледай публикувания файл на точния timecode, сравни зрителското намерение с обещанието и запиши друго възможно обяснение. Малката извадка и промяната на източниците могат да обърнат извода. Предлагай тест за следващото видео и определи кой ще го изпълни и кога ще се върне към данните.\n\nЗа тази задача: Изолирай източника и деня на пика преди творческо решение."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Отвори Reach за едно видео и запиши период и общи гледания.\n2. Извади основните traffic sources с абсолютен брой и дял.\n3. Сравни релевантния сегмент с началото и задържането на същото видео.\n4. Формулирай една проверима хипотеза за следващ клип.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Канал с урок за монтаж вижда много Search трафик за конкретна грешка. Вместо да променя всички заглавия към тренд, добавя ясно обяснение за грешката и проверява дали зрителят стига до решението.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Сменяш интрото на цялата серия, защото една външна публикация е донесла пик."},"after":{"label":"Как го поправяш","text":"Изолирай източника и деня на пика преди творческо решение."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Сменяш интрото на цялата серия, защото една външна публикация е донесла пик.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Отвори Reach за едно видео и запиши период и общи гледания. След него: Сравни релевантния сегмент с началото и задържането на същото видео.\n\nКорекция: Изолирай източника и деня на пика преди творческо решение.\n\nНови данни, които ще приемеш за успешна поправка: Решението е свързано с действителен източник и не твърди причинност само от един графичен пик. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Направи карта на трафика за реален клип или предоставен отчет; напиши източник, период, вероятно намерение и едно неизвестно.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Решението е свързано с действителен източник и не твърди причинност само от един графичен пик.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Канал с урок за монтаж вижда много Search трафик за конкретна грешка. Вместо да променя всички заглавия към тренд, добавя ясно обяснение за грешката и проверява дали зрителят стига до решението.\n\nДоставка: Направи карта на трафика за реален клип или предоставен отчет; напиши източник, период, вероятно намерение и едно неизвестно.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Решението е свързано с действителен източник и не твърди причинност само от един графичен пик."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Проверен първоизточник","content":{"body":"YouTube Help — Reach, източници на трафик и CTR: https://support.google.com/youtube/answer/9314355\nПровери текущата версия на функцията преди да повториш стъпките."},"points":0,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Как четеш traffic source?","options":[{"id":"a","label":"Като място на откриване, което тълкуваш с период и поведение."},{"id":"b","label":"Като доказателство за качество само по себе си."},{"id":"c","label":"Като неизменна характеристика на канала."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Като място на откриване, което тълкуваш с период и поведение.\n\nПървият слаб ход — Като доказателство за качество само по себе си. — пропуска тази проверка: Решението е свързано с действителен източник и не твърди причинност само от един графичен пик. Вторият — Като неизменна характеристика на канала. — оставя този риск: Сменяш интрото на цялата серия, защото една външна публикация е донесла пик. В работна ситуация поправката е: Изолирай източника и деня на пика преди творческо решение. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Външен сайт дава еднодневен пик. Какво правиш?","options":[{"id":"a","label":"Приемаш, че новото заглавие е причината."},{"id":"b","label":"Маркираш събитието и не променяш цялата стратегия по него."},{"id":"c","label":"Събираш всички източници в „Search“."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Маркираш събитието и не променяш цялата стратегия по него.\n\nПървият слаб ход — Приемаш, че новото заглавие е причината. — пропуска тази проверка: Решението е свързано с действителен източник и не твърди причинност само от един графичен пик. Вторият — Събираш всички източници в „Search“. — оставя този риск: Сменяш интрото на цялата серия, защото една външна публикация е донесла пик. В работна ситуация поправката е: Изолирай източника и деня на пика преди творческо решение. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Какъв контекст записваш?","options":[{"id":"a","label":"Само screenshot без дата."},{"id":"b","label":"Период, брой и дял по източник плюс поведение на зрителя."},{"id":"c","label":"Само най-големия процент."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Период, брой и дял по източник плюс поведение на зрителя.\n\nПървият слаб ход — Само най-големия процент. — пропуска тази проверка: Решението е свързано с действителен източник и не твърди причинност само от един графичен пик. Вторият — Само screenshot без дата. — оставя този риск: Сменяш интрото на цялата серия, защото една външна публикация е донесла пик. В работна ситуация поправката е: Изолирай източника и деня на пика преди творческо решение. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Сменяш интрото на цялата серия, защото една външна публикация е донесла пик. Как продължаваш?","options":[{"id":"a","label":"Изолирай източника и деня на пика преди творческо решение."},{"id":"b","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"c","label":"Продължаваш без проверка и наричаш тази версия окончателна."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Изолирай източника и деня на пика преди творческо решение.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Решението е свързано с действителен източник и не твърди причинност само от един графичен пик. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Сменяш интрото на цялата серия, защото една външна публикация е донесла пик. В работна ситуация поправката е: Изолирай източника и деня на пика преди творческо решение. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s4","text":"Формулирай една проверима хипотеза за следващ клип."},{"id":"s3","text":"Сравни релевантния сегмент с началото и задържането на същото видео."},{"id":"s2","text":"Извади основните traffic sources с абсолютен брой и дял."},{"id":"s1","text":"Отвори Reach за едно видео и запиши период и общи гледания."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Отвори Reach за едно видео и запиши период и общи гледания.\n2. Извади основните traffic sources с абсолютен брой и дял.\n3. Сравни релевантния сегмент с началото и задържането на същото видео.\n4. Формулирай една проверима хипотеза за следващ клип."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Източникът показва къде е намерен клипът, а не непременно защо зрителят го е харесал. В YouTube различавай Search, Browse, Suggested, външни източници и другите налични категории. Гледай период, абсолютни числа, част от общото и поведение след клика. Не преименувай Home, Browse и Suggested като едно и също.","Изолирай източника и деня на пика преди творческо решение.","Решението е свързано с действителен източник и не твърди причинност само от един графичен пик."],"nextStep":"Направи карта на трафика за реален клип или предоставен отчет; напиши източник, период, вероятно намерение и едно неизвестно."},"points":1,"required":true}]},{"module_id":"s02-m11","lesson_id":"pv11-05","title":"Чети графиката за задържане като сигнал, не като диагноза","subtitle":"Дълъг формат, измерване и решения от реални данни","objective":"Нито един извод не е само „графиката пада“; всяка хипотеза сочи конкретна сцена и следващ тест.","hook":"На графиката има спад след 2:10. Монтажистът веднага изрязва 20 секунди, без да гледа сцената.","estimated_minutes":38,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Нито един извод не е само „графиката пада“; всяка хипотеза сочи конкретна сцена и следващ тест."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"На графиката има спад след 2:10. Монтажистът веднага изрязва 20 секунди, без да гледа сцената."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Retention показва какво се е случило със зрителите в измерения период, не причината. Съпостави графиката с точното място в timeline, обещанието, източниците и различните зрители, ако отчетът ги показва. Платформата може да обработва данните със закъснение. Прегледай зрителско поведение и съдържание, после предложи конкретна промяна за бъдеща версия."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Пази screenshot или export на отчета с дата, видео и избран период. Една крива показва поведение, не причина. Изгледай публикувания файл на точния timecode, сравни зрителското намерение с обещанието и запиши друго възможно обяснение. Малката извадка и промяната на източниците могат да обърнат извода. Предлагай тест за следващото видео и определи кой ще го изпълни и кога ще се върне към данните.\n\nЗа тази задача: Върни се към действителните кадри и намерението на зрителя; отдели нормалното излизане след решена задача."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Избери видео с достатъчно данни и запиши дата на отчета.\n2. Маркирай спад, пик и равен участък с timecode.\n3. Изгледай 20 секунди преди и след всеки момент със звук.\n4. Запиши поне две възможни причини и един тест за следващ монтаж.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"При урок за камерата спадът съвпада с дълъг списък спецификации. Екипът вижда, че демонстрацията започва след него, и планира следващия клип да покаже резултата преди таблицата.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Наричаш всеки спад „скучна сцена“ без да провериш завършил ли е отговорът."},"after":{"label":"Как го поправяш","text":"Върни се към действителните кадри и намерението на зрителя; отдели нормалното излизане след решена задача."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Наричаш всеки спад „скучна сцена“ без да провериш завършил ли е отговорът.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Избери видео с достатъчно данни и запиши дата на отчета. След него: Изгледай 20 секунди преди и след всеки момент със звук.\n\nКорекция: Върни се към действителните кадри и намерението на зрителя; отдели нормалното излизане след решена задача.\n\nНови данни, които ще приемеш за успешна поправка: Нито един извод не е само „графиката пада“; всяка хипотеза сочи конкретна сцена и следващ тест. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Извлечи три timecode-а от реален отчет или учебен пример; за всеки опиши наблюдение, възможно обяснение и как ще го провериш.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Нито един извод не е само „графиката пада“; всяка хипотеза сочи конкретна сцена и следващ тест.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: При урок за камерата спадът съвпада с дълъг списък спецификации. Екипът вижда, че демонстрацията започва след него, и планира следващия клип да покаже резултата преди таблицата.\n\nДоставка: Извлечи три timecode-а от реален отчет или учебен пример; за всеки опиши наблюдение, възможно обяснение и как ще го провериш.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Нито един извод не е само „графиката пада“; всяка хипотеза сочи конкретна сцена и следващ тест."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Проверен първоизточник","content":{"body":"YouTube Help — Key moments for audience retention: https://support.google.com/youtube/answer/9314415\nПровери текущата версия на функцията преди да повториш стъпките."},"points":0,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Какво доказва спадът?","options":[{"id":"a","label":"Че трябва да се изрежат точно 20 секунди."},{"id":"b","label":"Че музиката е грешна."},{"id":"c","label":"Че част от зрителите са напуснали в този момент, но не защо."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Че част от зрителите са напуснали в този момент, но не защо.\n\nПървият слаб ход — Че музиката е грешна. — пропуска тази проверка: Нито един извод не е само „графиката пада“; всяка хипотеза сочи конкретна сцена и следващ тест. Вторият — Че трябва да се изрежат точно 20 секунди. — оставя този риск: Наричаш всеки спад „скучна сцена“ без да провериш завършил ли е отговорът. В работна ситуация поправката е: Върни се към действителните кадри и намерението на зрителя; отдели нормалното излизане след решена задача. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Спадът е след края на отговора. Как го тълкуваш?","options":[{"id":"a","label":"Проверяваш дали задачата вече е изпълнена и каква следваща стъпка има."},{"id":"b","label":"Обвиняваш интрото."},{"id":"c","label":"Изтриваш целия клип."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Проверяваш дали задачата вече е изпълнена и каква следваща стъпка има.\n\nПървият слаб ход — Обвиняваш интрото. — пропуска тази проверка: Нито един извод не е само „графиката пада“; всяка хипотеза сочи конкретна сцена и следващ тест. Вторият — Изтриваш целия клип. — оставя този риск: Наричаш всеки спад „скучна сцена“ без да провериш завършил ли е отговорът. В работна ситуация поправката е: Върни се към действителните кадри и намерението на зрителя; отдели нормалното излизане след решена задача. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Какво сравняваш?","options":[{"id":"a","label":"Само средния процент."},{"id":"b","label":"Timecode, сцена, източник и група зрители, ако данните позволяват."},{"id":"c","label":"Само чужд канал с друга тема."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Timecode, сцена, източник и група зрители, ако данните позволяват.\n\nПървият слаб ход — Само средния процент. — пропуска тази проверка: Нито един извод не е само „графиката пада“; всяка хипотеза сочи конкретна сцена и следващ тест. Вторият — Само чужд канал с друга тема. — оставя този риск: Наричаш всеки спад „скучна сцена“ без да провериш завършил ли е отговорът. В работна ситуация поправката е: Върни се към действителните кадри и намерението на зрителя; отдели нормалното излизане след решена задача. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Наричаш всеки спад „скучна сцена“ без да провериш завършил ли е отговорът. Как продължаваш?","options":[{"id":"a","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"b","label":"Върни се към действителните кадри и намерението на зрителя; отдели нормалното излизане след решена задача."},{"id":"c","label":"Продължаваш без проверка и наричаш тази версия окончателна."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Върни се към действителните кадри и намерението на зрителя; отдели нормалното излизане след решена задача.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Нито един извод не е само „графиката пада“; всяка хипотеза сочи конкретна сцена и следващ тест. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Наричаш всеки спад „скучна сцена“ без да провериш завършил ли е отговорът. В работна ситуация поправката е: Върни се към действителните кадри и намерението на зрителя; отдели нормалното излизане след решена задача. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s2","text":"Маркирай спад, пик и равен участък с timecode."},{"id":"s3","text":"Изгледай 20 секунди преди и след всеки момент със звук."},{"id":"s4","text":"Запиши поне две възможни причини и един тест за следващ монтаж."},{"id":"s1","text":"Избери видео с достатъчно данни и запиши дата на отчета."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Избери видео с достатъчно данни и запиши дата на отчета.\n2. Маркирай спад, пик и равен участък с timecode.\n3. Изгледай 20 секунди преди и след всеки момент със звук.\n4. Запиши поне две възможни причини и един тест за следващ монтаж."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Retention показва какво се е случило със зрителите в измерения период, не причината. Съпостави графиката с точното място в timeline, обещанието, източниците и различните зрители, ако отчетът ги показва. Платформата може да обработва данните със закъснение. Прегледай зрителско поведение и съдържание, после предложи конкретна промяна за бъдеща версия.","Върни се към действителните кадри и намерението на зрителя; отдели нормалното излизане след решена задача.","Нито един извод не е само „графиката пада“; всяка хипотеза сочи конкретна сцена и следващ тест."],"nextStep":"Извлечи три timecode-а от реален отчет или учебен пример; за всеки опиши наблюдение, възможно обяснение и как ще го провериш."},"points":1,"required":true}]},{"module_id":"s02-m11","lesson_id":"pv11-06","title":"Добави глави, които отговарят на реалните въпроси","subtitle":"Дълъг формат, измерване и решения от реални данни","objective":"Друг човек стига до търсения отговор и времевите марки отварят верния момент.","hook":"Главите са „Въведение“, „Част 2“, „Част 3“; никой не знае къде е отговорът.","estimated_minutes":36,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Друг човек стига до търсения отговор и времевите марки отварят верния момент."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Главите са „Въведение“, „Част 2“, „Част 3“; никой не знае къде е отговорът."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Главите трябва да отразяват реални смени на въпрос или действие. Прегледай видеото, запиши точния начален момент на всяка част и назови какво зрителят ще намери там. Не измисляй глава за нещо, което не се вижда. Провери актуалните изисквания на платформата за глави и дали ръчните времеви марки работят в публикувания клип."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Пази screenshot или export на отчета с дата, видео и избран период. Една крива показва поведение, не причина. Изгледай публикувания файл на точния timecode, сравни зрителското намерение с обещанието и запиши друго възможно обяснение. Малката извадка и промяната на източниците могат да обърнат извода. Предлагай тест за следващото видео и определи кой ще го изпълни и кога ще се върне към данните.\n\nЗа тази задача: Премести границата към реалния въпрос; премахни излишни маркери."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Изгледай цялото видео и маркирай смисловите преходи.\n2. Напиши заглавия с действие/въпрос вместо номера.\n3. Свери timecode-а с реалния export, не със стара timeline версия.\n4. Отвори всяка глава след публикация и провери кадъра и текста.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Интервю за малък бизнес има глава „Как избрахме цена“, започваща при първия конкретен пример, а не в средата на отговора за бюджет.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Поставяш марки по минути механично и главата започва след отговора."},"after":{"label":"Как го поправяш","text":"Премести границата към реалния въпрос; премахни излишни маркери."}},"points":2,"required":true},{"position":7,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Добави глави към свое или разрешено дълго видео; помоли друг човек да намери конкретен отговор само по тях.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Друг човек стига до търсения отговор и времевите марки отварят верния момент.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":9,"block_key":"reference","block_type":"rich_text","title":"Проверен първоизточник","content":{"body":"YouTube Help — YouTube Analytics: https://support.google.com/youtube/answer/9002587\nПровери текущата версия на функцията преди да повториш стъпките."},"points":0,"required":false},{"position":10,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Кое е добра глава?","options":[{"id":"a","label":"„Част 4“ на кръгла минута."},{"id":"b","label":"Ключова дума без такъв сегмент."},{"id":"c","label":"„Проверка на звука преди интервю“ на действителното начало на проверката."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: „Проверка на звука преди интервю“ на действителното начало на проверката.\n\nПървият слаб ход — „Част 4“ на кръгла минута. — пропуска тази проверка: Друг човек стига до търсения отговор и времевите марки отварят верния момент. Вторият — Ключова дума без такъв сегмент. — оставя този риск: Поставяш марки по минути механично и главата започва след отговора. В работна ситуация поправката е: Премести границата към реалния въпрос; премахни излишни маркери. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Export-ът е съкратен с 18 секунди. Какво правиш?","options":[{"id":"a","label":"Премахваш само първата глава."},{"id":"b","label":"Оставяш старите от timeline."},{"id":"c","label":"Сверяваш и поправяш всички timecode-и по публикувания файл."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Сверяваш и поправяш всички timecode-и по публикувания файл.\n\nПървият слаб ход — Оставяш старите от timeline. — пропуска тази проверка: Друг човек стига до търсения отговор и времевите марки отварят верния момент. Вторият — Премахваш само първата глава. — оставя този риск: Поставяш марки по минути механично и главата започва след отговора. В работна ситуация поправката е: Премести границата към реалния въпрос; премахни излишни маркери. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Каква е най-пряката проверка?","options":[{"id":"a","label":"Друг човек намира отговор чрез публикуваните глави."},{"id":"b","label":"Само броя глави."},{"id":"c","label":"Само тяхната дължина."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Друг човек намира отговор чрез публикуваните глави.\n\nПървият слаб ход — Само броя глави. — пропуска тази проверка: Друг човек стига до търсения отговор и времевите марки отварят верния момент. Вторият — Само тяхната дължина. — оставя този риск: Поставяш марки по минути механично и главата започва след отговора. В работна ситуация поправката е: Премести границата към реалния въпрос; премахни излишни маркери. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Поставяш марки по минути механично и главата започва след отговора. Как продължаваш?","options":[{"id":"a","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"b","label":"Премести границата към реалния въпрос; премахни излишни маркери."},{"id":"c","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Премести границата към реалния въпрос; премахни излишни маркери.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Друг човек стига до търсения отговор и времевите марки отварят верния момент. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Поставяш марки по минути механично и главата започва след отговора. В работна ситуация поправката е: Премести границата към реалния въпрос; премахни излишни маркери. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s2","text":"Напиши заглавия с действие/въпрос вместо номера."},{"id":"s1","text":"Изгледай цялото видео и маркирай смисловите преходи."},{"id":"s4","text":"Отвори всяка глава след публикация и провери кадъра и текста."},{"id":"s3","text":"Свери timecode-а с реалния export, не със стара timeline версия."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Изгледай цялото видео и маркирай смисловите преходи.\n2. Напиши заглавия с действие/въпрос вместо номера.\n3. Свери timecode-а с реалния export, не със стара timeline версия.\n4. Отвори всяка глава след публикация и провери кадъра и текста."},"scoring":{"mode":"exact_order"}},{"position":15,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Главите трябва да отразяват реални смени на въпрос или действие. Прегледай видеото, запиши точния начален момент на всяка част и назови какво зрителят ще намери там. Не измисляй глава за нещо, което не се вижда. Провери актуалните изисквания на платформата за глави и дали ръчните времеви марки работят в публикувания клип.","Премести границата към реалния въпрос; премахни излишни маркери.","Друг човек стига до търсения отговор и времевите марки отварят верния момент."],"nextStep":"Добави глави към свое или разрешено дълго видео; помоли друг човек да намери конкретен отговор само по тях."},"points":1,"required":true}]},{"module_id":"s02-m11","lesson_id":"pv11-07","title":"Напиши сценарий с развитие, а не с безкрайно закачане","subtitle":"Дълъг формат, измерване и решения от реални данни","objective":"Има развитие и проверим финален извод; никоя част не съществува само за да увеличи продължителността.","hook":"Първите 15 секунди са шумен hook, после 12 минути клипът няма посока.","estimated_minutes":36,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Има развитие и проверим финален извод; никоя част не съществува само за да увеличи продължителността."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Първите 15 секунди са шумен hook, после 12 минути клипът няма посока."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Дългият сценарий обещава развитие: въпрос, условия, опит, усложнение, проверка и извод. Зрителят трябва да знае защо следващата сцена е нужна. Планирай доказателство за твърденията и паузи за разбиране. Ако имаш реален обрат, покажи как си стигнал до него; не създавай фалшива драма."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Пази screenshot или export на отчета с дата, видео и избран период. Една крива показва поведение, не причина. Изгледай публикувания файл на точния timecode, сравни зрителското намерение с обещанието и запиши друго възможно обяснение. Малката извадка и промяната на източниците могат да обърнат извода. Предлагай тест за следващото видео и определи кой ще го изпълни и кога ще се върне към данните.\n\nЗа тази задача: Дай на всяка част ново наблюдение или я съкрати; задръж само нужния контекст."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Запиши въпроса и промяната, която зрителят ще разбере накрая.\n2. Раздели видеото на сцени с действие и доказателство, не на абстрактни теми.\n3. За всяка сцена посочи какво променя в решението.\n4. Прочети сценария на глас и премахни повторенията без функция.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Документален клип за семейна пекарна започва с проблем при ранното производство, показва две проби и завършва с реално решение и какво още не е известно. Няма измислен „секрет“ за задържане.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Повтаряш обещанието през три минути, без да даваш нов факт."},"after":{"label":"Как го поправяш","text":"Дай на всяка част ново наблюдение или я съкрати; задръж само нужния контекст."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Повтаряш обещанието през три минути, без да даваш нов факт.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Запиши въпроса и промяната, която зрителят ще разбере накрая. След него: За всяка сцена посочи какво променя в решението.\n\nКорекция: Дай на всяка част ново наблюдение или я съкрати; задръж само нужния контекст.\n\nНови данни, които ще приемеш за успешна поправка: Има развитие и проверим финален извод; никоя част не съществува само за да увеличи продължителността. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Напиши outline за 8–12 минути: шест сцени, доказателство за всяка и точната връзка между две съседни сцени.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Има развитие и проверим финален извод; никоя част не съществува само за да увеличи продължителността.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Документален клип за семейна пекарна започва с проблем при ранното производство, показва две проби и завършва с реално решение и какво още не е известно. Няма измислен „секрет“ за задържане.\n\nДоставка: Напиши outline за 8–12 минути: шест сцени, доказателство за всяка и точната връзка между две съседни сцени.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Има развитие и проверим финален извод; никоя част не съществува само за да увеличи продължителността."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Кое държи дълъг сценарий?","options":[{"id":"a","label":"Последователни решения и доказателства, които развиват въпроса."},{"id":"b","label":"Максимално много преходи без нов факт."},{"id":"c","label":"Един силен hook и повтаряне на teaser."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Последователни решения и доказателства, които развиват въпроса.\n\nПървият слаб ход — Един силен hook и повтаряне на teaser. — пропуска тази проверка: Има развитие и проверим финален извод; никоя част не съществува само за да увеличи продължителността. Вторият — Максимално много преходи без нов факт. — оставя този риск: Повтаряш обещанието през три минути, без да даваш нов факт. В работна ситуация поправката е: Дай на всяка част ново наблюдение или я съкрати; задръж само нужния контекст. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Средната част няма ново действие. Какво правиш?","options":[{"id":"a","label":"Усилваш музиката."},{"id":"b","label":"Слагаш недоказан конфликт."},{"id":"c","label":"Добавяш реален тест или съкращаваш повторението."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Добавяш реален тест или съкращаваш повторението.\n\nПървият слаб ход — Усилваш музиката. — пропуска тази проверка: Има развитие и проверим финален извод; никоя част не съществува само за да увеличи продължителността. Вторият — Слагаш недоказан конфликт. — оставя този риск: Повтаряш обещанието през три минути, без да даваш нов факт. В работна ситуация поправката е: Дай на всяка част ново наблюдение или я съкрати; задръж само нужния контекст. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Как проверяваш структурата преди снимки?","options":[{"id":"a","label":"Само броя hook фрази."},{"id":"b","label":"Само броя страници."},{"id":"c","label":"Всяка сцена има функция, материал и следващ въпрос."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Всяка сцена има функция, материал и следващ въпрос.\n\nПървият слаб ход — Само броя страници. — пропуска тази проверка: Има развитие и проверим финален извод; никоя част не съществува само за да увеличи продължителността. Вторият — Само броя hook фрази. — оставя този риск: Повтаряш обещанието през три минути, без да даваш нов факт. В работна ситуация поправката е: Дай на всяка част ново наблюдение или я съкрати; задръж само нужния контекст. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Повтаряш обещанието през три минути, без да даваш нов факт. Как продължаваш?","options":[{"id":"a","label":"Дай на всяка част ново наблюдение или я съкрати; задръж само нужния контекст."},{"id":"b","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"c","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Дай на всяка част ново наблюдение или я съкрати; задръж само нужния контекст.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Има развитие и проверим финален извод; никоя част не съществува само за да увеличи продължителността. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Повтаряш обещанието през три минути, без да даваш нов факт. В работна ситуация поправката е: Дай на всяка част ново наблюдение или я съкрати; задръж само нужния контекст. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s4","text":"Прочети сценария на глас и премахни повторенията без функция."},{"id":"s1","text":"Запиши въпроса и промяната, която зрителят ще разбере накрая."},{"id":"s2","text":"Раздели видеото на сцени с действие и доказателство, не на абстрактни теми."},{"id":"s3","text":"За всяка сцена посочи какво променя в решението."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Запиши въпроса и промяната, която зрителят ще разбере накрая.\n2. Раздели видеото на сцени с действие и доказателство, не на абстрактни теми.\n3. За всяка сцена посочи какво променя в решението.\n4. Прочети сценария на глас и премахни повторенията без функция."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Дългият сценарий обещава развитие: въпрос, условия, опит, усложнение, проверка и извод. Зрителят трябва да знае защо следващата сцена е нужна. Планирай доказателство за твърденията и паузи за разбиране. Ако имаш реален обрат, покажи как си стигнал до него; не създавай фалшива драма.","Дай на всяка част ново наблюдение или я съкрати; задръж само нужния контекст.","Има развитие и проверим финален извод; никоя част не съществува само за да увеличи продължителността."],"nextStep":"Напиши outline за 8–12 минути: шест сцени, доказателство за всяка и точната връзка между две съседни сцени."},"points":1,"required":true}]},{"module_id":"s02-m11","lesson_id":"pv11-08","title":"Тълкувай времето за гледане според целта и видеото","subtitle":"Дълъг формат, измерване и решения от реални данни","objective":"Заключението назовава показател, период, дължина и цел; няма победител по една сурова сума.","hook":"Два клипа имат еднакви гледания, но единият е 3 минути, другият 30. Екипът сравнява watch time без контекст.","estimated_minutes":36,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Заключението назовава показател, период, дължина и цел; няма победител по една сурова сума."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Два клипа имат еднакви гледания, но единият е 3 минути, другият 30. Екипът сравнява watch time без контекст."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Общото време на гледане, средната продължителност и задържането отговарят на различни въпроси. Дължината, целта, периодът и източникът на трафик влияят на сравнение. Инструктаж, който решава задача рано, не е непременно неуспех при кратко гледане. Свържи показателя с очакваното действие и конкретната сцена."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Пази screenshot или export на отчета с дата, видео и избран период. Една крива показва поведение, не причина. Изгледай публикувания файл на точния timecode, сравни зрителското намерение с обещанието и запиши друго възможно обяснение. Малката извадка и промяната на източниците могат да обърнат извода. Предлагай тест за следващото видео и определи кой ще го изпълни и кога ще се върне към данните.\n\nЗа тази задача: Нормализирай по дължина и цел; провери къде зрителят получава отговора."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Запиши целта, дължината и периода на два сравними клипа.\n2. Извади watch time, average view duration и релевантните действия.\n3. Отбележи различни източници и условия на гледане.\n4. Напиши едно решение за следващ клип, което данните действително подкрепят.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Три-минутен урок за изключване на грешна настройка се гледа средно две минути. За канала е по-важно дали зрителят стига до решението, отколкото да го държи още минута без причина.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Обявяваш по-дългото видео за победител само защото натрупва повече минути."},"after":{"label":"Как го поправяш","text":"Нормализирай по дължина и цел; провери къде зрителят получава отговора."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Обявяваш по-дългото видео за победител само защото натрупва повече минути.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Запиши целта, дължината и периода на два сравними клипа. След него: Отбележи различни източници и условия на гледане.\n\nКорекция: Нормализирай по дължина и цел; провери къде зрителят получава отговора.\n\nНови данни, които ще приемеш за успешна поправка: Заключението назовава показател, период, дължина и цел; няма победител по една сурова сума. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Сравни два свои видеоклипа или два примерни отчета, като отбележиш защо числата не са пряко съпоставими.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Заключението назовава показател, период, дължина и цел; няма победител по една сурова сума.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Три-минутен урок за изключване на грешна настройка се гледа средно две минути. За канала е по-важно дали зрителят стига до решението, отколкото да го държи още минута без причина.\n\nДоставка: Сравни два свои видеоклипа или два примерни отчета, като отбележиш защо числата не са пряко съпоставими.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Заключението назовава показател, период, дължина и цел; няма победител по една сурова сума."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Проверен първоизточник","content":{"body":"YouTube Help — YouTube Analytics: https://support.google.com/youtube/answer/9002587\nПровери текущата версия на функцията преди да повториш стъпките."},"points":0,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Какво е average view duration?","options":[{"id":"a","label":"Процентът на кликовете към миниатюрата."},{"id":"b","label":"Средното време, което едно гледане е продължило според отчета."},{"id":"c","label":"Сумата на всички минути за канала."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Средното време, което едно гледане е продължило според отчета.\n\nПървият слаб ход — Сумата на всички минути за канала. — пропуска тази проверка: Заключението назовава показател, период, дължина и цел; няма победител по една сурова сума. Вторият — Процентът на кликовете към миниатюрата. — оставя този риск: Обявяваш по-дългото видео за победител само защото натрупва повече минути. В работна ситуация поправката е: Нормализирай по дължина и цел; провери къде зрителят получава отговора. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Кратък урок губи зрител след показаното решение. Как тълкуваш?","options":[{"id":"a","label":"Проверяваш дали задачата е изпълнена, преди да обявиш проблем."},{"id":"b","label":"Скриваш решението в края."},{"id":"c","label":"Удължаваш финала без полезност."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Проверяваш дали задачата е изпълнена, преди да обявиш проблем.\n\nПървият слаб ход — Удължаваш финала без полезност. — пропуска тази проверка: Заключението назовава показател, период, дължина и цел; няма победител по една сурова сума. Вторият — Скриваш решението в края. — оставя този риск: Обявяваш по-дългото видео за победител само защото натрупва повече минути. В работна ситуация поправката е: Нормализирай по дължина и цел; провери къде зрителят получава отговора. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Кое добавяш към сравнението?","options":[{"id":"a","label":"Само броя гледания."},{"id":"b","label":"Само коментарите на автора."},{"id":"c","label":"Дължина, източник, цел и момент на решението."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Дължина, източник, цел и момент на решението.\n\nПървият слаб ход — Само броя гледания. — пропуска тази проверка: Заключението назовава показател, период, дължина и цел; няма победител по една сурова сума. Вторият — Само коментарите на автора. — оставя този риск: Обявяваш по-дългото видео за победител само защото натрупва повече минути. В работна ситуация поправката е: Нормализирай по дължина и цел; провери къде зрителят получава отговора. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Обявяваш по-дългото видео за победител само защото натрупва повече минути. Как продължаваш?","options":[{"id":"a","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"b","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"c","label":"Нормализирай по дължина и цел; провери къде зрителят получава отговора."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Нормализирай по дължина и цел; провери къде зрителят получава отговора.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Заключението назовава показател, период, дължина и цел; няма победител по една сурова сума. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Обявяваш по-дългото видео за победител само защото натрупва повече минути. В работна ситуация поправката е: Нормализирай по дължина и цел; провери къде зрителят получава отговора. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s4","text":"Напиши едно решение за следващ клип, което данните действително подкрепят."},{"id":"s3","text":"Отбележи различни източници и условия на гледане."},{"id":"s2","text":"Извади watch time, average view duration и релевантните действия."},{"id":"s1","text":"Запиши целта, дължината и периода на два сравними клипа."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Запиши целта, дължината и периода на два сравними клипа.\n2. Извади watch time, average view duration и релевантните действия.\n3. Отбележи различни източници и условия на гледане.\n4. Напиши едно решение за следващ клип, което данните действително подкрепят."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Общото време на гледане, средната продължителност и задържането отговарят на различни въпроси. Дължината, целта, периодът и източникът на трафик влияят на сравнение. Инструктаж, който решава задача рано, не е непременно неуспех при кратко гледане. Свържи показателя с очакваното действие и конкретната сцена.","Нормализирай по дължина и цел; провери къде зрителят получава отговора.","Заключението назовава показател, период, дължина и цел; няма победител по една сурова сума."],"nextStep":"Сравни два свои видеоклипа или два примерни отчета, като отбележиш защо числата не са пряко съпоставими."},"points":1,"required":true}]},{"module_id":"s02-m11","lesson_id":"pv11-09","title":"Сравни средната продължителност с процента изгледано","subtitle":"Дълъг формат, измерване и решения от реални данни","objective":"Трите показателя са назовани правилно; процентът на гледане не е погрешно представен като брой завършили хора.","hook":"Десет минути средно гледане звучи силно, докато не разбереш, че клипът е час.","estimated_minutes":36,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Трите показателя са назовани правилно; процентът на гледане не е погрешно представен като брой завършили хора."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Десет минути средно гледане звучи силно, докато не разбереш, че клипът е час."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Средна продължителност и среден процент изгледано са различни перспективи към същия отчет. Не ги превръщай механично в „completion rate“: завършилите до край са отделна дефиниция. При повторни гледания и различни дължини проверявай как платформата изчислява метриката. Сравнявай подобни формати и търси конкретен момент за подобрение."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Пази screenshot или export на отчета с дата, видео и избран период. Една крива показва поведение, не причина. Изгледай публикувания файл на точния timecode, сравни зрителското намерение с обещанието и запиши друго възможно обяснение. Малката извадка и промяната на източниците могат да обърнат извода. Предлагай тест за следващото видео и определи кой ще го изпълни и кога ще се върне към данните.\n\nЗа тази задача: Върни дължината и дефиницията; не прави процентна диагноза от абсолютна минута."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Запиши дължина на клипа и точната дефиниция на наличните метрики.\n2. Изчисли груба ориентация, но използвай отчетената стойност за окончателно сравнение.\n3. Провери retention графиката и дали има повторни гледания.\n4. Сравни само клипове със сходна задача и посочи ограничение.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"12-минутно интервю с AVD 6 минути и 60-минутен разговор с AVD 10 минути не доказват, че разговорът е по-успешен. Екипът проверява какъв въпрос трябва да реши всеки формат.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Наричаш 10 минути „100% гледане“, защото нямаш дължина в таблицата."},"after":{"label":"Как го поправяш","text":"Върни дължината и дефиницията; не прави процентна диагноза от абсолютна минута."}},"points":2,"required":true},{"position":7,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Направи таблица за три видеа: дължина, AVD, отчетен среден процент, конкретна цел и едно непроверено допускане.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Трите показателя са назовани правилно; процентът на гледане не е погрешно представен като брой завършили хора.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":9,"block_key":"reference","block_type":"rich_text","title":"Проверен първоизточник","content":{"body":"YouTube Help — YouTube Analytics: https://support.google.com/youtube/answer/9002587\nПровери текущата версия на функцията преди да повториш стъпките."},"points":0,"required":false},{"position":10,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Кое е вярно?","options":[{"id":"a","label":"И трите са една и съща метрика."},{"id":"b","label":"AVD е време; средният процент изгледано е относителна стойност; завършването е друг въпрос."},{"id":"c","label":"По-дълъг AVD винаги значи по-добър клип."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: AVD е време; средният процент изгледано е относителна стойност; завършването е друг въпрос.\n\nПървият слаб ход — И трите са една и съща метрика. — пропуска тази проверка: Трите показателя са назовани правилно; процентът на гледане не е погрешно представен като брой завършили хора. Вторият — По-дълъг AVD винаги значи по-добър клип. — оставя този риск: Наричаш 10 минути „100% гледане“, защото нямаш дължина в таблицата. В работна ситуация поправката е: Върни дължината и дефиницията; не прави процентна диагноза от абсолютна минута. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Клипът има много повторни гледания на кратък участък. Какво проверяваш?","options":[{"id":"a","label":"Изтриваш повторните гледания от анализа наум."},{"id":"b","label":"Дефиницията на отчета и retention участъка преди извод за завършване."},{"id":"c","label":"Изчисляваш 100% завършили от AVD."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Дефиницията на отчета и retention участъка преди извод за завършване.\n\nПървият слаб ход — Изчисляваш 100% завършили от AVD. — пропуска тази проверка: Трите показателя са назовани правилно; процентът на гледане не е погрешно представен като брой завършили хора. Вторият — Изтриваш повторните гледания от анализа наум. — оставя този риск: Наричаш 10 минути „100% гледане“, защото нямаш дължина в таблицата. В работна ситуация поправката е: Върни дължината и дефиницията; не прави процентна диагноза от абсолютна минута. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Кой контекст е нужен?","options":[{"id":"a","label":"Дължина, задача, период, източник и дефиниция на метриката."},{"id":"b","label":"Само общи гледания."},{"id":"c","label":"Само заглавие."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Дължина, задача, период, източник и дефиниция на метриката.\n\nПървият слаб ход — Само заглавие. — пропуска тази проверка: Трите показателя са назовани правилно; процентът на гледане не е погрешно представен като брой завършили хора. Вторият — Само общи гледания. — оставя този риск: Наричаш 10 минути „100% гледане“, защото нямаш дължина в таблицата. В работна ситуация поправката е: Върни дължината и дефиницията; не прави процентна диагноза от абсолютна минута. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Наричаш 10 минути „100% гледане“, защото нямаш дължина в таблицата. Как продължаваш?","options":[{"id":"a","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"b","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"c","label":"Върни дължината и дефиницията; не прави процентна диагноза от абсолютна минута."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Върни дължината и дефиницията; не прави процентна диагноза от абсолютна минута.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Трите показателя са назовани правилно; процентът на гледане не е погрешно представен като брой завършили хора. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Наричаш 10 минути „100% гледане“, защото нямаш дължина в таблицата. В работна ситуация поправката е: Върни дължината и дефиницията; не прави процентна диагноза от абсолютна минута. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s2","text":"Изчисли груба ориентация, но използвай отчетената стойност за окончателно сравнение."},{"id":"s3","text":"Провери retention графиката и дали има повторни гледания."},{"id":"s4","text":"Сравни само клипове със сходна задача и посочи ограничение."},{"id":"s1","text":"Запиши дължина на клипа и точната дефиниция на наличните метрики."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Запиши дължина на клипа и точната дефиниция на наличните метрики.\n2. Изчисли груба ориентация, но използвай отчетената стойност за окончателно сравнение.\n3. Провери retention графиката и дали има повторни гледания.\n4. Сравни само клипове със сходна задача и посочи ограничение."},"scoring":{"mode":"exact_order"}},{"position":15,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Средна продължителност и среден процент изгледано са различни перспективи към същия отчет. Не ги превръщай механично в „completion rate“: завършилите до край са отделна дефиниция. При повторни гледания и различни дължини проверявай как платформата изчислява метриката. Сравнявай подобни формати и търси конкретен момент за подобрение.","Върни дължината и дефиницията; не прави процентна диагноза от абсолютна минута.","Трите показателя са назовани правилно; процентът на гледане не е погрешно представен като брой завършили хора."],"nextStep":"Направи таблица за три видеа: дължина, AVD, отчетен среден процент, конкретна цел и едно непроверено допускане."},"points":1,"required":true}]},{"module_id":"s02-m11","lesson_id":"pv11-10","title":"Провери първите 30 секунди спрямо обещанието","subtitle":"Дълъг формат, измерване и решения от реални данни","objective":"Зрителят вижда обещаната тема и знае следващата стъпка преди да изтече половин минута; критичният контекст е запазен.","hook":"Заглавието обещава демонстрация. Първите 30 секунди са лого, спонсор и общи приказки.","estimated_minutes":36,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Зрителят вижда обещаната тема и знае следващата стъпка преди да изтече половин минута; критичният контекст е запазен."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Заглавието обещава демонстрация. Първите 30 секунди са лого, спонсор и общи приказки."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Началото на дълъг клип трябва бързо да потвърди защо зрителят е избрал точно него, без да скрие контекста или изискваното предупреждение. Сравни миниатюра, заглавие, първо видимо действие и произнесеното обещание. Retention в началото е сигнал; разликата може да идва и от източника на трафик."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Пази screenshot или export на отчета с дата, видео и избран период. Една крива показва поведение, не причина. Изгледай публикувания файл на точния timecode, сравни зрителското намерение с обещанието и запиши друго възможно обяснение. Малката извадка и промяната на източниците могат да обърнат извода. Предлагай тест за следващото видео и определи кой ще го изпълни и кога ще се върне към данните.\n\nЗа тази задача: Подреди безопасността преди действието и премахни излишния интро блок."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Запиши буквалното обещание в заглавието и миниатюрата.\n2. Изгледай първите 30 секунди като човек без предишен контекст.\n3. Маркирай секунда, в която се появява обещаният обект или действие.\n4. Направи ново начало и сравни с релевантен трафик, без да местиш задължителна информация.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Видео за ремонт обещава „проверка на контакта“. Новото начало показва дефекта и инструмента в първите секунди, а предупреждението за безопасност е преди работа, не скрито след рекламата.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Местиш предупреждението за безопасност в края, за да задържиш гледане."},"after":{"label":"Как го поправяш","text":"Подреди безопасността преди действието и премахни излишния интро блок."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Местиш предупреждението за безопасност в края, за да задържиш гледане.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Запиши буквалното обещание в заглавието и миниатюрата. След него: Маркирай секунда, в която се появява обещаният обект или действие.\n\nКорекция: Подреди безопасността преди действието и премахни излишния интро блок.\n\nНови данни, които ще приемеш за успешна поправка: Зрителят вижда обещаната тема и знае следващата стъпка преди да изтече половин минута; критичният контекст е запазен. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Направи карта секунда по секунда на първите 30 секунди и запиши един нов монтаж, който показва обещаното без подвеждане.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Зрителят вижда обещаната тема и знае следващата стъпка преди да изтече половин минута; критичният контекст е запазен.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Видео за ремонт обещава „проверка на контакта“. Новото начало показва дефекта и инструмента в първите секунди, а предупреждението за безопасност е преди работа, не скрито след рекламата.\n\nДоставка: Направи карта секунда по секунда на първите 30 секунди и запиши един нов монтаж, който показва обещаното без подвеждане.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Зрителят вижда обещаната тема и знае следващата стъпка преди да изтече половин минута; критичният контекст е запазен."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Проверен първоизточник","content":{"body":"YouTube Help — Key moments for audience retention: https://support.google.com/youtube/answer/9314415\nПровери текущата версия на функцията преди да повториш стъпките."},"points":0,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Кое начало служи на обещанието?","options":[{"id":"a","label":"Показва обещаното действие и необходимия контекст бързо."},{"id":"b","label":"Само лого и музика."},{"id":"c","label":"Недоказан шокиращ кадър."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Показва обещаното действие и необходимия контекст бързо.\n\nПървият слаб ход — Само лого и музика. — пропуска тази проверка: Зрителят вижда обещаната тема и знае следващата стъпка преди да изтече половин минута; критичният контекст е запазен. Вторият — Недоказан шокиращ кадър. — оставя този риск: Местиш предупреждението за безопасност в края, за да задържиш гледане. В работна ситуация поправката е: Подреди безопасността преди действието и премахни излишния интро блок. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Искаш да премахнеш безопасна инструкция от началото. Какво правиш?","options":[{"id":"a","label":"Преместваш я след опасната стъпка."},{"id":"b","label":"Оставяш я преди действието и съкращаваш ненужните представяния."},{"id":"c","label":"Скриваш я в описание, което може да не се отвори."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Оставяш я преди действието и съкращаваш ненужните представяния.\n\nПървият слаб ход — Преместваш я след опасната стъпка. — пропуска тази проверка: Зрителят вижда обещаната тема и знае следващата стъпка преди да изтече половин минута; критичният контекст е запазен. Вторият — Скриваш я в описание, което може да не се отвори. — оставя този риск: Местиш предупреждението за безопасност в края, за да задържиш гледане. В работна ситуация поправката е: Подреди безопасността преди действието и премахни излишния интро блок. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Какво проверяваш след публикация?","options":[{"id":"a","label":"Само лайкове от първия час."},{"id":"b","label":"Retention в началото заедно с източник и обещание."},{"id":"c","label":"Само общ брой абонати."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Retention в началото заедно с източник и обещание.\n\nПървият слаб ход — Само общ брой абонати. — пропуска тази проверка: Зрителят вижда обещаната тема и знае следващата стъпка преди да изтече половин минута; критичният контекст е запазен. Вторият — Само лайкове от първия час. — оставя този риск: Местиш предупреждението за безопасност в края, за да задържиш гледане. В работна ситуация поправката е: Подреди безопасността преди действието и премахни излишния интро блок. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Местиш предупреждението за безопасност в края, за да задържиш гледане. Как продължаваш?","options":[{"id":"a","label":"Подреди безопасността преди действието и премахни излишния интро блок."},{"id":"b","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"c","label":"Продължаваш без проверка и наричаш тази версия окончателна."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Подреди безопасността преди действието и премахни излишния интро блок.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Зрителят вижда обещаната тема и знае следващата стъпка преди да изтече половин минута; критичният контекст е запазен. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Местиш предупреждението за безопасност в края, за да задържиш гледане. В работна ситуация поправката е: Подреди безопасността преди действието и премахни излишния интро блок. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s2","text":"Изгледай първите 30 секунди като човек без предишен контекст."},{"id":"s1","text":"Запиши буквалното обещание в заглавието и миниатюрата."},{"id":"s4","text":"Направи ново начало и сравни с релевантен трафик, без да местиш задължителна информация."},{"id":"s3","text":"Маркирай секунда, в която се появява обещаният обект или действие."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Запиши буквалното обещание в заглавието и миниатюрата.\n2. Изгледай първите 30 секунди като човек без предишен контекст.\n3. Маркирай секунда, в която се появява обещаният обект или действие.\n4. Направи ново начало и сравни с релевантен трафик, без да местиш задължителна информация."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Началото на дълъг клип трябва бързо да потвърди защо зрителят е избрал точно него, без да скрие контекста или изискваното предупреждение. Сравни миниатюра, заглавие, първо видимо действие и произнесеното обещание. Retention в началото е сигнал; разликата може да идва и от източника на трафик.","Подреди безопасността преди действието и премахни излишния интро блок.","Зрителят вижда обещаната тема и знае следващата стъпка преди да изтече половин минута; критичният контекст е запазен."],"nextStep":"Направи карта секунда по секунда на първите 30 секунди и запиши един нов монтаж, който показва обещаното без подвеждане."},"points":1,"required":true}]},{"module_id":"s02-m11","lesson_id":"pv11-11","title":"Провери повторните гледания, споделянията и действията в плейлист","subtitle":"Дълъг формат, измерване и решения от реални данни","objective":"Отчетът назовава точно видимите метрики; изводът за причина остава хипотеза до проверка.","hook":"Видеото има много повторения на една сцена, но екипът нарича това „масово споделяне“.","estimated_minutes":36,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Отчетът назовава точно видимите метрики; изводът за причина остава хипотеза до проверка."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Видеото има много повторения на една сцена, но екипът нарича това „масово споделяне“."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Повторно гледане, споделяне, запазване и действие към следващ клип измерват различни поведения и не всяка платформа показва всяко число. Отдели факт от тълкуване: повторението може да означава трудна стъпка или полезен момент. Запиши какви данни реално са налични и не приравнявай сигнали между платформи."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Пази screenshot или export на отчета с дата, видео и избран период. Една крива показва поведение, не причина. Изгледай публикувания файл на точния timecode, сравни зрителското намерение с обещанието и запиши друго възможно обяснение. Малката извадка и промяната на източниците могат да обърнат извода. Предлагай тест за следващото видео и определи кой ще го изпълни и кога ще се върне към данните.\n\nЗа тази задача: Пази ги отделно и проверявай сцената, която ги поражда."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Назови целта: усвояване, разговор или следваща задача.\n2. Отвори наличните отчети и запиши дефинициите на показателите.\n3. Изгледай повтаряния момент с въпрос защо човек би се върнал.\n4. Избери една промяна в съдържание или навигация и метрика за преглед.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"В урок за възел зрителите връщат 15 секунди около движението на пръстите. Екипът не обявява „виралност“, а снима по-бавен близък план и добавя глава към стъпката.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Събираш повторения, споделяния и гледания в един измислен „engagement score“."},"after":{"label":"Как го поправяш","text":"Пази ги отделно и проверявай сцената, която ги поражда."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Събираш повторения, споделяния и гледания в един измислен „engagement score“.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Назови целта: усвояване, разговор или следваща задача. След него: Изгледай повтаряния момент с въпрос защо човек би се върнал.\n\nКорекция: Пази ги отделно и проверявай сцената, която ги поражда.\n\nНови данни, които ще приемеш за успешна поправка: Отчетът назовава точно видимите метрики; изводът за причина остава хипотеза до проверка. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Избери видео с налични данни; напиши три различни обяснения за един пик и един начин да ги различиш.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Отчетът назовава точно видимите метрики; изводът за причина остава хипотеза до проверка.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: В урок за възел зрителите връщат 15 секунди около движението на пръстите. Екипът не обявява „виралност“, а снима по-бавен близък план и добавя глава към стъпката.\n\nДоставка: Избери видео с налични данни; напиши три различни обяснения за един пик и един начин да ги различиш.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Отчетът назовава точно видимите метрики; изводът за причина остава хипотеза до проверка."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Проверен първоизточник","content":{"body":"YouTube Help — Key moments for audience retention: https://support.google.com/youtube/answer/9314415\nПровери текущата версия на функцията преди да повториш стъпките."},"points":0,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Повторното гледане доказва ли споделяне?","options":[{"id":"a","label":"Да, ако видеото е дълго."},{"id":"b","label":"Да, всяко повторение е споделяне."},{"id":"c","label":"Не; може да показва интерес или труден момент, който трябва да се провери."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Не; може да показва интерес или труден момент, който трябва да се провери.\n\nПървият слаб ход — Да, всяко повторение е споделяне. — пропуска тази проверка: Отчетът назовава точно видимите метрики; изводът за причина остава хипотеза до проверка. Вторият — Да, ако видеото е дълго. — оставя този риск: Събираш повторения, споделяния и гледания в един измислен „engagement score“. В работна ситуация поправката е: Пази ги отделно и проверявай сцената, която ги поражда. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Хората връщат една техническа стъпка. Какво пробваш?","options":[{"id":"a","label":"По-ясен близък план или отделена глава и проверка на резултата."},{"id":"b","label":"Изтриваш стъпката."},{"id":"c","label":"Добавяш по-силна музика."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: По-ясен близък план или отделена глава и проверка на резултата.\n\nПървият слаб ход — Изтриваш стъпката. — пропуска тази проверка: Отчетът назовава точно видимите метрики; изводът за причина остава хипотеза до проверка. Вторият — Добавяш по-силна музика. — оставя този риск: Събираш повторения, споделяния и гледания в един измислен „engagement score“. В работна ситуация поправката е: Пази ги отделно и проверявай сцената, която ги поражда. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Какво записваш?","options":[{"id":"a","label":"Една сума от несъвместими показатели."},{"id":"b","label":"Наличен показател, дефиниция, сцена и вероятно обяснение."},{"id":"c","label":"Само общите гледания."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Наличен показател, дефиниция, сцена и вероятно обяснение.\n\nПървият слаб ход — Една сума от несъвместими показатели. — пропуска тази проверка: Отчетът назовава точно видимите метрики; изводът за причина остава хипотеза до проверка. Вторият — Само общите гледания. — оставя този риск: Събираш повторения, споделяния и гледания в един измислен „engagement score“. В работна ситуация поправката е: Пази ги отделно и проверявай сцената, която ги поражда. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Събираш повторения, споделяния и гледания в един измислен „engagement score“. Как продължаваш?","options":[{"id":"a","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"b","label":"Пази ги отделно и проверявай сцената, която ги поражда."},{"id":"c","label":"Продължаваш без проверка и наричаш тази версия окончателна."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Пази ги отделно и проверявай сцената, която ги поражда.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Отчетът назовава точно видимите метрики; изводът за причина остава хипотеза до проверка. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Събираш повторения, споделяния и гледания в един измислен „engagement score“. В работна ситуация поправката е: Пази ги отделно и проверявай сцената, която ги поражда. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s4","text":"Избери една промяна в съдържание или навигация и метрика за преглед."},{"id":"s1","text":"Назови целта: усвояване, разговор или следваща задача."},{"id":"s2","text":"Отвори наличните отчети и запиши дефинициите на показателите."},{"id":"s3","text":"Изгледай повтаряния момент с въпрос защо човек би се върнал."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Назови целта: усвояване, разговор или следваща задача.\n2. Отвори наличните отчети и запиши дефинициите на показателите.\n3. Изгледай повтаряния момент с въпрос защо човек би се върнал.\n4. Избери една промяна в съдържание или навигация и метрика за преглед."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Повторно гледане, споделяне, запазване и действие към следващ клип измерват различни поведения и не всяка платформа показва всяко число. Отдели факт от тълкуване: повторението може да означава трудна стъпка или полезен момент. Запиши какви данни реално са налични и не приравнявай сигнали между платформи.","Пази ги отделно и проверявай сцената, която ги поражда.","Отчетът назовава точно видимите метрики; изводът за причина остава хипотеза до проверка."],"nextStep":"Избери видео с налични данни; напиши три различни обяснения за един пик и един начин да ги различиш."},"points":1,"required":true}]},{"module_id":"s02-m11","lesson_id":"pv11-12","title":"Свържи показванията и процента на кликване с поведението след клика","subtitle":"Дълъг формат, измерване и решения от реални данни","objective":"Има доказуема връзка между опаковка и съдържание; CTR не е обявен за краен резултат.","hook":"Миниатюрата вдига кликовете, но хората напускат, когато не видят обещания тест.","estimated_minutes":36,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Има доказуема връзка между опаковка и съдържание; CTR не е обявен за краен резултат."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Миниатюрата вдига кликовете, но хората напускат, когато не видят обещания тест."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Импресиите и CTR описват вход към видеото; гледането след клика и следващото действие показват дали входът е уместен. Източниците имат различно намерение, а CTR може да се промени при по-широка аудитория. Затова анализирай верига, не едно число: показване → клик → обещан момент → полезен резултат."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Пази screenshot или export на отчета с дата, видео и избран период. Една крива показва поведение, не причина. Изгледай публикувания файл на точния timecode, сравни зрителското намерение с обещанието и запиши друго възможно обяснение. Малката извадка и промяната на източниците могат да обърнат извода. Предлагай тест за следващото видео и определи кой ще го изпълни и кога ще се върне към данните.\n\nЗа тази задача: Върни обещанието към реалния тест и провери поведението след клика."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Извади импресии, CTR и основни източници за един период.\n2. Отбележи къде видеото изпълнява обещанието от заглавието.\n3. Прочети retention и подходящо следващо действие.\n4. Реши дали да поправиш опаковката или началото, като запишеш защо.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Видео за бюджетен микрофон има висок CTR от Suggested, но отговорът за шумна стая идва след дълъг unboxing. Екипът премества звуковия тест напред и уточнява заглавието.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Преследваш CTR с по-силно обещание, въпреки че видеото не го покрива."},"after":{"label":"Как го поправяш","text":"Върни обещанието към реалния тест и провери поведението след клика."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Преследваш CTR с по-силно обещание, въпреки че видеото не го покрива.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Извади импресии, CTR и основни източници за един период. След него: Прочети retention и подходящо следващо действие.\n\nКорекция: Върни обещанието към реалния тест и провери поведението след клика.\n\nНови данни, които ще приемеш за успешна поправка: Има доказуема връзка между опаковка и съдържание; CTR не е обявен за краен резултат. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Направи карта на едно свое видео с четирите звена; към всяко добави отчет или timecode и едно ограничение.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Има доказуема връзка между опаковка и съдържание; CTR не е обявен за краен резултат.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Видео за бюджетен микрофон има висок CTR от Suggested, но отговорът за шумна стая идва след дълъг unboxing. Екипът премества звуковия тест напред и уточнява заглавието.\n\nДоставка: Направи карта на едно свое видео с четирите звена; към всяко добави отчет или timecode и едно ограничение.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Има доказуема връзка между опаковка и съдържание; CTR не е обявен за краен резултат."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Проверен първоизточник","content":{"body":"YouTube Help — CTR и импресии в контекст: https://support.google.com/youtube/answer/16767369\nПровери текущата версия на функцията преди да повториш стъпките."},"points":0,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Какво значи CTR?","options":[{"id":"a","label":"Дял зрители, изгледали докрай."},{"id":"b","label":"Брой продажби от видеото."},{"id":"c","label":"Дял кликове от отчетените импресии на миниатюрата."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Дял кликове от отчетените импресии на миниатюрата.\n\nПървият слаб ход — Дял зрители, изгледали докрай. — пропуска тази проверка: Има доказуема връзка между опаковка и съдържание; CTR не е обявен за краен резултат. Вторият — Брой продажби от видеото. — оставя този риск: Преследваш CTR с по-силно обещание, въпреки че видеото не го покрива. В работна ситуация поправката е: Върни обещанието към реалния тест и провери поведението след клика. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"CTR пада, а импресиите се разширяват към нова аудитория. Какво правиш?","options":[{"id":"a","label":"Твърдиш, че всички нови зрители са ботове."},{"id":"b","label":"Сменяш миниатюра веднага."},{"id":"c","label":"Проверяваш източници и гледане, преди да приемеш спад в качеството."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Проверяваш източници и гледане, преди да приемеш спад в качеството.\n\nПървият слаб ход — Сменяш миниатюра веднага. — пропуска тази проверка: Има доказуема връзка между опаковка и съдържание; CTR не е обявен за краен резултат. Вторият — Твърдиш, че всички нови зрители са ботове. — оставя този риск: Преследваш CTR с по-силно обещание, въпреки че видеото не го покрива. В работна ситуация поправката е: Върни обещанието към реалния тест и провери поведението след клика. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Коя е правилната верига?","options":[{"id":"a","label":"Показване → клик → изпълнено обещание → полезно действие."},{"id":"b","label":"Клик → автоматична продажба."},{"id":"c","label":"Импресия → доказано доволство."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Показване → клик → изпълнено обещание → полезно действие.\n\nПървият слаб ход — Клик → автоматична продажба. — пропуска тази проверка: Има доказуема връзка между опаковка и съдържание; CTR не е обявен за краен резултат. Вторият — Импресия → доказано доволство. — оставя този риск: Преследваш CTR с по-силно обещание, въпреки че видеото не го покрива. В работна ситуация поправката е: Върни обещанието към реалния тест и провери поведението след клика. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Преследваш CTR с по-силно обещание, въпреки че видеото не го покрива. Как продължаваш?","options":[{"id":"a","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"b","label":"Върни обещанието към реалния тест и провери поведението след клика."},{"id":"c","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Върни обещанието към реалния тест и провери поведението след клика.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Има доказуема връзка между опаковка и съдържание; CTR не е обявен за краен резултат. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Преследваш CTR с по-силно обещание, въпреки че видеото не го покрива. В работна ситуация поправката е: Върни обещанието към реалния тест и провери поведението след клика. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s4","text":"Реши дали да поправиш опаковката или началото, като запишеш защо."},{"id":"s3","text":"Прочети retention и подходящо следващо действие."},{"id":"s2","text":"Отбележи къде видеото изпълнява обещанието от заглавието."},{"id":"s1","text":"Извади импресии, CTR и основни източници за един период."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Извади импресии, CTR и основни източници за един период.\n2. Отбележи къде видеото изпълнява обещанието от заглавието.\n3. Прочети retention и подходящо следващо действие.\n4. Реши дали да поправиш опаковката или началото, като запишеш защо."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Импресиите и CTR описват вход към видеото; гледането след клика и следващото действие показват дали входът е уместен. Източниците имат различно намерение, а CTR може да се промени при по-широка аудитория. Затова анализирай верига, не едно число: показване → клик → обещан момент → полезен резултат.","Върни обещанието към реалния тест и провери поведението след клика.","Има доказуема връзка между опаковка и съдържание; CTR не е обявен за краен резултат."],"nextStep":"Направи карта на едно свое видео с четирите звена; към всяко добави отчет или timecode и едно ограничение."},"points":1,"required":true}]},{"module_id":"s02-m11","lesson_id":"pv11-13","title":"Прочети източника на трафик за едно видео","subtitle":"Дълъг формат, измерване и решения от реални данни","objective":"Данните могат да бъдат проверени обратно в Studio; източникът не е объркан с причина за гледане.","hook":"Отчетът има Search и Suggested, но презентацията ги е събрала като „алгоритъм“.","estimated_minutes":36,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Данните могат да бъдат проверени обратно в Studio; източникът не е объркан с причина за гледане."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Отчетът има Search и Suggested, но презентацията ги е събрала като „алгоритъм“."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Записвай точния източник и дефиниция от YouTube Studio. Search често започва с изричен въпрос; Suggested може да идва от контекста на друго гледане. Това са работни хипотези, не диагноза за отделен човек. Съпостави период, видео, тема и поведение; не прави сравнение между видео и канално ниво без обозначение."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Пази screenshot или export на отчета с дата, видео и избран период. Една крива показва поведение, не причина. Изгледай публикувания файл на точния timecode, сравни зрителското намерение с обещанието и запиши друго възможно обяснение. Малката извадка и промяната на източниците могат да обърнат извода. Предлагай тест за следващото видео и определи кой ще го изпълни и кога ще се върне към данните.\n\nЗа тази задача: Раздели категориите и върни към презентацията точните им имена."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Отвори Reach на ниво конкретно видео и фиксирай период.\n2. Запиши имената на източниците точно както са в отчета.\n3. Провери най-важния източник и времето на гледане за същия период.\n4. Напиши едно решение и едно алтернативно обяснение.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Видео за осветление идва от Search за „сенки при интервю“ и от Suggested под обзор на лампи. Екипът подготвя следващо видео за конкретна сенчеста сцена, без да обещава, че Suggested ще се повтори.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Наричаш всички вътрешни YouTube гледания „търсене“."},"after":{"label":"Как го поправяш","text":"Раздели категориите и върни към презентацията точните им имена."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Наричаш всички вътрешни YouTube гледания „търсене“.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Отвори Reach на ниво конкретно видео и фиксирай период. След него: Провери най-важния източник и времето на гледане за същия период.\n\nКорекция: Раздели категориите и върни към презентацията точните им имена.\n\nНови данни, които ще приемеш за успешна поправка: Данните могат да бъдат проверени обратно в Studio; източникът не е объркан с причина за гледане. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Направи кратък отчет за един клип: период, два основни източника, свързана сцена и предпазлива следваща хипотеза.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Данните могат да бъдат проверени обратно в Studio; източникът не е объркан с причина за гледане.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Видео за осветление идва от Search за „сенки при интервю“ и от Suggested под обзор на лампи. Екипът подготвя следващо видео за конкретна сенчеста сцена, без да обещава, че Suggested ще се повтори.\n\nДоставка: Направи кратък отчет за един клип: период, два основни източника, свързана сцена и предпазлива следваща хипотеза.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Данните могат да бъдат проверени обратно в Studio; източникът не е объркан с причина за гледане."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Проверен първоизточник","content":{"body":"YouTube Help — Reach, източници на трафик и CTR: https://support.google.com/youtube/answer/9314355\nПровери текущата версия на функцията преди да повториш стъпките."},"points":0,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Какво е правилно в отчета?","options":[{"id":"a","label":"Точни имена на източниците, видео ниво и период."},{"id":"b","label":"Канални данни, представени като данни за един клип."},{"id":"c","label":"Всичко под една дума „алгоритъм“."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Точни имена на източниците, видео ниво и период.\n\nПървият слаб ход — Всичко под една дума „алгоритъм“. — пропуска тази проверка: Данните могат да бъдат проверени обратно в Studio; източникът не е объркан с причина за гледане. Вторият — Канални данни, представени като данни за един клип. — оставя този риск: Наричаш всички вътрешни YouTube гледания „търсене“. В работна ситуация поправката е: Раздели категориите и върни към презентацията точните им имена. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Search расте след външна публикация. Какво проверяваш?","options":[{"id":"a","label":"Приписваш всичко на заглавието."},{"id":"b","label":"Изтриваш външния източник от таблицата."},{"id":"c","label":"Периода и отделния външен източник, преди да правиш причинен извод."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Периода и отделния външен източник, преди да правиш причинен извод.\n\nПървият слаб ход — Приписваш всичко на заглавието. — пропуска тази проверка: Данните могат да бъдат проверени обратно в Studio; източникът не е объркан с причина за гледане. Вторият — Изтриваш външния източник от таблицата. — оставя този риск: Наричаш всички вътрешни YouTube гледания „търсене“. В работна ситуация поправката е: Раздели категориите и върни към презентацията точните им имена. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Кое е полезно сравнение?","options":[{"id":"a","label":"Само коментари без период."},{"id":"b","label":"Само общ брой гледания за канала."},{"id":"c","label":"Източник, гледане и конкретна тема за едно видео."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Източник, гледане и конкретна тема за едно видео.\n\nПървият слаб ход — Само общ брой гледания за канала. — пропуска тази проверка: Данните могат да бъдат проверени обратно в Studio; източникът не е объркан с причина за гледане. Вторият — Само коментари без период. — оставя този риск: Наричаш всички вътрешни YouTube гледания „търсене“. В работна ситуация поправката е: Раздели категориите и върни към презентацията точните им имена. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Наричаш всички вътрешни YouTube гледания „търсене“. Как продължаваш?","options":[{"id":"a","label":"Раздели категориите и върни към презентацията точните им имена."},{"id":"b","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"c","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Раздели категориите и върни към презентацията точните им имена.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Данните могат да бъдат проверени обратно в Studio; източникът не е объркан с причина за гледане. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Наричаш всички вътрешни YouTube гледания „търсене“. В работна ситуация поправката е: Раздели категориите и върни към презентацията точните им имена. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s2","text":"Запиши имената на източниците точно както са в отчета."},{"id":"s3","text":"Провери най-важния източник и времето на гледане за същия период."},{"id":"s4","text":"Напиши едно решение и едно алтернативно обяснение."},{"id":"s1","text":"Отвори Reach на ниво конкретно видео и фиксирай период."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Отвори Reach на ниво конкретно видео и фиксирай период.\n2. Запиши имената на източниците точно както са в отчета.\n3. Провери най-важния източник и времето на гледане за същия период.\n4. Напиши едно решение и едно алтернативно обяснение."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Записвай точния източник и дефиниция от YouTube Studio. Search често започва с изричен въпрос; Suggested може да идва от контекста на друго гледане. Това са работни хипотези, не диагноза за отделен човек. Съпостави период, видео, тема и поведение; не прави сравнение между видео и канално ниво без обозначение.","Раздели категориите и върни към презентацията точните им имена.","Данните могат да бъдат проверени обратно в Studio; източникът не е объркан с причина за гледане."],"nextStep":"Направи кратък отчет за един клип: период, два основни източника, свързана сцена и предпазлива следваща хипотеза."},"points":1,"required":true}]},{"module_id":"s02-m11","lesson_id":"pv11-14","title":"Намери точния момент на отпадане и провери сцената","subtitle":"Дълъг формат, измерване и решения от реални данни","objective":"Всеки предложен срез има смислова причина; критичният факт остава във видеото.","hook":"Монтажистът вижда провал при 04:12, но анализът не казва коя сцена е там.","estimated_minutes":38,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Всеки предложен срез има смислова причина; критичният факт остава във видеото."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Монтажистът вижда провал при 04:12, но анализът не казва коя сцена е там."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Drop-off разборът свързва timecode, сцена, обещание и възможен мотив. Използвай export-а, който действително е публикуван; работният timeline може да има друго време. Изгледай началото и края на сцената, провери звук, повторение, смяна на тема и дали зрителят вече е получил отговора. Предложи обратим тест, а не фиктивна сигурност."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Пази screenshot или export на отчета с дата, видео и избран период. Една крива показва поведение, не причина. Изгледай публикувания файл на точния timecode, сравни зрителското намерение с обещанието и запиши друго възможно обяснение. Малката извадка и промяната на източниците могат да обърнат извода. Предлагай тест за следващото видео и определи кой ще го изпълни и кога ще се върне към данните.\n\nЗа тази задача: Запази нужното уточнение, но промени показването и темпото; сравни сцената след тест."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Експортирай или отвори точния публикуван файл.\n2. Отбележи timecode и 20 секунди от двете му страни.\n3. Запиши видимото действие, звук и обещание в този момент.\n4. Предложи две причини и един конкретен монтажен тест с правило за приемане.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"При интервю спадът е на кадър с дребна таблица и продължителен прочит. Следващата версия показва една цифра и обяснението на говорителя; екипът проверява дали хората стигат до извода.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Премахваш сцената със задължително уточнение само заради графиката."},"after":{"label":"Как го поправяш","text":"Запази нужното уточнение, но промени показването и темпото; сравни сцената след тест."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Премахваш сцената със задължително уточнение само заради графиката.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Експортирай или отвори точния публикуван файл. След него: Запиши видимото действие, звук и обещание в този момент.\n\nКорекция: Запази нужното уточнение, но промени показването и темпото; сравни сцената след тест.\n\nНови данни, които ще приемеш за успешна поправка: Всеки предложен срез има смислова причина; критичният факт остава във видеото. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Направи карта на един спад: точен файл, timecode, сцена, звук, алтернативни причини, тест и какво ще наблюдаваш.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Всеки предложен срез има смислова причина; критичният факт остава във видеото.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: При интервю спадът е на кадър с дребна таблица и продължителен прочит. Следващата версия показва една цифра и обяснението на говорителя; екипът проверява дали хората стигат до извода.\n\nДоставка: Направи карта на един спад: точен файл, timecode, сцена, звук, алтернативни причини, тест и какво ще наблюдаваш.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Всеки предложен срез има смислова причина; критичният факт остава във видеото."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Проверен първоизточник","content":{"body":"YouTube Help — Key moments for audience retention: https://support.google.com/youtube/answer/9314415\nПровери текущата версия на функцията преди да повториш стъпките."},"points":0,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Какво първо правиш при спад?","options":[{"id":"a","label":"Добавяш zoom без преглед."},{"id":"b","label":"Отваряш точния публикуван файл около timecode-а и описваш сцената."},{"id":"c","label":"Изрязваш произволно 20 секунди."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Отваряш точния публикуван файл около timecode-а и описваш сцената.\n\nПървият слаб ход — Изрязваш произволно 20 секунди. — пропуска тази проверка: Всеки предложен срез има смислова причина; критичният факт остава във видеото. Вторият — Добавяш zoom без преглед. — оставя този риск: Премахваш сцената със задължително уточнение само заради графиката. В работна ситуация поправката е: Запази нужното уточнение, но промени показването и темпото; сравни сцената след тест. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Спадът съвпада с предупреждение за безопасност. Какъв ход?","options":[{"id":"a","label":"Запазваш предупреждението и тестваш по-ясно и навременно представяне."},{"id":"b","label":"Скриваш го в бърз титър."},{"id":"c","label":"Премахваш го."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Запазваш предупреждението и тестваш по-ясно и навременно представяне.\n\nПървият слаб ход — Премахваш го. — пропуска тази проверка: Всеки предложен срез има смислова причина; критичният факт остава във видеото. Вторият — Скриваш го в бърз титър. — оставя този риск: Премахваш сцената със задължително уточнение само заради графиката. В работна ситуация поправката е: Запази нужното уточнение, но промени показването и темпото; сравни сцената след тест. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Кога тестът има смисъл?","options":[{"id":"a","label":"Когато сцената е непременно виновна."},{"id":"b","label":"Когато нямаш точния export."},{"id":"c","label":"Когато има назована хипотеза и сравним следващ участък."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Когато има назована хипотеза и сравним следващ участък.\n\nПървият слаб ход — Когато сцената е непременно виновна. — пропуска тази проверка: Всеки предложен срез има смислова причина; критичният факт остава във видеото. Вторият — Когато нямаш точния export. — оставя този риск: Премахваш сцената със задължително уточнение само заради графиката. В работна ситуация поправката е: Запази нужното уточнение, но промени показването и темпото; сравни сцената след тест. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Премахваш сцената със задължително уточнение само заради графиката. Как продължаваш?","options":[{"id":"a","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"b","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"c","label":"Запази нужното уточнение, но промени показването и темпото; сравни сцената след тест."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Запази нужното уточнение, но промени показването и темпото; сравни сцената след тест.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Всеки предложен срез има смислова причина; критичният факт остава във видеото. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Премахваш сцената със задължително уточнение само заради графиката. В работна ситуация поправката е: Запази нужното уточнение, но промени показването и темпото; сравни сцената след тест. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s2","text":"Отбележи timecode и 20 секунди от двете му страни."},{"id":"s1","text":"Експортирай или отвори точния публикуван файл."},{"id":"s4","text":"Предложи две причини и един конкретен монтажен тест с правило за приемане."},{"id":"s3","text":"Запиши видимото действие, звук и обещание в този момент."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Експортирай или отвори точния публикуван файл.\n2. Отбележи timecode и 20 секунди от двете му страни.\n3. Запиши видимото действие, звук и обещание в този момент.\n4. Предложи две причини и един конкретен монтажен тест с правило за приемане."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Drop-off разборът свързва timecode, сцена, обещание и възможен мотив. Използвай export-а, който действително е публикуван; работният timeline може да има друго време. Изгледай началото и края на сцената, провери звук, повторение, смяна на тема и дали зрителят вече е получил отговора. Предложи обратим тест, а не фиктивна сигурност.","Запази нужното уточнение, но промени показването и темпото; сравни сцената след тест.","Всеки предложен срез има смислова причина; критичният факт остава във видеото."],"nextStep":"Направи карта на един спад: точен файл, timecode, сцена, звук, алтернативни причини, тест и какво ще наблюдаваш."},"points":1,"required":true}]},{"module_id":"s02-m11","lesson_id":"pv11-15","title":"Планирай едно дълго видео за реалната седмица","subtitle":"Дълъг формат, измерване и решения от реални данни","objective":"Има собственик и срок за всеки критичен вход, резерв и отделен прозорец за QA.","hook":"Планът за седмицата е „снимаме дълго видео“, но няма герой, място или човек за одобрение.","estimated_minutes":38,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Има собственик и срок за всеки критичен вход, резерв и отделен прозорец за QA."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Планът за седмицата е „снимаме дълго видео“, но няма герой, място или човек за одобрение."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Реалният седмичен план събира задача, доказателство, достъп, хора, график, резерв и доставка. Отдели неизбежните действия от желанията. Преди да обещаеш дата, провери права, локация, готовност на говорител, звук и време за гледане на финалния export. Ако материалът липсва, намали обхвата или смени темата навреме."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Пази screenshot или export на отчета с дата, видео и избран период. Една крива показва поведение, не причина. Изгледай публикувания файл на точния timecode, сравни зрителското намерение с обещанието и запиши друго възможно обяснение. Малката извадка и промяната на източниците могат да обърнат извода. Предлагай тест за следващото видео и определи кой ще го изпълни и кога ще се върне към данните.\n\nЗа тази задача: Отдели буфер и приемане; намали обхвата, ако зависимостите няма да се случат."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Напиши въпрос и какъв материал ще докаже отговора.\n2. Свери участници, разрешения, място и времеви прозорец.\n3. Разпредели сценарий, снимки, монтаж, проверка и одобрение по дни.\n4. Задай резервен план и дата, след която непотвърденото спира проекта.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Клиентска работилница може да даде достъп само в сряда. Екипът подготвя въпросите във вторник, снима основно и резерв в сряда, сглобява в четвъртък и оставя петък за преглед.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Последният ден е едновременно снимки, монтаж, проверка и качване."},"after":{"label":"Как го поправяш","text":"Отдели буфер и приемане; намали обхвата, ако зависимостите няма да се случат."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Последният ден е едновременно снимки, монтаж, проверка и качване.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Напиши въпрос и какъв материал ще докаже отговора. След него: Разпредели сценарий, снимки, монтаж, проверка и одобрение по дни.\n\nКорекция: Отдели буфер и приемане; намали обхвата, ако зависимостите няма да се случат.\n\nНови данни, които ще приемеш за успешна поправка: Има собственик и срок за всеки критичен вход, резерв и отделен прозорец за QA. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Направи календар за едно 8–12-минутно видео тази седмица с хора, разрешения, материали, часови блокове и план Б.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Има собственик и срок за всеки критичен вход, резерв и отделен прозорец за QA.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Клиентска работилница може да даде достъп само в сряда. Екипът подготвя въпросите във вторник, снима основно и резерв в сряда, сглобява в четвъртък и оставя петък за преглед.\n\nДоставка: Направи календар за едно 8–12-минутно видео тази седмица с хора, разрешения, материали, часови блокове и план Б.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Има собственик и срок за всеки критичен вход, резерв и отделен прозорец за QA."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Кога можеш да обещаеш дата?","options":[{"id":"a","label":"Веднага след идеята."},{"id":"b","label":"След като провериш достъп, права, хора и време за одобрение."},{"id":"c","label":"След като си избрал thumbnail."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: След като провериш достъп, права, хора и време за одобрение.\n\nПървият слаб ход — Веднага след идеята. — пропуска тази проверка: Има собственик и срок за всеки критичен вход, резерв и отделен прозорец за QA. Вторият — След като си избрал thumbnail. — оставя този риск: Последният ден е едновременно снимки, монтаж, проверка и качване. В работна ситуация поправката е: Отдели буфер и приемане; намали обхвата, ако зависимостите няма да се случат. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Говорителят отпада в деня на снимките. Какво правиш?","options":[{"id":"a","label":"Публикуваш половин клип като готов."},{"id":"b","label":"Използваш предварително съгласуван резерв или преоценяваш дата и обхват."},{"id":"c","label":"Генерираш негов глас без съгласие."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Използваш предварително съгласуван резерв или преоценяваш дата и обхват.\n\nПървият слаб ход — Генерираш негов глас без съгласие. — пропуска тази проверка: Има собственик и срок за всеки критичен вход, резерв и отделен прозорец за QA. Вторият — Публикуваш половин клип като готов. — оставя този риск: Последният ден е едновременно снимки, монтаж, проверка и качване. В работна ситуация поправката е: Отдели буфер и приемане; намали обхвата, ако зависимостите няма да се случат. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Кое време не се изяжда?","options":[{"id":"a","label":"Пълна проверка на експорта и одобрение."},{"id":"b","label":"Само качването на файла."},{"id":"c","label":"Само паузата за обяд."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Пълна проверка на експорта и одобрение.\n\nПървият слаб ход — Само паузата за обяд. — пропуска тази проверка: Има собственик и срок за всеки критичен вход, резерв и отделен прозорец за QA. Вторият — Само качването на файла. — оставя този риск: Последният ден е едновременно снимки, монтаж, проверка и качване. В работна ситуация поправката е: Отдели буфер и приемане; намали обхвата, ако зависимостите няма да се случат. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Последният ден е едновременно снимки, монтаж, проверка и качване. Как продължаваш?","options":[{"id":"a","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"b","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"c","label":"Отдели буфер и приемане; намали обхвата, ако зависимостите няма да се случат."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Отдели буфер и приемане; намали обхвата, ако зависимостите няма да се случат.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Има собственик и срок за всеки критичен вход, резерв и отделен прозорец за QA. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Последният ден е едновременно снимки, монтаж, проверка и качване. В работна ситуация поправката е: Отдели буфер и приемане; намали обхвата, ако зависимостите няма да се случат. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s4","text":"Задай резервен план и дата, след която непотвърденото спира проекта."},{"id":"s1","text":"Напиши въпрос и какъв материал ще докаже отговора."},{"id":"s2","text":"Свери участници, разрешения, място и времеви прозорец."},{"id":"s3","text":"Разпредели сценарий, снимки, монтаж, проверка и одобрение по дни."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Напиши въпрос и какъв материал ще докаже отговора.\n2. Свери участници, разрешения, място и времеви прозорец.\n3. Разпредели сценарий, снимки, монтаж, проверка и одобрение по дни.\n4. Задай резервен план и дата, след която непотвърденото спира проекта."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Реалният седмичен план събира задача, доказателство, достъп, хора, график, резерв и доставка. Отдели неизбежните действия от желанията. Преди да обещаеш дата, провери права, локация, готовност на говорител, звук и време за гледане на финалния export. Ако материалът липсва, намали обхвата или смени темата навреме.","Отдели буфер и приемане; намали обхвата, ако зависимостите няма да се случат.","Има собственик и срок за всеки критичен вход, резерв и отделен прозорец за QA."],"nextStep":"Направи календар за едно 8–12-минутно видео тази седмица с хора, разрешения, материали, часови блокове и план Б."},"points":1,"required":true}]},{"module_id":"s02-m11","lesson_id":"pv11-16","title":"Извади три подобрения от анализ на истинско видео","subtitle":"Дълъг формат, измерване и решения от реални данни","objective":"Друг монтажист може да изпълни трите решения без устно обяснение; докладът отделя наблюдение от хипотеза.","hook":"Отчетът завършва с „да правим по-динамични видеа“, без три конкретни промени.","estimated_minutes":38,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Друг монтажист може да изпълни трите решения без устно обяснение; докладът отделя наблюдение от хипотеза."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Отчетът завършва с „да правим по-динамични видеа“, без три конкретни промени."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Добър анализ води от наблюдение към предпазлива причина, промяна, собственик и метрика. Избери три решения от различни части на процеса: обещание/начало, развитие/доказателство, навигация/следваща стъпка. Подреди ги по очакван ефект и усилие. Запази какво не знаеш и не представяй корелация като доказана причина."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"Пази screenshot или export на отчета с дата, видео и избран период. Една крива показва поведение, не причина. Изгледай публикувания файл на точния timecode, сравни зрителското намерение с обещанието и запиши друго възможно обяснение. Малката извадка и промяната на източниците могат да обърнат извода. Предлагай тест за следващото видео и определи кой ще го изпълни и кога ще се върне към данните.\n\nЗа тази задача: Върни всяко предложение към наблюдаван момент, следващ тест и собственик."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Събери заглавие, миниатюра, източници, retention и действия за едно видео.\n2. Посочи три конкретни сцени или прехода с timecode.\n3. За всяка напиши един обратим тест и кой ще го направи.\n4. Избери момент за повторен преглед и критерий за успех.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Клиентски обзор показва силен Search, слаб първи преход и добра последна демонстрация. Екипът изважда демонстрацията по-рано, пренаписва входното обещание и добавя ясна връзка към следваща проверка.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Изброяваш три общи пожелания без файл, timecode или отговорник."},"after":{"label":"Как го поправяш","text":"Върни всяко предложение към наблюдаван момент, следващ тест и собственик."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Изброяваш три общи пожелания без файл, timecode или отговорник.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Събери заглавие, миниатюра, източници, retention и действия за едно видео. След него: За всяка напиши един обратим тест и кой ще го направи.\n\nКорекция: Върни всяко предложение към наблюдаван момент, следващ тест и собственик.\n\nНови данни, които ще приемеш за успешна поправка: Друг монтажист може да изпълни трите решения без устно обяснение; докладът отделя наблюдение от хипотеза. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Предай една страница с три промени за реален или разрешен клип, доказателство за всяка, цена във време и метрика за следващ преглед.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Друг монтажист може да изпълни трите решения без устно обяснение; докладът отделя наблюдение от хипотеза.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Клиентски обзор показва силен Search, слаб първи преход и добра последна демонстрация. Екипът изважда демонстрацията по-рано, пренаписва входното обещание и добавя ясна връзка към следваща проверка.\n\nДоставка: Предай една страница с три промени за реален или разрешен клип, доказателство за всяка, цена във време и метрика за следващ преглед.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Друг монтажист може да изпълни трите решения без устно обяснение; докладът отделя наблюдение от хипотеза."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Проверен първоизточник","content":{"body":"YouTube Help — Key moments for audience retention: https://support.google.com/youtube/answer/9314415\nПровери текущата версия на функцията преди да повториш стъпките."},"points":0,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Кое е конкретно подобрение?","options":[{"id":"a","label":"„В 00:25 показваме обещания тест преди общия увод и сравняваме задържането.“"},{"id":"b","label":"„Повече динамика“."},{"id":"c","label":"„Алгоритъмът да ни хареса“."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: „В 00:25 показваме обещания тест преди общия увод и сравняваме задържането.“\n\nПървият слаб ход — „Повече динамика“. — пропуска тази проверка: Друг монтажист може да изпълни трите решения без устно обяснение; докладът отделя наблюдение от хипотеза. Вторият — „Алгоритъмът да ни хареса“. — оставя този риск: Изброяваш три общи пожелания без файл, timecode или отговорник. В работна ситуация поправката е: Върни всяко предложение към наблюдаван момент, следващ тест и собственик. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Източникът на трафик се е сменил между две видеа. Какво правиш?","options":[{"id":"a","label":"Пишеш доказан ефект от монтажа."},{"id":"b","label":"Маркираш ограничението и не приписваш цялата разлика на монтажа."},{"id":"c","label":"Изключваш неудобния период без бележка."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Маркираш ограничението и не приписваш цялата разлика на монтажа.\n\nПървият слаб ход — Пишеш доказан ефект от монтажа. — пропуска тази проверка: Друг монтажист може да изпълни трите решения без устно обяснение; докладът отделя наблюдение от хипотеза. Вторият — Изключваш неудобния период без бележка. — оставя този риск: Изброяваш три общи пожелания без файл, timecode или отговорник. В работна ситуация поправката е: Върни всяко предложение към наблюдаван момент, следващ тест и собственик. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Какво трябва да има при всяка препоръка?","options":[{"id":"a","label":"Само общ брой гледания."},{"id":"b","label":"Наблюдение, действие, собственик и начин за проверка."},{"id":"c","label":"Само емоционална оценка."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Наблюдение, действие, собственик и начин за проверка.\n\nПървият слаб ход — Само емоционална оценка. — пропуска тази проверка: Друг монтажист може да изпълни трите решения без устно обяснение; докладът отделя наблюдение от хипотеза. Вторият — Само общ брой гледания. — оставя този риск: Изброяваш три общи пожелания без файл, timecode или отговорник. В работна ситуация поправката е: Върни всяко предложение към наблюдаван момент, следващ тест и собственик. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Изброяваш три общи пожелания без файл, timecode или отговорник. Как продължаваш?","options":[{"id":"a","label":"Върни всяко предложение към наблюдаван момент, следващ тест и собственик."},{"id":"b","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"c","label":"Продължаваш без проверка и наричаш тази версия окончателна."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Върни всяко предложение към наблюдаван момент, следващ тест и собственик.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Друг монтажист може да изпълни трите решения без устно обяснение; докладът отделя наблюдение от хипотеза. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Изброяваш три общи пожелания без файл, timecode или отговорник. В работна ситуация поправката е: Върни всяко предложение към наблюдаван момент, следващ тест и собственик. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s4","text":"Избери момент за повторен преглед и критерий за успех."},{"id":"s3","text":"За всяка напиши един обратим тест и кой ще го направи."},{"id":"s2","text":"Посочи три конкретни сцени или прехода с timecode."},{"id":"s1","text":"Събери заглавие, миниатюра, източници, retention и действия за едно видео."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Събери заглавие, миниатюра, източници, retention и действия за едно видео.\n2. Посочи три конкретни сцени или прехода с timecode.\n3. За всяка напиши един обратим тест и кой ще го направи.\n4. Избери момент за повторен преглед и критерий за успех."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Добър анализ води от наблюдение към предпазлива причина, промяна, собственик и метрика. Избери три решения от различни части на процеса: обещание/начало, развитие/доказателство, навигация/следваща стъпка. Подреди ги по очакван ефект и усилие. Запази какво не знаеш и не представяй корелация като доказана причина.","Върни всяко предложение към наблюдаван момент, следващ тест и собственик.","Друг монтажист може да изпълни трите решения без устно обяснение; докладът отделя наблюдение от хипотеза."],"nextStep":"Предай една страница с три промени за реален или разрешен клип, доказателство за всяка, цена във време и метрика за следващ преглед."},"points":1,"required":true}]},{"module_id":"s02-m12","lesson_id":"pv12-01","title":"Картографирай AI по етапи и остави човека отговорен","subtitle":"AI употреба с човешка проверка и проследими права","objective":"Всеки AI изход има собственик, разрешен вход, проверка и план за връщане към оригинала.","hook":"Екипът казва „AI ни направи видеото“, но никой не знае кой провери твърденията и правата.","estimated_minutes":38,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Всеки AI изход има собственик, разрешен вход, проверка и план за връщане към оригинала."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Екипът казва „AI ни направи видеото“, но никой не знае кой провери твърденията и правата."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Раздели процеса на идея, сценарий, заснемане, монтаж, звук, графика, публикация и анализ. При всяка употреба запиши вход, инструмент, версия, отговорен човек, проверка и дали може да се върнеш към изходния материал. AI може да предложи и ускорява; крайното решение, правата и точността са човешка отговорност. Не подавай поверителен клиентски материал в инструмент без разрешение и ясни условия."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"За всеки генериран или редактиран елемент пази източник, разрешение, версия на инструмента и оригинал. Провери факти, числа, имена, образ и глас чрез независим материал; гладък резултат не е доказателство. При поверителни данни първо провери разрешение и условия за обработка. Човек преглежда целия export и изискванията за обозначаване в конкретния канал преди публикация.\n\nЗа тази задача: Сложи човешка точка за проверка преди всяко необратимо действие и пази източника."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Нарисувай осемте етапа от брифа до отчета.\n2. Маркирай къде AI има конкретна полза и какви данни ще получи.\n3. Назначи човек и проверка за факт, образ, глас, права и публикуване.\n4. Пробвай възстановяване от оригинала при един неуспешен AI изход.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Малка агенция използва транскрипция за груб монтаж, но редактор сравнява ключовите реплики със суровия звук. Дизайнерът пази оригиналните продуктови кадри; отговорникът по клиента одобрява финала.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Изходът от инструмент се приема за одобрен, защото изглежда професионално."},"after":{"label":"Как го поправяш","text":"Сложи човешка точка за проверка преди всяко необратимо действие и пази източника."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Изходът от инструмент се приема за одобрен, защото изглежда професионално.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Нарисувай осемте етапа от брифа до отчета. След него: Назначи човек и проверка за факт, образ, глас, права и публикуване.\n\nКорекция: Сложи човешка точка за проверка преди всяко необратимо действие и пази източника.\n\nНови данни, които ще приемеш за успешна поправка: Всеки AI изход има собственик, разрешен вход, проверка и план за връщане към оригинала. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Направи карта на един реален видео процес с поне три AI употреби и едно място, където умишлено няма да го ползваш.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Всеки AI изход има собственик, разрешен вход, проверка и план за връщане към оригинала.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Малка агенция използва транскрипция за груб монтаж, но редактор сравнява ключовите реплики със суровия звук. Дизайнерът пази оригиналните продуктови кадри; отговорникът по клиента одобрява финала.\n\nДоставка: Направи карта на един реален видео процес с поне три AI употреби и едно място, където умишлено няма да го ползваш.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Всеки AI изход има собственик, разрешен вход, проверка и план за връщане към оригинала."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Кой носи крайна отговорност?","options":[{"id":"a","label":"Зрителят, защото може да провери сам."},{"id":"b","label":"Инструментът, защото е генерирал файла."},{"id":"c","label":"Назованият човек, който проверява и одобрява финалния материал."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Назованият човек, който проверява и одобрява финалния материал.\n\nПървият слаб ход — Инструментът, защото е генерирал файла. — пропуска тази проверка: Всеки AI изход има собственик, разрешен вход, проверка и план за връщане към оригинала. Вторият — Зрителят, защото може да провери сам. — оставя този риск: Изходът от инструмент се приема за одобрен, защото изглежда професионално. В работна ситуация поправката е: Сложи човешка точка за проверка преди всяко необратимо действие и пази източника. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Клиент изпраща поверително интервю. Какво правиш преди upload?","options":[{"id":"a","label":"Проверяваш разрешение, условия за данните и по-безопасна алтернатива."},{"id":"b","label":"Качваш го във всеки безплатен инструмент."},{"id":"c","label":"Махаш името на файла и приемаш, че е анонимно."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Проверяваш разрешение, условия за данните и по-безопасна алтернатива.\n\nПървият слаб ход — Качваш го във всеки безплатен инструмент. — пропуска тази проверка: Всеки AI изход има собственик, разрешен вход, проверка и план за връщане към оригинала. Вторият — Махаш името на файла и приемаш, че е анонимно. — оставя този риск: Изходът от инструмент се приема за одобрен, защото изглежда професионално. В работна ситуация поправката е: Сложи човешка точка за проверка преди всяко необратимо действие и пази източника. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Какво записваш в картата?","options":[{"id":"a","label":"Само prompt."},{"id":"b","label":"Вход, инструмент/версия, изход, проверка, одобрител и права."},{"id":"c","label":"Само спестените минути."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Вход, инструмент/версия, изход, проверка, одобрител и права.\n\nПървият слаб ход — Само prompt. — пропуска тази проверка: Всеки AI изход има собственик, разрешен вход, проверка и план за връщане към оригинала. Вторият — Само спестените минути. — оставя този риск: Изходът от инструмент се приема за одобрен, защото изглежда професионално. В работна ситуация поправката е: Сложи човешка точка за проверка преди всяко необратимо действие и пази източника. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Изходът от инструмент се приема за одобрен, защото изглежда професионално. Как продължаваш?","options":[{"id":"a","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"b","label":"Сложи човешка точка за проверка преди всяко необратимо действие и пази източника."},{"id":"c","label":"Продължаваш без проверка и наричаш тази версия окончателна."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Сложи човешка точка за проверка преди всяко необратимо действие и пази източника.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Всеки AI изход има собственик, разрешен вход, проверка и план за връщане към оригинала. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Изходът от инструмент се приема за одобрен, защото изглежда професионално. В работна ситуация поправката е: Сложи човешка точка за проверка преди всяко необратимо действие и пази източника. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s2","text":"Маркирай къде AI има конкретна полза и какви данни ще получи."},{"id":"s3","text":"Назначи човек и проверка за факт, образ, глас, права и публикуване."},{"id":"s4","text":"Пробвай възстановяване от оригинала при един неуспешен AI изход."},{"id":"s1","text":"Нарисувай осемте етапа от брифа до отчета."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Нарисувай осемте етапа от брифа до отчета.\n2. Маркирай къде AI има конкретна полза и какви данни ще получи.\n3. Назначи човек и проверка за факт, образ, глас, права и публикуване.\n4. Пробвай възстановяване от оригинала при един неуспешен AI изход."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Раздели процеса на идея, сценарий, заснемане, монтаж, звук, графика, публикация и анализ. При всяка употреба запиши вход, инструмент, версия, отговорен човек, проверка и дали може да се върнеш към изходния материал. AI може да предложи и ускорява; крайното решение, правата и точността са човешка отговорност. Не подавай поверителен клиентски материал в инструмент без разрешение и ясни условия.","Сложи човешка точка за проверка преди всяко необратимо действие и пази източника.","Всеки AI изход има собственик, разрешен вход, проверка и план за връщане към оригинала."],"nextStep":"Направи карта на един реален видео процес с поне три AI употреби и едно място, където умишлено няма да го ползваш."},"points":1,"required":true}]},{"module_id":"s02-m12","lesson_id":"pv12-02","title":"Извеждай идеи от истински сигнали, после използвай AI за варианти","subtitle":"AI употреба с човешка проверка и проследими права","objective":"Избраната тема има реален източник и разрешено доказателство; никой измислен тренд не е представен като факт.","hook":"Генераторът предлага пет тренда, които нямат връзка с истинските въпроси на хората.","estimated_minutes":36,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Избраната тема има реален източник и разрешено доказателство; никой измислен тренд не е представен като факт."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Генераторът предлага пет тренда, които нямат връзка с истинските въпроси на хората."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Първо събери сигнали: разговори, търсене, въпроси към услугата, трудна стъпка в реален проект. После дай на AI ограничен бриф за различни ъгли към проверен проблем. Избери идея по възможност да я докажеш със собствен материал, не по най-силното заглавие. Генераторът не е източник на пазарни данни и не знае какво е разрешено да снимаш."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"За всеки генериран или редактиран елемент пази източник, разрешение, версия на инструмента и оригинал. Провери факти, числа, имена, образ и глас чрез независим материал; гладък резултат не е доказателство. При поверителни данни първо провери разрешение и условия за обработка. Човек преглежда целия export и изискванията за обозначаване в конкретния канал преди публикация.\n\nЗа тази задача: Върни се към реалните въпроси и отбележи кои предложения нямат опора."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Запиши три реални въпроса с дата и контекст, без лични данни.\n2. Дай на инструмента цел, аудитория, известни факти и забранени твърдения.\n3. Потърси три различни гледни точки, а не 20 пренаписани заглавия.\n4. Избери една идея с наличен казус, действие и проверим резултат.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Сервиз чува пет пъти въпрос за шум при колело. AI предлага „тайна, която майсторите крият“; екипът го отхвърля и снима честно разграничаване на два дефекта с демонстрация.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Показваш AI списък като доказателство, че пазарът иска тези теми."},"after":{"label":"Как го поправяш","text":"Върни се към реалните въпроси и отбележи кои предложения нямат опора."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Показваш AI списък като доказателство, че пазарът иска тези теми.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Запиши три реални въпроса с дата и контекст, без лични данни. След него: Потърси три различни гледни точки, а не 20 пренаписани заглавия.\n\nКорекция: Върни се към реалните въпроси и отбележи кои предложения нямат опора.\n\nНови данни, които ще приемеш за успешна поправка: Избраната тема има реален източник и разрешено доказателство; никой измислен тренд не е представен като факт. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Извлечи три анонимизирани сигнала и три AI варианта; за всеки напиши какво можеш и не можеш да докажеш.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Избраната тема има реален източник и разрешено доказателство; никой измислен тренд не е представен като факт.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Сервиз чува пет пъти въпрос за шум при колело. AI предлага „тайна, която майсторите крият“; екипът го отхвърля и снима честно разграничаване на два дефекта с демонстрация.\n\nДоставка: Извлечи три анонимизирани сигнала и три AI варианта; за всеки напиши какво можеш и не можеш да докажеш.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Избраната тема има реален източник и разрешено доказателство; никой измислен тренд не е представен като факт."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Какво подаваш на AI?","options":[{"id":"a","label":"Чужди лични разговори без разрешение."},{"id":"b","label":"Искане да измисли пазарно проучване."},{"id":"c","label":"Проверен проблем и ясни граници, без поверителни данни."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Проверен проблем и ясни граници, без поверителни данни.\n\nПървият слаб ход — Чужди лични разговори без разрешение. — пропуска тази проверка: Избраната тема има реален източник и разрешено доказателство; никой измислен тренд не е представен като факт. Вторият — Искане да измисли пазарно проучване. — оставя този риск: Показваш AI списък като доказателство, че пазарът иска тези теми. В работна ситуация поправката е: Върни се към реалните въпроси и отбележи кои предложения нямат опора. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Най-доброто заглавие няма реален казус. Какво правиш?","options":[{"id":"a","label":"Обещаваш непроверен резултат."},{"id":"b","label":"Снимаш инсценировка като истински случай."},{"id":"c","label":"Отхвърляш го или набавяш проверимо доказателство преди производство."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Отхвърляш го или набавяш проверимо доказателство преди производство.\n\nПървият слаб ход — Снимаш инсценировка като истински случай. — пропуска тази проверка: Избраната тема има реален източник и разрешено доказателство; никой измислен тренд не е представен като факт. Вторият — Обещаваш непроверен резултат. — оставя този риск: Показваш AI списък като доказателство, че пазарът иска тези теми. В работна ситуация поправката е: Върни се към реалните въпроси и отбележи кои предложения нямат опора. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Как оценяваш идея?","options":[{"id":"a","label":"По източник на нуждата, изпълнимост и доказуем отговор."},{"id":"b","label":"По броя удивителни в заглавието."},{"id":"c","label":"По броя генерирани варианта."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: По източник на нуждата, изпълнимост и доказуем отговор.\n\nПървият слаб ход — По броя удивителни в заглавието. — пропуска тази проверка: Избраната тема има реален източник и разрешено доказателство; никой измислен тренд не е представен като факт. Вторият — По броя генерирани варианта. — оставя този риск: Показваш AI списък като доказателство, че пазарът иска тези теми. В работна ситуация поправката е: Върни се към реалните въпроси и отбележи кои предложения нямат опора. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Показваш AI списък като доказателство, че пазарът иска тези теми. Как продължаваш?","options":[{"id":"a","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"b","label":"Върни се към реалните въпроси и отбележи кои предложения нямат опора."},{"id":"c","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Върни се към реалните въпроси и отбележи кои предложения нямат опора.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Избраната тема има реален източник и разрешено доказателство; никой измислен тренд не е представен като факт. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Показваш AI списък като доказателство, че пазарът иска тези теми. В работна ситуация поправката е: Върни се към реалните въпроси и отбележи кои предложения нямат опора. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s2","text":"Дай на инструмента цел, аудитория, известни факти и забранени твърдения."},{"id":"s1","text":"Запиши три реални въпроса с дата и контекст, без лични данни."},{"id":"s4","text":"Избери една идея с наличен казус, действие и проверим резултат."},{"id":"s3","text":"Потърси три различни гледни точки, а не 20 пренаписани заглавия."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Запиши три реални въпроса с дата и контекст, без лични данни.\n2. Дай на инструмента цел, аудитория, известни факти и забранени твърдения.\n3. Потърси три различни гледни точки, а не 20 пренаписани заглавия.\n4. Избери една идея с наличен казус, действие и проверим резултат."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Първо събери сигнали: разговори, търсене, въпроси към услугата, трудна стъпка в реален проект. После дай на AI ограничен бриф за различни ъгли към проверен проблем. Избери идея по възможност да я докажеш със собствен материал, не по най-силното заглавие. Генераторът не е източник на пазарни данни и не знае какво е разрешено да снимаш.","Върни се към реалните въпроси и отбележи кои предложения нямат опора.","Избраната тема има реален източник и разрешено доказателство; никой измислен тренд не е представен като факт."],"nextStep":"Извлечи три анонимизирани сигнала и три AI варианта; за всеки напиши какво можеш и не можеш да докажеш."},"points":1,"required":true}]},{"module_id":"s02-m12","lesson_id":"pv12-03","title":"Редактирай транскрипт с AI, без да изкривиш казаното","subtitle":"AI употреба с човешка проверка и проследими права","objective":"Нито едно отрицание, число или приписване на човек не е променено; финалът е чут спрямо оригинала.","hook":"Автоматичният транскрипт превръща „не можем“ в „можем“ и монтажът променя смисъла.","estimated_minutes":38,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Нито едно отрицание, число или приписване на човек не е променено; финалът е чут спрямо оригинала."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Автоматичният транскрипт превръща „не можем“ в „можем“ и монтажът променя смисъла."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Транскриптът е работна карта към звук, а не авторитетен запис на казаното. Проверявай имена, числа, отрицания, цени и цитати в оригиналния аудио файл. При текстов монтаж слушай двете страни на всяка сглобка и гледай контекста на целия отговор. Не лепи изречения от различни въпроси така, че говорителят да застане зад ново твърдение."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"За всеки генериран или редактиран елемент пази източник, разрешение, версия на инструмента и оригинал. Провери факти, числа, имена, образ и глас чрез независим материал; гладък резултат не е доказателство. При поверителни данни първо провери разрешение и условия за обработка. Човек преглежда целия export и изискванията за обозначаване в конкретния канал преди публикация.\n\nЗа тази задача: Върни оригиналния отрязък и показвай условието около ключовата фраза."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Запази недокоснат оригинален звук и timecode за всяка реплика.\n2. Маркирай критичните думи и ги свери със слушане, не само с текст.\n3. Направи rough cut и изслушай преходите с оригиналния въпрос.\n4. Дай на говорителя или редактор втори преглед на чувствителните твърдения.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Лекар обяснява „този подход не е подходящ за всеки“. Системата пропуска „не“; редакторът сверява звука, връща фразата и пази уточняващия контекст.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Изхвърляш паузите механично и превръщаш условно твърдение в категорично."},"after":{"label":"Как го поправяш","text":"Върни оригиналния отрязък и показвай условието около ключовата фраза."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Изхвърляш паузите механично и превръщаш условно твърдение в категорично.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Запази недокоснат оригинален звук и timecode за всяка реплика. След него: Направи rough cut и изслушай преходите с оригиналния въпрос.\n\nКорекция: Върни оригиналния отрязък и показвай условието около ключовата фраза.\n\nНови данни, които ще приемеш за успешна поправка: Нито едно отрицание, число или приписване на човек не е променено; финалът е чут спрямо оригинала. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Редактирай 45–90 секунди разрешен говор чрез транскрипт; приложи списък с поне пет критични сверявания и една отхвърлена сглобка.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Нито едно отрицание, число или приписване на човек не е променено; финалът е чут спрямо оригинала.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Лекар обяснява „този подход не е подходящ за всеки“. Системата пропуска „не“; редакторът сверява звука, връща фразата и пази уточняващия контекст.\n\nДоставка: Редактирай 45–90 секунди разрешен говор чрез транскрипт; приложи списък с поне пет критични сверявания и една отхвърлена сглобка.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Нито едно отрицание, число или приписване на човек не е променено; финалът е чут спрямо оригинала."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Кой е източникът при спор?","options":[{"id":"a","label":"Оригиналният звук и контекстът на целия отговор."},{"id":"b","label":"По-гладката версия на изречението."},{"id":"c","label":"Автоматичният текст."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Оригиналният звук и контекстът на целия отговор.\n\nПървият слаб ход — Автоматичният текст. — пропуска тази проверка: Нито едно отрицание, число или приписване на човек не е променено; финалът е чут спрямо оригинала. Вторият — По-гладката версия на изречението. — оставя този риск: Изхвърляш паузите механично и превръщаш условно твърдение в категорично. В работна ситуация поправката е: Върни оригиналния отрязък и показвай условието около ключовата фраза. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Транскриптът изпуска „не“. Как действаш?","options":[{"id":"a","label":"Оставяш го заради субтитрите."},{"id":"b","label":"Сменяш говорителя със синтетичен глас."},{"id":"c","label":"Връщаш се към звука и поправяш текста и монтажа."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Връщаш се към звука и поправяш текста и монтажа.\n\nПървият слаб ход — Оставяш го заради субтитрите. — пропуска тази проверка: Нито едно отрицание, число или приписване на човек не е променено; финалът е чут спрямо оригинала. Вторият — Сменяш говорителя със синтетичен глас. — оставя този риск: Изхвърляш паузите механично и превръщаш условно твърдение в категорично. В работна ситуация поправката е: Върни оригиналния отрязък и показвай условието около ключовата фраза. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Какво проверяваш при cut?","options":[{"id":"a","label":"Само продължителността на клипа."},{"id":"b","label":"Само дали waveform-ът е равен."},{"id":"c","label":"Смисъл, въпрос, начало/край на реплика и синхрон на звука."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Смисъл, въпрос, начало/край на реплика и синхрон на звука.\n\nПървият слаб ход — Само дали waveform-ът е равен. — пропуска тази проверка: Нито едно отрицание, число или приписване на човек не е променено; финалът е чут спрямо оригинала. Вторият — Само продължителността на клипа. — оставя този риск: Изхвърляш паузите механично и превръщаш условно твърдение в категорично. В работна ситуация поправката е: Върни оригиналния отрязък и показвай условието около ключовата фраза. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Изхвърляш паузите механично и превръщаш условно твърдение в категорично. Как продължаваш?","options":[{"id":"a","label":"Върни оригиналния отрязък и показвай условието около ключовата фраза."},{"id":"b","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"c","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Върни оригиналния отрязък и показвай условието около ключовата фраза.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Нито едно отрицание, число или приписване на човек не е променено; финалът е чут спрямо оригинала. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Изхвърляш паузите механично и превръщаш условно твърдение в категорично. В работна ситуация поправката е: Върни оригиналния отрязък и показвай условието около ключовата фраза. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s4","text":"Дай на говорителя или редактор втори преглед на чувствителните твърдения."},{"id":"s1","text":"Запази недокоснат оригинален звук и timecode за всяка реплика."},{"id":"s2","text":"Маркирай критичните думи и ги свери със слушане, не само с текст."},{"id":"s3","text":"Направи rough cut и изслушай преходите с оригиналния въпрос."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Запази недокоснат оригинален звук и timecode за всяка реплика.\n2. Маркирай критичните думи и ги свери със слушане, не само с текст.\n3. Направи rough cut и изслушай преходите с оригиналния въпрос.\n4. Дай на говорителя или редактор втори преглед на чувствителните твърдения."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Транскриптът е работна карта към звук, а не авторитетен запис на казаното. Проверявай имена, числа, отрицания, цени и цитати в оригиналния аудио файл. При текстов монтаж слушай двете страни на всяка сглобка и гледай контекста на целия отговор. Не лепи изречения от различни въпроси така, че говорителят да застане зад ново твърдение.","Върни оригиналния отрязък и показвай условието около ключовата фраза.","Нито едно отрицание, число или приписване на човек не е променено; финалът е чут спрямо оригинала."],"nextStep":"Редактирай 45–90 секунди разрешен говор чрез транскрипт; приложи списък с поне пет критични сверявания и една отхвърлена сглобка."},"points":1,"required":true}]},{"module_id":"s02-m12","lesson_id":"pv12-04","title":"Ползвай синтетичен глас само с право, съгласие и ясна проверка","subtitle":"AI употреба с човешка проверка и проследими права","objective":"Има право и съгласие за конкретната употреба; нито едно име или число не е произнесено грешно.","hook":"Клиент иска глас, „почти като“ служител, който не е дал съгласие.","estimated_minutes":38,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Има право и съгласие за конкретната употреба; нито едно име или число не е произнесено грешно."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Клиент иска глас, „почти като“ служител, който не е дал съгласие."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Синтетичният глас изисква ясно право върху записа, разрешение за имитация на разпознаваем глас и проверка дали зрителят няма да бъде подведен. За прости инструкции често е достатъчен неимитиращ глас с право на употреба. Прослушай произношение, имена, числа, паузи и език; пази версията на скрипта и кой я е одобрил. Преди публикация виж изискванията на конкретната платформа за AI обозначаване."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"За всеки генериран или редактиран елемент пази източник, разрешение, версия на инструмента и оригинал. Провери факти, числа, имена, образ и глас чрез независим материал; гладък резултат не е доказателство. При поверителни данни първо провери разрешение и условия за обработка. Човек преглежда целия export и изискванията за обозначаване в конкретния канал преди публикация.\n\nЗа тази задача: Спри използването; вземи валидно разрешение или избери собствен, неимитиращ запис."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Определи дали гласът е общ синтетичен или имитация на човек.\n2. Провери права, обхват, срок и изрично съгласие преди генериране.\n3. Свери скрипта с проверени факти; експортирай тестов отрязък.\n4. Прослушай целия файл, добави нужно обозначение и документирай финално одобрение.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Видео за работно време използва лицензиран общ глас, а не имитация на собственика. Човек от екипа проверява произношението на адреса и часовете, после слуша на телефон.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Генерираш познат глас от стар клиентски запис и оставяш зрителя да мисли, че човекът е говорил."},"after":{"label":"Как го поправяш","text":"Спри използването; вземи валидно разрешение или избери собствен, неимитиращ запис."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Генерираш познат глас от стар клиентски запис и оставяш зрителя да мисли, че човекът е говорил.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Определи дали гласът е общ синтетичен или имитация на човек. След него: Свери скрипта с проверени факти; експортирай тестов отрязък.\n\nКорекция: Спри използването; вземи валидно разрешение или избери собствен, неимитиращ запис.\n\nНови данни, които ще приемеш за успешна поправка: Има право и съгласие за конкретната употреба; нито едно име или число не е произнесено грешно. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Направи 15-секунден тест с разрешен глас; приложи документ/условия за употреба, текст, три прослушани рискови думи и решение за обозначение.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Има право и съгласие за конкретната употреба; нито едно име или число не е произнесено грешно.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Видео за работно време използва лицензиран общ глас, а не имитация на собственика. Човек от екипа проверява произношението на адреса и часовете, после слуша на телефон.\n\nДоставка: Направи 15-секунден тест с разрешен глас; приложи документ/условия за употреба, текст, три прослушани рискови думи и решение за обозначение.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Има право и съгласие за конкретната употреба; нито едно име или число не е произнесено грешно."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Проверен първоизточник","content":{"body":"YouTube Help — обозначаване на значително променено или синтетично съдържание: https://support.google.com/youtube/answer/14328491\nПровери текущата версия на функцията преди да повториш стъпките."},"points":0,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Кога може да клонираш разпознаваем глас?","options":[{"id":"a","label":"Когато прилича, но не е напълно същият."},{"id":"b","label":"Само при ясно разрешена конкретна употреба и необходима прозрачност към зрителя."},{"id":"c","label":"Щом имаш стар запис на човека."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Само при ясно разрешена конкретна употреба и необходима прозрачност към зрителя.\n\nПървият слаб ход — Щом имаш стар запис на човека. — пропуска тази проверка: Има право и съгласие за конкретната употреба; нито едно име или число не е произнесено грешно. Вторият — Когато прилича, но не е напълно същият. — оставя този риск: Генерираш познат глас от стар клиентски запис и оставяш зрителя да мисли, че човекът е говорил. В работна ситуация поправката е: Спри използването; вземи валидно разрешение или избери собствен, неимитиращ запис. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Нямаш съгласие до крайния срок. Какво правиш?","options":[{"id":"a","label":"Използваш разрешен неимитиращ вариант или променяш срока."},{"id":"b","label":"Публикуваш и искаш разрешение после."},{"id":"c","label":"Генерираш тихо подобен глас."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Използваш разрешен неимитиращ вариант или променяш срока.\n\nПървият слаб ход — Генерираш тихо подобен глас. — пропуска тази проверка: Има право и съгласие за конкретната употреба; нито едно име или число не е произнесено грешно. Вторият — Публикуваш и искаш разрешение после. — оставя този риск: Генерираш познат глас от стар клиентски запис и оставяш зрителя да мисли, че човекът е говорил. В работна ситуация поправката е: Спри използването; вземи валидно разрешение или избери собствен, неимитиращ запис. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Какво проверяваш на финала?","options":[{"id":"a","label":"Само приятен тембър."},{"id":"b","label":"Само скорост на генерацията."},{"id":"c","label":"Право, факти, произношение, пълно прослушване и обозначение."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Право, факти, произношение, пълно прослушване и обозначение.\n\nПървият слаб ход — Само приятен тембър. — пропуска тази проверка: Има право и съгласие за конкретната употреба; нито едно име или число не е произнесено грешно. Вторият — Само скорост на генерацията. — оставя този риск: Генерираш познат глас от стар клиентски запис и оставяш зрителя да мисли, че човекът е говорил. В работна ситуация поправката е: Спри използването; вземи валидно разрешение или избери собствен, неимитиращ запис. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Генерираш познат глас от стар клиентски запис и оставяш зрителя да мисли, че човекът е говорил. Как продължаваш?","options":[{"id":"a","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"b","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"c","label":"Спри използването; вземи валидно разрешение или избери собствен, неимитиращ запис."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Спри използването; вземи валидно разрешение или избери собствен, неимитиращ запис.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Има право и съгласие за конкретната употреба; нито едно име или число не е произнесено грешно. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Генерираш познат глас от стар клиентски запис и оставяш зрителя да мисли, че човекът е говорил. В работна ситуация поправката е: Спри използването; вземи валидно разрешение или избери собствен, неимитиращ запис. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s4","text":"Прослушай целия файл, добави нужно обозначение и документирай финално одобрение."},{"id":"s3","text":"Свери скрипта с проверени факти; експортирай тестов отрязък."},{"id":"s2","text":"Провери права, обхват, срок и изрично съгласие преди генериране."},{"id":"s1","text":"Определи дали гласът е общ синтетичен или имитация на човек."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Определи дали гласът е общ синтетичен или имитация на човек.\n2. Провери права, обхват, срок и изрично съгласие преди генериране.\n3. Свери скрипта с проверени факти; експортирай тестов отрязък.\n4. Прослушай целия файл, добави нужно обозначение и документирай финално одобрение."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Синтетичният глас изисква ясно право върху записа, разрешение за имитация на разпознаваем глас и проверка дали зрителят няма да бъде подведен. За прости инструкции често е достатъчен неимитиращ глас с право на употреба. Прослушай произношение, имена, числа, паузи и език; пази версията на скрипта и кой я е одобрил. Преди публикация виж изискванията на конкретната платформа за AI обозначаване.","Спри използването; вземи валидно разрешение или избери собствен, неимитиращ запис.","Има право и съгласие за конкретната употреба; нито едно име или число не е произнесено грешно."],"nextStep":"Направи 15-секунден тест с разрешен глас; приложи документ/условия за употреба, текст, три прослушани рискови думи и решение за обозначение."},"points":1,"required":true}]},{"module_id":"s02-m12","lesson_id":"pv12-05","title":"Подобрявай кадър с AI, без да измисляш детайл","subtitle":"AI употреба с човешка проверка и проследими права","objective":"Критичният факт идва от реален източник; оригиналът е запазен и зрителят не вижда измислен детайл като доказателство.","hook":"AI изчиства размазан номер върху автомобил и го заменя с убедителен, но измислен знак.","estimated_minutes":38,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Критичният факт идва от реален източник; оригиналът е запазен и зрителят не вижда измислен детайл като доказателство."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"AI изчиства размазан номер върху автомобил и го заменя с убедителен, но измислен знак."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Подобряване на кадър не възстановява доказано липсваща информация. Разграничи шумопотискане, стабилизация и цветна корекция от генеративно допълване. Ако детайл е важен за факт, не го извеждай от AI реконструкция. Сравнявай с оригинал на 100% размер, проверявай ръце, етикети, текст и лица; пази оригинала и версията на обработката."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"За всеки генериран или редактиран елемент пази източник, разрешение, версия на инструмента и оригинал. Провери факти, числа, имена, образ и глас чрез независим материал; гладък резултат не е доказателство. При поверителни данни първо провери разрешение и условия за обработка. Човек преглежда целия export и изискванията за обозначаване в конкретния канал преди публикация.\n\nЗа тази задача: Върни проверен оригинал или ново заснемане; отдели творчески фон от фактическо доказателство."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Запиши защо кадърът е слаб и дали детайлът е факт или само фон.\n2. Направи контролна, негенеративна корекция и отделно AI проба.\n3. Сравни оригинал, контрол и проба на критичните пиксели.\n4. Отхвърли добавен детайл или заснеми нов кадър; маркирай съществена синтетична промяна.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Производител снима етикет извън фокус. Upscale измисля букви. Екипът не ползва обработеното изображение за съставките; заснема нов близък план и оставя стария кадър само за атмосфера.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Представяш нарисуван текст като реално видим етикет."},"after":{"label":"Как го поправяш","text":"Върни проверен оригинал или ново заснемане; отдели творчески фон от фактическо доказателство."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Представяш нарисуван текст като реално видим етикет.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Запиши защо кадърът е слаб и дали детайлът е факт или само фон. След него: Сравни оригинал, контрол и проба на критичните пиксели.\n\nКорекция: Върни проверен оригинал или ново заснемане; отдели творчески фон от фактическо доказателство.\n\nНови данни, които ще приемеш за успешна поправка: Критичният факт идва от реален източник; оригиналът е запазен и зрителят не вижда измислен детайл като доказателство. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Сравни 5-секунден собствен кадър преди/след обработка; маркирай три зони, в които не би приел генериран детайл.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Критичният факт идва от реален източник; оригиналът е запазен и зрителят не вижда измислен детайл като доказателство.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Производител снима етикет извън фокус. Upscale измисля букви. Екипът не ползва обработеното изображение за съставките; заснема нов близък план и оставя стария кадър само за атмосфера.\n\nДоставка: Сравни 5-секунден собствен кадър преди/след обработка; маркирай три зони, в които не би приел генериран детайл.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Критичният факт идва от реален източник; оригиналът е запазен и зрителят не вижда измислен детайл като доказателство."},"points":1,"required":false},{"position":11,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Какво прави upscale с липсващ детайл?","options":[{"id":"a","label":"Възстановява със сигурност всеки знак."},{"id":"b","label":"Може да изгради правдоподобен вид, но не доказва първоначалния факт."},{"id":"c","label":"Проверява етикета срещу база данни."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Може да изгради правдоподобен вид, но не доказва първоначалния факт.\n\nПървият слаб ход — Възстановява със сигурност всеки знак. — пропуска тази проверка: Критичният факт идва от реален източник; оригиналът е запазен и зрителят не вижда измислен детайл като доказателство. Вторият — Проверява етикета срещу база данни. — оставя този риск: Представяш нарисуван текст като реално видим етикет. В работна ситуация поправката е: Върни проверен оригинал или ново заснемане; отдели творчески фон от фактическо доказателство. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Етикетът е нечетим. Какво правиш?","options":[{"id":"a","label":"Увеличаваш още обработката, докато звучи правдоподобно."},{"id":"b","label":"Заснемаш отново или ползваш проверен източник за факта."},{"id":"c","label":"Показваш AI буквите като реални."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Заснемаш отново или ползваш проверен източник за факта.\n\nПървият слаб ход — Показваш AI буквите като реални. — пропуска тази проверка: Критичният факт идва от реален източник; оригиналът е запазен и зрителят не вижда измислен детайл като доказателство. Вторият — Увеличаваш още обработката, докато звучи правдоподобно. — оставя този риск: Представяш нарисуван текст като реално видим етикет. В работна ситуация поправката е: Върни проверен оригинал или ново заснемане; отдели творчески фон от фактическо доказателство. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Къде сравняваш?","options":[{"id":"a","label":"Критични детайли на оригинал и обработена версия в крайния размер."},{"id":"b","label":"Само колко бързо е рендерирало."},{"id":"c","label":"Само малкия preview."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Критични детайли на оригинал и обработена версия в крайния размер.\n\nПървият слаб ход — Само малкия preview. — пропуска тази проверка: Критичният факт идва от реален източник; оригиналът е запазен и зрителят не вижда измислен детайл като доказателство. Вторият — Само колко бързо е рендерирало. — оставя този риск: Представяш нарисуван текст като реално видим етикет. В работна ситуация поправката е: Върни проверен оригинал или ново заснемане; отдели творчески фон от фактическо доказателство. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Представяш нарисуван текст като реално видим етикет. Как продължаваш?","options":[{"id":"a","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"b","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"c","label":"Върни проверен оригинал или ново заснемане; отдели творчески фон от фактическо доказателство."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Върни проверен оригинал или ново заснемане; отдели творчески фон от фактическо доказателство.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Критичният факт идва от реален източник; оригиналът е запазен и зрителят не вижда измислен детайл като доказателство. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Представяш нарисуван текст като реално видим етикет. В работна ситуация поправката е: Върни проверен оригинал или ново заснемане; отдели творчески фон от фактическо доказателство. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s2","text":"Направи контролна, негенеративна корекция и отделно AI проба."},{"id":"s3","text":"Сравни оригинал, контрол и проба на критичните пиксели."},{"id":"s4","text":"Отхвърли добавен детайл или заснеми нов кадър; маркирай съществена синтетична промяна."},{"id":"s1","text":"Запиши защо кадърът е слаб и дали детайлът е факт или само фон."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Запиши защо кадърът е слаб и дали детайлът е факт или само фон.\n2. Направи контролна, негенеративна корекция и отделно AI проба.\n3. Сравни оригинал, контрол и проба на критичните пиксели.\n4. Отхвърли добавен детайл или заснеми нов кадър; маркирай съществена синтетична промяна."},"scoring":{"mode":"exact_order"}},{"position":16,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Подобряване на кадър не възстановява доказано липсваща информация. Разграничи шумопотискане, стабилизация и цветна корекция от генеративно допълване. Ако детайл е важен за факт, не го извеждай от AI реконструкция. Сравнявай с оригинал на 100% размер, проверявай ръце, етикети, текст и лица; пази оригинала и версията на обработката.","Върни проверен оригинал или ново заснемане; отдели творчески фон от фактическо доказателство.","Критичният факт идва от реален източник; оригиналът е запазен и зрителят не вижда измислен детайл като доказателство."],"nextStep":"Сравни 5-секунден собствен кадър преди/след обработка; маркирай три зони, в които не би приел генериран детайл."},"points":1,"required":true}]},{"module_id":"s02-m12","lesson_id":"pv12-06","title":"Създавай AI говорител само когато зрителят не е подведен","subtitle":"AI употреба с човешка проверка и проследими права","objective":"Никой тестов зрител не приема синтетичния човек за реален свидетел; правата и фактите са документирани.","hook":"AI говорител с лице на „клиент“ казва одобрение, което истински клиент никога не е давал.","estimated_minutes":38,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Никой тестов зрител не приема синтетичния човек за реален свидетел; правата и фактите са документирани."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"AI говорител с лице на „клиент“ казва одобрение, което истински клиент никога не е давал."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Синтетичният говорител е уместен само когато има право върху образ, глас и текст и аудиторията разбира естеството на представянето. Избягвай фалшиви препоръки, реалистично представяне на действителен човек без съгласие и подмяна на свидетелство. Проверявай текст, мимика, синхрон, обозначение и контекст на публикацията. Ако достоверността е централна, използвай реален говорител или явно условна анимация."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"За всеки генериран или редактиран елемент пази източник, разрешение, версия на инструмента и оригинал. Провери факти, числа, имена, образ и глас чрез независим материал; гладък резултат не е доказателство. При поверителни данни първо провери разрешение и условия за обработка. Човек преглежда целия export и изискванията за обозначаване в конкретния канал преди публикация.\n\nЗа тази задача: Премахни свидетелството; използвай реално разрешен казус или честно демонстрационно представяне."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Определи дали героят е действителен човек, измислен персонаж или общ аватар.\n2. Провери права върху лице/глас и кой е автор на твърдението.\n3. Направи кратък тест и го покажи на човек без обяснение: какво смята, че вижда?\n4. Обозначи синтетичния характер и отхвърли всяко подвеждащо свидетелство.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Обучителен клип използва ясно стилизиран дигитален персонаж, представен като водещ. Реална лекарка не е имитирана, а медицинските твърдения минават редакционен преглед от компетентен човек.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Фалшив „доволен клиент“ се представя като истинска препоръка."},"after":{"label":"Как го поправяш","text":"Премахни свидетелството; използвай реално разрешен казус или честно демонстрационно представяне."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Фалшив „доволен клиент“ се представя като истинска препоръка.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Определи дали героят е действителен човек, измислен персонаж или общ аватар. След него: Направи кратък тест и го покажи на човек без обяснение: какво смята, че вижда?\n\nКорекция: Премахни свидетелството; използвай реално разрешен казус или честно демонстрационно представяне.\n\nНови данни, които ще приемеш за успешна поправка: Никой тестов зрител не приема синтетичния човек за реален свидетел; правата и фактите са документирани. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Напиши бриф за 20-секунден AI говорител: произход на образ/глас, тип твърдения, текст на обозначение и тест дали зрителят разбира какво гледа.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Никой тестов зрител не приема синтетичния човек за реален свидетел; правата и фактите са документирани.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Обучителен клип използва ясно стилизиран дигитален персонаж, представен като водещ. Реална лекарка не е имитирана, а медицинските твърдения минават редакционен преглед от компетентен човек.\n\nДоставка: Напиши бриф за 20-секунден AI говорител: произход на образ/глас, тип твърдения, текст на обозначение и тест дали зрителят разбира какво гледа.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Никой тестов зрител не приема синтетичния човек за реален свидетел; правата и фактите са документирани."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Проверен първоизточник","content":{"body":"TikTok Help — AI-generated content: https://support.tiktok.com/en/using-tiktok/creating-videos/ai-generated-content\nПровери текущата версия на функцията преди да повториш стъпките."},"points":0,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Кой говорител е приемлив за демонстрация?","options":[{"id":"a","label":"Разрешен и ясно представен синтетичен персонаж с проверен текст."},{"id":"b","label":"Клонинг на клиент от старо видео без разрешение."},{"id":"c","label":"Измислен свидетел, представен като реален."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Разрешен и ясно представен синтетичен персонаж с проверен текст.\n\nПървият слаб ход — Клонинг на клиент от старо видео без разрешение. — пропуска тази проверка: Никой тестов зрител не приема синтетичния човек за реален свидетел; правата и фактите са документирани. Вторият — Измислен свидетел, представен като реален. — оставя този риск: Фалшив „доволен клиент“ се представя като истинска препоръка. В работна ситуация поправката е: Премахни свидетелството; използвай реално разрешен казус или честно демонстрационно представяне. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Тестов зрител мисли, че аватарът е истински клиент. Какво правиш?","options":[{"id":"a","label":"Оставяш го, щом изглежда реалистично."},{"id":"b","label":"Променяш представянето и обозначението или изоставяш този формат."},{"id":"c","label":"Слагаш пояснение само във вътрешния файл."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Променяш представянето и обозначението или изоставяш този формат.\n\nПървият слаб ход — Оставяш го, щом изглежда реалистично. — пропуска тази проверка: Никой тестов зрител не приема синтетичния човек за реален свидетел; правата и фактите са документирани. Вторият — Слагаш пояснение само във вътрешния файл. — оставя този риск: Фалшив „доволен клиент“ се представя като истинска препоръка. В работна ситуация поправката е: Премахни свидетелството; използвай реално разрешен казус или честно демонстрационно представяне. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Какво проверяваш преди публикуване?","options":[{"id":"a","label":"Само цената на инструмента."},{"id":"b","label":"Права, произход на твърденията, яснота за зрителя и правила на платформата."},{"id":"c","label":"Само синхрон на устните."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Права, произход на твърденията, яснота за зрителя и правила на платформата.\n\nПървият слаб ход — Само синхрон на устните. — пропуска тази проверка: Никой тестов зрител не приема синтетичния човек за реален свидетел; правата и фактите са документирани. Вторият — Само цената на инструмента. — оставя този риск: Фалшив „доволен клиент“ се представя като истинска препоръка. В работна ситуация поправката е: Премахни свидетелството; използвай реално разрешен казус или честно демонстрационно представяне. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Фалшив „доволен клиент“ се представя като истинска препоръка. Как продължаваш?","options":[{"id":"a","label":"Премахни свидетелството; използвай реално разрешен казус или честно демонстрационно представяне."},{"id":"b","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"c","label":"Продължаваш без проверка и наричаш тази версия окончателна."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Премахни свидетелството; използвай реално разрешен казус или честно демонстрационно представяне.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Никой тестов зрител не приема синтетичния човек за реален свидетел; правата и фактите са документирани. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Фалшив „доволен клиент“ се представя като истинска препоръка. В работна ситуация поправката е: Премахни свидетелството; използвай реално разрешен казус или честно демонстрационно представяне. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s2","text":"Провери права върху лице/глас и кой е автор на твърдението."},{"id":"s1","text":"Определи дали героят е действителен човек, измислен персонаж или общ аватар."},{"id":"s4","text":"Обозначи синтетичния характер и отхвърли всяко подвеждащо свидетелство."},{"id":"s3","text":"Направи кратък тест и го покажи на човек без обяснение: какво смята, че вижда?"}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Определи дали героят е действителен човек, измислен персонаж или общ аватар.\n2. Провери права върху лице/глас и кой е автор на твърдението.\n3. Направи кратък тест и го покажи на човек без обяснение: какво смята, че вижда?\n4. Обозначи синтетичния характер и отхвърли всяко подвеждащо свидетелство."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Синтетичният говорител е уместен само когато има право върху образ, глас и текст и аудиторията разбира естеството на представянето. Избягвай фалшиви препоръки, реалистично представяне на действителен човек без съгласие и подмяна на свидетелство. Проверявай текст, мимика, синхрон, обозначение и контекст на публикацията. Ако достоверността е централна, използвай реален говорител или явно условна анимация.","Премахни свидетелството; използвай реално разрешен казус или честно демонстрационно представяне.","Никой тестов зрител не приема синтетичния човек за реален свидетел; правата и фактите са документирани."],"nextStep":"Напиши бриф за 20-секунден AI говорител: произход на образ/глас, тип твърдения, текст на обозначение и тест дали зрителят разбира какво гледа."},"points":1,"required":true}]},{"module_id":"s02-m12","lesson_id":"pv12-07","title":"Редактирай AI текста, така че да звучи като човек и като теб","subtitle":"AI употреба с човешка проверка и проследими права","objective":"Говорителят може да прочете естествено текста и да защити всяко изречение с реален пример.","hook":"AI пише: „Отключете потенциала на вашата история“, а човекът във видеото никога не би го казал.","estimated_minutes":36,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Говорителят може да прочете естествено текста и да защити всяко изречение с реален пример."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"AI пише: „Отключете потенциала на вашата история“, а човекът във видеото никога не би го казал."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"Гласът на автора се получава от реални думи, позиция и наблюдения. Използвай AI за варианти и редакционна проверка, но върни конкретната ситуация, естествена синтактична дължина и едно честно мнение. Прочети текста на глас; ако не можеш да го кажеш пред клиент без неудобство, пренапиши го. Пази фактите и не имитирай чужд автор."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"За всеки генериран или редактиран елемент пази източник, разрешение, версия на инструмента и оригинал. Провери факти, числа, имена, образ и глас чрез независим материал; гладък резултат не е доказателство. При поверителни данни първо провери разрешение и условия за обработка. Човек преглежда целия export и изискванията за обозначаване в конкретния канал преди публикация.\n\nЗа тази задача: Върни едно видяно действие, конкретен говорител и реална промяна; премахни празния суперлатив."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Вземи три собствени изречения от реален разговор или разрешен текст.\n2. Маркирай повтарящи се думи, твоята позиция и изрази, които никога не ползваш.\n3. Помоли AI за две версии на конкретната сцена с тези ограничения.\n4. Прочети на глас, изрежи общите фрази и провери всяко твърдение.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Собственик на ателие казва: „Този шев се разпра след третото пране, затова го променихме“. Това е по-силно и вярно от „революционно качество“; AI помага само да се подреди историята.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Запазваш гладък общ текст, който няма човек, действие или цена на грешката."},"after":{"label":"Как го поправяш","text":"Върни едно видяно действие, конкретен говорител и реална промяна; премахни празния суперлатив."}},"points":2,"required":true},{"position":7,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Вземи 120 думи AI текст, пренапиши ги като 45-секунден собствен говор и посочи пет изтрити клишета и два проверени факта.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":8,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Говорителят може да прочете естествено текста и да защити всяко изречение с реален пример.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":9,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Кое звучи като автор с опит?","options":[{"id":"a","label":"Чужд стил, копиран дума по дума."},{"id":"b","label":"„Ние трансформираме съдбите“ без пример."},{"id":"c","label":"Конкретен случай, наблюдение и честна промяна."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Конкретен случай, наблюдение и честна промяна.\n\nПървият слаб ход — „Ние трансформираме съдбите“ без пример. — пропуска тази проверка: Говорителят може да прочете естествено текста и да защити всяко изречение с реален пример. Вторият — Чужд стил, копиран дума по дума. — оставя този риск: Запазваш гладък общ текст, който няма човек, действие или цена на грешката. В работна ситуация поправката е: Върни едно видяно действие, конкретен говорител и реална промяна; премахни празния суперлатив. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":10,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Говорителят отказва една фраза като неестествена. Какво правиш?","options":[{"id":"a","label":"Връщаш неговите думи и проверяваш дали смисълът е запазен."},{"id":"b","label":"Караш го да я повтори 20 пъти."},{"id":"c","label":"Заменяш го със синтетичен глас без съгласие."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Връщаш неговите думи и проверяваш дали смисълът е запазен.\n\nПървият слаб ход — Караш го да я повтори 20 пъти. — пропуска тази проверка: Говорителят може да прочете естествено текста и да защити всяко изречение с реален пример. Вторият — Заменяш го със синтетичен глас без съгласие. — оставя този риск: Запазваш гладък общ текст, който няма човек, действие или цена на грешката. В работна ситуация поправката е: Върни едно видяно действие, конкретен говорител и реална промяна; премахни празния суперлатив. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":11,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Кой е тестът за текст?","options":[{"id":"a","label":"Текстът има много прилагателни."},{"id":"b","label":"Говорителят може да го каже и защити с факт пред реален човек."},{"id":"c","label":"Генераторът го оценява като „премиум“."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Говорителят може да го каже и защити с факт пред реален човек.\n\nПървият слаб ход — Текстът има много прилагателни. — пропуска тази проверка: Говорителят може да прочете естествено текста и да защити всяко изречение с реален пример. Вторият — Генераторът го оценява като „премиум“. — оставя този риск: Запазваш гладък общ текст, който няма човек, действие или цена на грешката. В работна ситуация поправката е: Върни едно видяно действие, конкретен говорител и реална промяна; премахни празния суперлатив. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":12,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Запазваш гладък общ текст, който няма човек, действие или цена на грешката. Как продължаваш?","options":[{"id":"a","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."},{"id":"b","label":"Върни едно видяно действие, конкретен говорител и реална промяна; премахни празния суперлатив."},{"id":"c","label":"Продължаваш без проверка и наричаш тази версия окончателна."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Върни едно видяно действие, конкретен говорител и реална промяна; премахни празния суперлатив.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Говорителят може да прочете естествено текста и да защити всяко изречение с реален пример. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Запазваш гладък общ текст, който няма човек, действие или цена на грешката. В работна ситуация поправката е: Върни едно видяно действие, конкретен говорител и реална промяна; премахни празния суперлатив. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s4","text":"Прочети на глас, изрежи общите фрази и провери всяко твърдение."},{"id":"s1","text":"Вземи три собствени изречения от реален разговор или разрешен текст."},{"id":"s2","text":"Маркирай повтарящи се думи, твоята позиция и изрази, които никога не ползваш."},{"id":"s3","text":"Помоли AI за две версии на конкретната сцена с тези ограничения."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Вземи три собствени изречения от реален разговор или разрешен текст.\n2. Маркирай повтарящи се думи, твоята позиция и изрази, които никога не ползваш.\n3. Помоли AI за две версии на конкретната сцена с тези ограничения.\n4. Прочети на глас, изрежи общите фрази и провери всяко твърдение."},"scoring":{"mode":"exact_order"}},{"position":14,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["Гласът на автора се получава от реални думи, позиция и наблюдения. Използвай AI за варианти и редакционна проверка, но върни конкретната ситуация, естествена синтактична дължина и едно честно мнение. Прочети текста на глас; ако не можеш да го кажеш пред клиент без неудобство, пренапиши го. Пази фактите и не имитирай чужд автор.","Върни едно видяно действие, конкретен говорител и реална промяна; премахни празния суперлатив.","Говорителят може да прочете естествено текста и да защити всяко изречение с реален пример."],"nextStep":"Вземи 120 думи AI текст, пренапиши ги като 45-секунден собствен говор и посочи пет изтрити клишета и два проверени факта."},"points":1,"required":true}]},{"module_id":"s02-m12","lesson_id":"pv12-08","title":"Сглоби цял AI подпомогнат процес и защити финалния клип","subtitle":"AI употреба с човешка проверка и проследими права","objective":"Друг човек може да проследи всеки значим елемент и да възпроизведе решението за публикация без устни допълнения.","hook":"Финалният клип е готов, но никой не може да каже кои кадри са генерирани и дали има разрешение за гласа.","estimated_minutes":38,"blocks":[{"position":0,"block_key":"objective","block_type":"objective","title":"Резултатът от урока","content":{"body":"Друг човек може да проследи всеки значим елемент и да възпроизведе решението за публикация без устни допълнения."},"points":1,"required":true},{"position":1,"block_key":"hook","block_type":"hook","title":"Ситуацията","content":{"body":"Финалният клип е готов, но никой не може да каже кои кадри са генерирани и дали има разрешение за гласа."},"points":1,"required":true},{"position":2,"block_key":"principle","block_type":"rich_text","title":"Как вземаш решението","content":{"body":"AI процесът е готов, когато входовете, решенията и проверките могат да бъдат проследени. Събери малък пакет: бриф, разрешени активи, версия на скрипта, списък на AI употребите, оригинали, фактологична проверка, права, нужни обозначения, финален export и приемане. Използвай AI само там, където качеството или скоростта са измеримо по-добри след човешки преглед. Не бъркай гладка генерация с готов продукт."},"points":2,"required":true},{"position":3,"block_key":"field_rules","block_type":"rich_text","title":"Преди да тръгнеш по инерция","content":{"body":"За всеки генериран или редактиран елемент пази източник, разрешение, версия на инструмента и оригинал. Провери факти, числа, имена, образ и глас чрез независим материал; гладък резултат не е доказателство. При поверителни данни първо провери разрешение и условия за обработка. Човек преглежда целия export и изискванията за обозначаване в конкретния канал преди публикация.\n\nЗа тази задача: Спри публикацията, докато произходът, правата и фактите могат да се проверят; замени неизвестните активи."},"points":2,"required":true},{"position":4,"block_key":"steps","block_type":"rich_text","title":"Работен ред","content":{"body":"1. Избери разрешен кратък проект и ограничен AI обхват.\n2. Запази оригиналите, входовете и версията на всяка генерирана част.\n3. Направи фактологичен, визуален, звуков и правен преглед с конкретни отметки.\n4. Изгледай целия export на целевия екран, добави обозначения и предай manifest с отговорник.\n\nПровери изхода преди да дадеш статуса „готово“. Ако входът или правата липсват, отбележи блокиращото условие и назови кой може да го реши."},"points":2,"required":true},{"position":5,"block_key":"case","block_type":"example","title":"Как изглежда в работа","content":{"body":"Малък бизнес снима истински продукт, ползва AI за чернови на субтитри и два варианта на началото. Екипът поправя името и съставките, избира собствен глас и предава досие с източници, версии и финален файл.\n\nПриеми примера като схема за решение, не като обещание за същите показатели във всеки проект. Твоят собствен източник и условия може да наложат друг ход."},"points":2,"required":true},{"position":6,"block_key":"repair","block_type":"before_after","title":"Грешката и поправката","content":{"before":{"label":"Ходът, който се проваля","text":"Доставяш mp4 без произход, а при въпрос за лицето казваш „генераторът го направи“."},"after":{"label":"Как го поправяш","text":"Спри публикацията, докато произходът, правата и фактите могат да се проверят; замени неизвестните активи."}},"points":2,"required":true},{"position":7,"block_key":"diagnosis","block_type":"rich_text","title":"Когато пробата не мине","content":{"body":"Наблюдаван симптом: Доставяш mp4 без произход, а при въпрос за лицето казваш „генераторът го направи“.\n\nЗапази предишната версия и провери входните условия по ред, вместо да сменяш всичко едновременно. Първият контролен ход е: Избери разрешен кратък проект и ограничен AI обхват. След него: Направи фактологичен, визуален, звуков и правен преглед с конкретни отметки.\n\nКорекция: Спри публикацията, докато произходът, правата и фактите могат да се проверят; замени неизвестните активи.\n\nНови данни, които ще приемеш за успешна поправка: Друг човек може да проследи всеки значим елемент и да възпроизведе решението за публикация без устни допълнения. Ако не можеш да покажеш това, остави работата в статус проба и запиши неизвестното."},"points":2,"required":true},{"position":8,"block_key":"practice","block_type":"rich_text","title":"Направи го със свой материал","content":{"body":"Направи 20–40-секунден разрешен откъс и предай заедно с него списък на AI употребите, оригинали, права, проверени факти, нужни етикети и QA отчет.\n\nИзползвай собствен или разрешен материал. Запази първа проба, коригирана версия, кратко обяснение защо си променил решението и финална проверка. Ако работиш без свой акаунт или данни, използвай предоставен пример и посочи точно какво не можеш да измериш. Не качвай клиентска медия или лични данни в портфолио без разрешение."},"points":2,"required":true},{"position":9,"block_key":"acceptance","block_type":"rich_text","title":"Как разбираш, че става","content":{"body":"Друг човек може да проследи всеки значим елемент и да възпроизведе решението за публикация без устни допълнения.\n\nПокажи доказателството на човек, който не е участвал: той трябва да намери изходния материал, решението, версията и следващото действие. Когато числото е хипотеза или е извън достъпа ти, не го представяй като измерен резултат. Отдели чернова, проверено и клиентски одобрено."},"points":1,"required":true},{"position":10,"block_key":"handoff","block_type":"rich_text","title":"Предай така, че колега да продължи","content":{"body":"Мини бриф: Малък бизнес снима истински продукт, ползва AI за чернови на субтитри и два варианта на началото. Екипът поправя името и съставките, избира собствен глас и предава досие с източници, версии и финален файл.\n\nДоставка: Направи 20–40-секунден разрешен откъс и предай заедно с него списък на AI употребите, оригинали, права, проверени факти, нужни етикети и QA отчет.\n\nКъм нея добави: кой е собственик; кои файлове или данни са източник; коя версия е проверена; коя е хипотеза; какви права и одобрения са нужни; какво се прави след публикация. Критерий за приемане: Друг човек може да проследи всеки значим елемент и да възпроизведе решението за публикация без устни допълнения."},"points":1,"required":false},{"position":11,"block_key":"reference","block_type":"rich_text","title":"Проверен първоизточник","content":{"body":"YouTube Help — обозначаване на значително променено или синтетично съдържание: https://support.google.com/youtube/answer/14328491\nПровери текущата версия на функцията преди да повториш стъпките."},"points":0,"required":false},{"position":12,"block_key":"quiz_1","block_type":"quiz","title":"Избери работещия ход","content":{"question":"Какво прави AI клипа готов за клиент?","options":[{"id":"a","label":"Само висока резолюция."},{"id":"b","label":"Само интересен prompt."},{"id":"c","label":"Проверен файл плюс проследими активи, права, факти и човешко одобрение."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Проверен файл плюс проследими активи, права, факти и човешко одобрение.\n\nПървият слаб ход — Само висока резолюция. — пропуска тази проверка: Друг човек може да проследи всеки значим елемент и да възпроизведе решението за публикация без устни допълнения. Вторият — Само интересен prompt. — оставя този риск: Доставяш mp4 без произход, а при въпрос за лицето казваш „генераторът го направи“. В работна ситуация поправката е: Спри публикацията, докато произходът, правата и фактите могат да се проверят; замени неизвестните активи. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":13,"block_key":"scenario_1","block_type":"scenario","title":"Решение при ограничение","content":{"prompt":"Не знаеш произхода на един реалистичен кадър. Какво правиш?","options":[{"id":"a","label":"Изтриваш метаданните му."},{"id":"b","label":"Публикуваш и чакаш оплакване."},{"id":"c","label":"Спираш този кадър, докато докажеш право и точност, или го заменяш."}]},"points":3,"required":true,"answer_key":{"correct":"c"},"feedback":{"explanation":"Причината за избора: Спираш този кадър, докато докажеш право и точност, или го заменяш.\n\nПървият слаб ход — Публикуваш и чакаш оплакване. — пропуска тази проверка: Друг човек може да проследи всеки значим елемент и да възпроизведе решението за публикация без устни допълнения. Вторият — Изтриваш метаданните му. — оставя този риск: Доставяш mp4 без произход, а при въпрос за лицето казваш „генераторът го направи“. В работна ситуация поправката е: Спри публикацията, докато произходът, правата и фактите могат да се проверят; замени неизвестните активи. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":14,"block_key":"quiz_2","block_type":"quiz","title":"Провери решението","content":{"question":"Коя е финалната проверка?","options":[{"id":"a","label":"Пълен export на целеви екран, маркирани AI употреби, права и одобрение."},{"id":"b","label":"Само preview в editor-а."},{"id":"c","label":"Само автоматичен score от инструмента."}]},"points":3,"required":true,"answer_key":{"correct":"a"},"feedback":{"explanation":"Причината за избора: Пълен export на целеви екран, маркирани AI употреби, права и одобрение.\n\nПървият слаб ход — Само preview в editor-а. — пропуска тази проверка: Друг човек може да проследи всеки значим елемент и да възпроизведе решението за публикация без устни допълнения. Вторият — Само автоматичен score от инструмента. — оставя този риск: Доставяш mp4 без произход, а при въпрос за лицето казваш „генераторът го направи“. В работна ситуация поправката е: Спри публикацията, докато произходът, правата и фактите могат да се проверят; замени неизвестните активи. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":15,"block_key":"scenario_2","block_type":"scenario","title":"Поправи грешния изход","content":{"prompt":"Виждаш тази грешка: Доставяш mp4 без произход, а при въпрос за лицето казваш „генераторът го направи“. Как продължаваш?","options":[{"id":"a","label":"Продължаваш без проверка и наричаш тази версия окончателна."},{"id":"b","label":"Спри публикацията, докато произходът, правата и фактите могат да се проверят; замени неизвестните активи."},{"id":"c","label":"Скриваш проблема в доклада и обещаваш резултат без доказателство."}]},"points":3,"required":true,"answer_key":{"correct":"b"},"feedback":{"explanation":"Причината за избора: Спри публикацията, докато произходът, правата и фактите могат да се проверят; замени неизвестните активи.\n\nПървият слаб ход — Продължаваш без проверка и наричаш тази версия окончателна. — пропуска тази проверка: Друг човек може да проследи всеки значим елемент и да възпроизведе решението за публикация без устни допълнения. Вторият — Скриваш проблема в доклада и обещаваш резултат без доказателство. — оставя този риск: Доставяш mp4 без произход, а при въпрос за лицето казваш „генераторът го направи“. В работна ситуация поправката е: Спри публикацията, докато произходът, правата и фактите могат да се проверят; замени неизвестните активи. Не обявявай успех преди да имаш изходния файл, измерване или позволено потвърждение."},"scoring":{"mode":"single_choice"}},{"position":16,"block_key":"sequence_sort","block_type":"sequence_sort","title":"Подреди зависимостите","content":{"instruction":"Подреди работните решения така, че проверката да предхожда окончателното предаване.","items":[{"id":"s4","text":"Изгледай целия export на целевия екран, добави обозначения и предай manifest с отговорник."},{"id":"s3","text":"Направи фактологичен, визуален, звуков и правен преглед с конкретни отметки."},{"id":"s2","text":"Запази оригиналите, входовете и версията на всяка генерирана част."},{"id":"s1","text":"Избери разрешен кратък проект и ограничен AI обхват."}]},"points":3,"required":true,"answer_key":{"order":["s1","s2","s3","s4"]},"feedback":{"explanation":"Редът следва зависимостите:\n1. Избери разрешен кратък проект и ограничен AI обхват.\n2. Запази оригиналите, входовете и версията на всяка генерирана част.\n3. Направи фактологичен, визуален, звуков и правен преглед с конкретни отметки.\n4. Изгледай целия export на целевия екран, добави обозначения и предай manifest с отговорник."},"scoring":{"mode":"exact_order"}},{"position":17,"block_key":"summary","block_type":"summary","title":"Какво вземаш в следващата задача","content":{"takeaways":["AI процесът е готов, когато входовете, решенията и проверките могат да бъдат проследени. Събери малък пакет: бриф, разрешени активи, версия на скрипта, списък на AI употребите, оригинали, фактологична проверка, права, нужни обозначения, финален export и приемане. Използвай AI само там, където качеството или скоростта са измеримо по-добри след човешки преглед. Не бъркай гладка генерация с готов продукт.","Спри публикацията, докато произходът, правата и фактите могат да се проверят; замени неизвестните активи.","Друг човек може да проследи всеки значим елемент и да възпроизведе решението за публикация без устни допълнения."],"nextStep":"Направи 20–40-секунден разрешен откъс и предай заедно с него списък на AI употребите, оригинали, права, проверени факти, нужни етикети и QA отчет."},"points":1,"required":true}]}]$curriculum$::jsonb;
  lesson record;
  block jsonb;
  lesson_uuid uuid;
  version_uuid uuid;
  block_uuid uuid;
  report jsonb;
  progress_before integer;
  attempts_before integer;
  progress_after integer;
  attempts_after integer;
  new_lessons integer;
  new_keys integer;
  release_note text := 'Перфектното видео, модули 10–12: първо практическо издание v7';
BEGIN
  LOCK TABLE public.academy_lessons IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.academy_lesson_progress IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.academy_lesson_attempts_v2 IN SHARE ROW EXCLUSIVE MODE;

  IF jsonb_typeof(payload)<>'array' OR jsonb_array_length(payload)<>40 THEN
    RAISE EXCEPTION 'Expected 40 lesson records';
  END IF;
  IF (SELECT count(DISTINCT p.lesson_id) FROM jsonb_to_recordset(payload)
      AS p(lesson_id text))<>40 OR
     (SELECT array_agg(p.lesson_id ORDER BY p.lesson_id)
      FROM jsonb_to_recordset(payload) AS p(lesson_id text))
       <>ARRAY['pv10-01','pv10-02','pv10-03','pv10-04','pv10-05','pv10-06','pv10-07','pv10-08','pv10-09','pv10-10','pv10-11','pv10-12','pv10-13','pv10-14','pv10-15','pv10-16','pv11-01','pv11-02','pv11-03','pv11-04','pv11-05','pv11-06','pv11-07','pv11-08','pv11-09','pv11-10','pv11-11','pv11-12','pv11-13','pv11-14','pv11-15','pv11-16','pv12-01','pv12-02','pv12-03','pv12-04','pv12-05','pv12-06','pv12-07','pv12-08']::text[] THEN
    RAISE EXCEPTION 'Unexpected or duplicate lesson IDs';
  END IF;
  IF (SELECT ARRAY[
        count(*) FILTER (WHERE p.module_id='s02-m10')::integer,
        count(*) FILTER (WHERE p.module_id='s02-m11')::integer,
        count(*) FILTER (WHERE p.module_id='s02-m12')::integer
      ] FROM jsonb_to_recordset(payload) AS p(module_id text))
      <>ARRAY[16,16,8] THEN
    RAISE EXCEPTION 'Unexpected module distribution';
  END IF;
  IF EXISTS (SELECT 1 FROM public.academy_lessons
             WHERE module_id IN ('s02-m10','s02-m11','s02-m12')) THEN
    RAISE EXCEPTION 'Modules 10–12 already contain lessons; review rather than overwrite';
  END IF;
  IF EXISTS (SELECT 1 FROM public.interactive_lessons
             WHERE module_id IN ('s02-m10','s02-m11','s02-m12')) THEN
    RAISE EXCEPTION 'Legacy lessons exist for this catalog; review before release';
  END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_to_recordset(payload)
      AS p(module_id text, lesson_id text, title text, objective text,
           hook text, estimated_minutes integer, blocks jsonb)
    WHERE p.module_id<>('s02-m'||substring(p.lesson_id from 3 for 2))
       OR btrim(coalesce(p.title,''))=''
       OR btrim(coalesce(p.objective,''))=''
       OR btrim(coalesce(p.hook,''))=''
       OR p.estimated_minutes NOT BETWEEN 25 AND 50
       OR jsonb_typeof(p.blocks)<>'array'
       OR jsonb_array_length(p.blocks) NOT BETWEEN 13 AND 20
       OR (SELECT count(*) FROM jsonb_array_elements(p.blocks) b
           WHERE b ? 'answer_key')<>5
       OR (SELECT count(*) FROM jsonb_array_elements(p.blocks) b
           WHERE b->>'block_type'='quiz')<>2
       OR (SELECT count(*) FROM jsonb_array_elements(p.blocks) b
           WHERE b->>'block_type'='scenario')<>2
       OR (SELECT count(*) FROM jsonb_array_elements(p.blocks) b
           WHERE b->>'block_type'='sequence_sort')<>1
       OR EXISTS (SELECT 1 FROM jsonb_array_elements(p.blocks) b
           WHERE b->>'block_type' IN (
             'practical_response','reflection','homework','submission','prompt_builder'
           ))
  ) THEN
    RAISE EXCEPTION 'Content, lesson structure or assessment guard failed';
  END IF;

  SELECT count(*) INTO progress_before FROM public.academy_lesson_progress;
  SELECT count(*) INTO attempts_before FROM public.academy_lesson_attempts_v2;

  FOR lesson IN SELECT * FROM jsonb_to_recordset(payload) AS p(
      module_id text,lesson_id text,title text,subtitle text,objective text,
      hook text,estimated_minutes integer,blocks jsonb)
      ORDER BY module_id,lesson_id
  LOOP
    INSERT INTO public.academy_lessons(module_id,lesson_id,status)
    VALUES (lesson.module_id,lesson.lesson_id,'draft')
    RETURNING id INTO lesson_uuid;

    INSERT INTO public.academy_lesson_versions(
      academy_lesson_id,version_number,title,subtitle,duration,objective,
      hook,estimated_minutes,source_kind,change_note)
    VALUES (lesson_uuid,1,lesson.title,lesson.subtitle,
            lesson.estimated_minutes::text||' минути',lesson.objective,
            lesson.hook,lesson.estimated_minutes,'editor',release_note)
    RETURNING id INTO version_uuid;

    FOR block IN SELECT value FROM jsonb_array_elements(lesson.blocks)
    LOOP
      INSERT INTO public.academy_lesson_blocks(
        version_id,block_key,"position",block_type,title,content,required,points)
      VALUES (version_uuid,block->>'block_key',(block->>'position')::integer,
              block->>'block_type',block->>'title',block->'content',
              (block->>'required')::boolean,(block->>'points')::integer)
      RETURNING id INTO block_uuid;

      IF block ? 'answer_key' THEN
        INSERT INTO academy_private.lesson_block_keys(
          block_id,answer_key,feedback,scoring)
        VALUES (block_uuid,block->'answer_key',block->'feedback',block->'scoring');
        IF block->>'block_type' IN ('quiz','scenario') AND NOT EXISTS (
          SELECT 1 FROM jsonb_array_elements(block->'content'->'options') o
          WHERE o->>'id'=block->'answer_key'->>'correct'
        ) THEN
          RAISE EXCEPTION 'Invalid answer key: % / %',
            lesson.lesson_id,block->>'block_key';
        END IF;
        IF block->>'block_type'='sequence_sort' AND
            jsonb_array_length(block->'answer_key'->'order')<>
            jsonb_array_length(block->'content'->'items') THEN
          RAISE EXCEPTION 'Invalid sequence key in %',lesson.lesson_id;
        END IF;
      END IF;
    END LOOP;

    report:=academy_private.lesson_validation(version_uuid);
    IF jsonb_array_length(report->'errors')<>0 OR
       jsonb_array_length(report->'warnings')<>0 THEN
      RAISE EXCEPTION 'Lesson % failed validation: %',lesson.lesson_id,report;
    END IF;
    UPDATE public.academy_lesson_versions SET validation=report
      WHERE id=version_uuid;
    UPDATE public.academy_lessons SET status='published',
      published_version_id=version_uuid,draft_version_id=version_uuid,
      updated_at=clock_timestamp()
      WHERE id=lesson_uuid;
    INSERT INTO public.academy_lesson_audit(
      academy_lesson_id,version_id,actor_id,action,details)
    VALUES (lesson_uuid,version_uuid,NULL,'published',
      jsonb_build_object('source','perfect_video_v7',
                         'previous_version_id',NULL,
                         'preserved_existing_progress',true));
  END LOOP;

  SELECT count(*),count(*) FILTER (WHERE l.status='published'
      AND l.published_version_id IS NOT NULL AND
      l.draft_version_id=l.published_version_id)
    INTO new_lessons,progress_after
  FROM public.academy_lessons l
  WHERE l.module_id IN ('s02-m10','s02-m11','s02-m12');
  IF new_lessons<>40 OR progress_after<>40 THEN
    RAISE EXCEPTION 'Publication incomplete: % / %',new_lessons,progress_after;
  END IF;
  SELECT count(*) INTO new_keys
  FROM academy_private.lesson_block_keys k
  JOIN public.academy_lesson_blocks b ON b.id=k.block_id
  JOIN public.academy_lesson_versions v ON v.id=b.version_id
  JOIN public.academy_lessons l ON l.id=v.academy_lesson_id
  WHERE l.module_id IN ('s02-m10','s02-m11','s02-m12')
    AND l.published_version_id=v.id;
  IF new_keys<>200 THEN
    RAISE EXCEPTION 'Expected 200 private answer keys; found %',new_keys;
  END IF;
  SELECT count(*) INTO progress_after FROM public.academy_lesson_progress;
  SELECT count(*) INTO attempts_after FROM public.academy_lesson_attempts_v2;
  IF progress_after<>progress_before OR attempts_after<>attempts_before THEN
    RAISE EXCEPTION 'Pre-existing learner records changed';
  END IF;
END
$release$;
